class TempFileWrapper:
    """
    Wrapper for file objects that automatically deletes the temp file when closed.
    This is necessary for cross-platform compatibility (especially Windows) where
    temp files need to be explicitly cleaned up after FileResponse finishes sending.
    """
    def __init__(self, file_obj, path_to_delete):
        self.file_obj = file_obj
        self.path_to_delete = path_to_delete
    
    def read(self, size=-1):
        return self.file_obj.read(size)
    
    def close(self):
        self.file_obj.close()
        # Delete the temp file after closing
        try:
            os.unlink(self.path_to_delete)
        except (OSError, PermissionError):
            pass  # Already deleted or still locked
    
    def __enter__(self):
        return self
    
    def __exit__(self, *args):
        self.close()
    
    def __getattr__(self, name):
        # Delegate all other attributes to the wrapped file object
        return getattr(self.file_obj, name)


