def load_image_from_bytes(file_bytes):
    image = Image.open(io.BytesIO(file_bytes))
    return np.array(image)


class FileUploadView(APIView):
    parser_classes = (MultiPartParser, FormParser)

    def post(self, request, *args, **kwargs):
        target_folder = request.data.get('target_folder', '.')
        file = request.FILES['file']
        save_path = os.path.join(target_folder, file.name)
        with open(save_path, 'wb+') as destination:
            for chunk in file.chunks():
                destination.write(chunk)
        return Response({'message': 'File uploaded successfully'})
    

def find_absolute_paths(relative_paths):
    home_dir = os.path.expanduser('~')
    absolute_paths = []
    
    unique_parent_folders = extract_folder_paths(relative_paths)
    # Group relative paths by unique parent folder using a dictionary
    paths_by_parent = {folder: [] for folder in unique_parent_folders}
    for rel_path in relative_paths:
        parent_folder = os.path.dirname(rel_path)
        paths_by_parent[parent_folder].append(rel_path)

    for the_paths in paths_by_parent.values():
        counter = 0
        for rel_path in the_paths:
            # Remove leading slash if present
            if rel_path.startswith('/'):
                rel_path = rel_path[1:]
            search_pattern = os.path.join(home_dir, '**', rel_path)
            matches = glob.glob(search_pattern, recursive=True)
            if len(matches) == 0:
                return f"No matches found for {rel_path}"
            elif len(matches) > 1:
                # Resolve real paths to handle symbolic links
                real_paths = list(set(os.path.realpath(match) for match in matches))
                print(real_paths)
                if len(real_paths) > 1:
                    return f"Multiple matches found for {rel_path}: {real_paths}. Please resolve manually."
                else:
                    absolute_paths.append(real_paths[0])
            else:
                absolute_paths.append(os.path.realpath(matches[0]))
            counter+=1
            if counter>=2:
                break
        
        
    return absolute_paths

def extract_folder_paths(file_paths):
    folder_paths = list(set(os.path.dirname(path) for path in file_paths))
    return folder_paths


def cleanup_memory():
    """More aggressively clean up memory to prevent out-of-memory errors."""
    # First, collect obvious garbage
    gc.collect()
    
    # Force Python to return memory to OS
    if hasattr(os, 'malloc_trim'):  # On Linux
        os.malloc_trim(0)
    
    # Print memory usage for debugging
    mem = psutil.virtual_memory()
    process = psutil.Process(os.getpid())
    process_memory = process.memory_info().rss / 1024 / 1024 / 1024
    print(f"Process memory: {process_memory:.2f} GB, Available system memory: {mem.available/1024/1024/1024:.2f} GB")
    # --- end of memory cleanup ---



def has_elastic_registration(scan_name, directory):
    """
    Check if a scan has completed elastic registration (latest edit is elastic).
    
    Args:
        scan_name (str): Name of the scan to check
        directory (str): Root project directory containing 'extracted' folder
    
    Returns:
        bool: True if scan has elastic registration as latest edit, False otherwise
    """
    try:

        # Load .json metadata to check if the scan is marked as the reference scan, if so, check if there are any elastic edits on any of the subjects on the project, if yes, this means that the reference scan has been used in elastic registration and thus must be locked in by returning True.
        json_path = os.path.join(directory, "extracted", scan_name, f"{scan_name}.json")
        with open(json_path, 'r') as jf:
            metadata = json.load(jf)
            if metadata.get('reference', False):
                # Check if there are any elastic_to in the json metadata on any of the subjects on the project matching the scan_name
                for subject in os.listdir(os.path.join(directory, "extracted")):
                    if subject == "project_settings.json" or not os.path.isdir(os.path.join(directory, "extracted", subject)):
                        continue
                    json_path = os.path.join(directory, "extracted", subject, f"{subject}.json")
                    with open(json_path, 'r') as jf:
                        metadata = json.load(jf)
                        if metadata.get('elastic_to', "none") == scan_name:
                            return True
                

        # Check if the scan is in the atlas (special case)
        if scan_name == "atlas":
            # Assume atlas as always elastic
            return True
        else:
            scan_path = os.path.join(directory, "extracted", scan_name)
            edit_pattern = os.path.join(scan_path, f"{scan_name}_edit_*_*.nii.gz")
        
        # Return False if scan directory doesn't exist
        if not os.path.isdir(scan_path):
            return False
        
        # Get all edit files
        edit_files = glob.glob(edit_pattern)
        
        # If no edit files exist, there's no elastic registration
        if not edit_files:
            return False
        
        # Extract edit numbers from all files
        edit_numbers = []
        for file in edit_files:
            try:
                num_str = file.split('_edit_')[1].split('_')[0]
                edit_numbers.append(int(num_str))
            except (IndexError, ValueError):
                continue
        
        # If no valid edit numbers found, no elastic registration
        if not edit_numbers:
            return False
        
        # Get the latest edit number
        latest_edit_num = max(edit_numbers)
        
        # Check if the latest edit is elastic
        latest_edit_pattern = os.path.join(scan_path, f"{scan_name}_edit_{latest_edit_num}_*elastic.nii.gz")
        
        # Return True only if elastic file exists for latest edit
        return len(glob.glob(latest_edit_pattern)) > 0
        
    except Exception as e:
        print(f"Error checking elastic registration for {scan_name}: {e}")
        return False





class FileCopyView(APIView):
    def post(self, request, *args, **kwargs):
        source_paths = extract_folder_paths(find_absolute_paths(request.data.get('source_paths')))
        target_folder = request.data.get('target_folder')

        if not source_paths or not target_folder:
            return Response({'error': 'Source path and target folder are required.'}, status=status.HTTP_400_BAD_REQUEST)
        
        if not isinstance(source_paths, list):
            return Response({'error': source_paths}, status=status.HTTP_400_BAD_REQUEST)
        
        try:
            for source_path in source_paths:
                shutil.copytree(source_path, os.path.join(target_folder, os.path.basename(source_path)))
            return Response({'message': 'Directories copied successfully'})
        except Exception as e:
            return Response({'error': str(e)}, status=status.HTTP_500_INTERNAL_SERVER_ERROR)

class ReportBadFileView(APIView):
    def post(self, request, *args, **kwargs):
        directory = request.data.get('directory')
        filename = request.data.get('filename')
        faulty = request.data.get('faulty')

        # Update the faulty status in the JSON file
        metadata_json_path = os.path.join(directory, "extracted", filename, f"{filename}.json")
        with open(metadata_json_path, 'r') as json_file:
            metadata_data = json.load(json_file)
            # Ensure faulty is stored as a boolean, not a string
            metadata_data['faulty'] = bool(faulty) if faulty is not None else False
        with open(metadata_json_path, 'w') as json_file:
            json.dump(metadata_data, json_file, indent=4)  # Add indent for readability

        return Response({'message': 'File reported successfully'})


class FlagSubjectsView(APIView):
    """
    Set metadata 'flag' on one or more subject JSON files under extracted/<name>/<name>.json.
    Expects: directory (project root), filenames (list of subject folder names), flag (bool, default True).
    """

    def post(self, request, *args, **kwargs):
        directory = request.data.get('directory')
        filenames = request.data.get('filenames')
        flag = request.data.get('flag', True)

        if not directory:
            return Response({'error': 'directory is required.'}, status=status.HTTP_400_BAD_REQUEST)
        if filenames is None:
            return Response({'error': 'filenames is required.'}, status=status.HTTP_400_BAD_REQUEST)
        if not isinstance(filenames, list):
            filenames = [filenames]
        if len(filenames) == 0:
            return Response({'error': 'filenames must be a non-empty list.'}, status=status.HTTP_400_BAD_REQUEST)

        flag_bool = bool(flag)
        errors = []
        updated = []
        confirmed_flags = {}

        for filename in filenames:
            if not filename or not isinstance(filename, str):
                errors.append({'filename': filename, 'error': 'invalid name'})
                continue
            metadata_json_path = os.path.join(directory, "extracted", filename, f"{filename}.json")
            if not os.path.isfile(metadata_json_path):
                errors.append({'filename': filename, 'error': 'metadata json not found'})
                continue
            try:
                with open(metadata_json_path, 'r') as json_file:
                    metadata_data = json.load(json_file)
                metadata_data['flag'] = flag_bool
                with open(metadata_json_path, 'w') as json_file:
                    json.dump(metadata_data, json_file, indent=4)
                # Re-read to confirm the persisted value
                with open(metadata_json_path, 'r') as json_file:
                    confirmed_data = json.load(json_file)
                confirmed_flags[filename] = confirmed_data.get('flag', flag_bool)
                updated.append(filename)
            except (json.JSONDecodeError, OSError) as e:
                errors.append({'filename': filename, 'error': str(e)})

        if not updated and errors:
            return Response(
                {'error': 'No metadata files updated', 'details': errors},
                status=status.HTTP_400_BAD_REQUEST,
            )
        return Response({
            'message': 'Flag updated successfully',
            'updated': updated,
            'errors': errors,
            'confirmed_flags': confirmed_flags,
        })


class LinkScansView(APIView):
    """
    Set or clear metadata 'linked_to' on subject JSON files under extracted/<name>/<name>.json.

    Expects:
      directory (project root),
      groups (optional list of {main, members}),
      unlink (optional list of subject names).

    Main image: linked_to equals its own name.
    Linked image: linked_to equals the main scan's name.
    Unlinked: field removed.
    All members in a group must share identical full-res NIfTI dimensions (x, y, z).
    """

    def _metadata_path(self, directory, scan_name):
        if scan_name == "atlas":
            return os.path.join(resolve_atlas_dir(directory), "atlas.json")
        return os.path.join(directory, "extracted", scan_name, f"{scan_name}.json")

    def _full_res_nifti_path(self, directory, scan_name):
        if scan_name == "atlas":
            return os.path.join(resolve_atlas_dir(directory), "atlas.nii.gz")
        return os.path.join(directory, "extracted", scan_name, f"{scan_name}.nii.gz")

    def _read_dims(self, directory, scan_name):
        nifti_path = self._full_res_nifti_path(directory, scan_name)
        if not os.path.isfile(nifti_path):
            return None, f"NIfTI not found for {scan_name}"
        try:
            nifti_image = nib.load(nifti_path)
            shape = nifti_image.header.get_data_shape()
            return [int(v) for v in shape[:3]], None
        except Exception as e:
            return None, f"Failed to read dims for {scan_name}: {e}"

    def _load_metadata(self, directory, scan_name):
        metadata_path = self._metadata_path(directory, scan_name)
        if not os.path.isfile(metadata_path):
            return None, metadata_path, f"metadata json not found for {scan_name}"
        try:
            with open(metadata_path, 'r') as json_file:
                return json.load(json_file), metadata_path, None
        except (json.JSONDecodeError, OSError) as e:
            return None, metadata_path, str(e)

    def _write_metadata(self, metadata_path, metadata_data):
        with open(metadata_path, 'w') as json_file:
            json.dump(metadata_data, json_file, indent=4)

    def post(self, request, *args, **kwargs):
        directory = request.data.get('directory')
        groups = request.data.get('groups') or []
        unlink = request.data.get('unlink') or []

        if not directory:
            return Response({'error': 'directory is required.'}, status=status.HTTP_400_BAD_REQUEST)
        if not isinstance(groups, list):
            return Response({'error': 'groups must be a list.'}, status=status.HTTP_400_BAD_REQUEST)
        if not isinstance(unlink, list):
            unlink = [unlink]

        errors = []
        updated = []
        confirmed_links = {}

        # Validate all groups before writing anything (atomic: any failure rejects all groups)
        validated_groups = []
        for group in groups:
            if not isinstance(group, dict):
                errors.append({'group': group, 'error': 'invalid group object'})
                continue
            main = group.get('main')
            members = group.get('members')
            if not main or not isinstance(main, str):
                errors.append({'group': group, 'error': 'main is required'})
                continue
            if not isinstance(members, list) or len(members) < 2:
                errors.append({'main': main, 'error': 'members must be a list with at least 2 scans'})
                continue
            members = [m for m in members if isinstance(m, str) and m]
            if main not in members:
                members = [main] + members
            if len(set(members)) < 2:
                errors.append({'main': main, 'error': 'members must include at least 2 distinct scans'})
                continue

            dims_by_member = {}
            group_error = None
            for member in members:
                _metadata_data, _metadata_path, meta_err = self._load_metadata(directory, member)
                if meta_err:
                    group_error = meta_err
                    break
                dims, dim_err = self._read_dims(directory, member)
                if dim_err:
                    group_error = dim_err
                    break
                dims_by_member[member] = dims

            if group_error:
                errors.append({'main': main, 'error': group_error})
                continue

            reference_dims = dims_by_member[main]
            mismatched = [
                f"{name} {dims}" for name, dims in dims_by_member.items()
                if dims != reference_dims
            ]
            if mismatched:
                errors.append({
                    'main': main,
                    'error': (
                        f"Dimension mismatch: main {main} has {reference_dims}; "
                        f"mismatched members: {', '.join(mismatched)}"
                    ),
                })
                continue

            validated_groups.append({'main': main, 'members': members, 'dims': reference_dims})

        if groups and errors:
            return Response(
                {'error': 'Link validation failed; no changes written', 'details': errors},
                status=status.HTTP_400_BAD_REQUEST,
            )
        if not groups and not unlink:
            return Response({
                'message': 'No link changes',
                'updated': [],
                'errors': [],
                'confirmed_links': {},
            })

        # Unlink first
        for filename in unlink:
            if not filename or not isinstance(filename, str):
                errors.append({'filename': filename, 'error': 'invalid name'})
                continue
            metadata_data, metadata_path, meta_err = self._load_metadata(directory, filename)
            if meta_err:
                errors.append({'filename': filename, 'error': meta_err})
                continue
            try:
                if 'linked_to' in metadata_data:
                    del metadata_data['linked_to']
                    self._write_metadata(metadata_path, metadata_data)
                confirmed_links[filename] = None
                if filename not in updated:
                    updated.append(filename)
            except OSError as e:
                errors.append({'filename': filename, 'error': str(e)})

        # Write groups
        for group in validated_groups:
            main = group['main']
            for member in group['members']:
                metadata_data, metadata_path, meta_err = self._load_metadata(directory, member)
                if meta_err:
                    errors.append({'filename': member, 'error': meta_err})
                    continue
                try:
                    metadata_data['linked_to'] = main
                    self._write_metadata(metadata_path, metadata_data)
                    confirmed_links[member] = main
                    if member not in updated:
                        updated.append(member)
                except OSError as e:
                    errors.append({'filename': member, 'error': str(e)})

        if not updated and errors:
            return Response(
                {'error': 'No metadata files updated', 'details': errors},
                status=status.HTTP_400_BAD_REQUEST,
            )
        return Response({
            'message': 'Linked scans updated successfully',
            'updated': updated,
            'errors': errors,
            'confirmed_links': confirmed_links,
        })


class ListDirectoriesView(APIView):
    def get(self, request, *args, **kwargs):
        path = unquote(request.query_params.get('path', '~'))
        try:
            if path == "root":
                path = "/"

            # Expand the '~' to the user's home directory
            path = os.path.expanduser(path)

            directories = []
            files = []
            sizes = []

            if not os.path.isdir(path):
                response_data = {
                    'directories': [],
                    'files': [],
                    'sizes': [],
                    'path': os.path.abspath(path),
                    'missing': True,
                }
                response_json = json.dumps(response_data, ensure_ascii=False).encode('utf-8', 'replace').decode('utf-8')
                return Response(json.loads(response_json))

            try:
                for item in os.listdir(path):
                    if "extracted" == os.path.basename(path):
                        # Only process directories inside "extracted"
                        item_path = os.path.join(path, item)
                        if os.path.isdir(item_path):
                            for item2 in os.listdir(item_path):
                                item2_path = os.path.join(item_path, item2)
                                try:
                                    if os.path.isdir(item2_path):
                                        directories.append(item2)
                                    elif os.path.isfile(item2_path):
                                        files.append(item2)
                                        sizes.append(os.path.getsize(item2_path))
                                except:
                                    # Skip files or directories that cannot be accessed
                                    continue
                        # If not a directory (e.g., project_settings.json), skip
                    else:
                        item_path = os.path.join(path, item)
                        try:
                            if os.path.isdir(item_path) and not item.startswith('.'):
                                directories.append(item)
                            elif os.path.isfile(item_path) and not item.startswith('.'):
                                files.append(item)
                                sizes.append(os.path.getsize(item_path))
                        except:
                            # Skip files or directories that cannot be accessed
                            continue
            except: 
                response_data = {
                    'directories': directories,
                    'files': ['-- RESTRICTED PATH --'],
                    'sizes': ['-- RESTRICTED PATH --'],
                    'path': os.path.abspath(path)
                }

                response_json = json.dumps(response_data, ensure_ascii=False).encode('utf-8', 'replace').decode('utf-8')
                return Response(json.loads(response_json))
            

            response_data = {
                'directories': directories,
                'files': files,
                'sizes': sizes,
                'path': os.path.abspath(path)
            }
            
            response_json = json.dumps(response_data, ensure_ascii=False).encode('utf-8', 'replace').decode('utf-8')
            return Response(json.loads(response_json))

        except PermissionError:
            return Response({'error': 'Permission denied'}, status=403)
        except Exception as e:
            return Response({'error': str(e)}, status=400)


# 1x1 transparent PNG — used when a subject has no projection (common for older projects).
# Returning 200 avoids browser console 404 spam from <img> tags requesting /projection-png/.
_TRANSPARENT_1X1_PNG = base64.b64decode(
    'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII='
)


def _missing_projection_png_response():
    response = HttpResponse(_TRANSPARENT_1X1_PNG, content_type='image/png', status=200)
    response['Access-Control-Allow-Origin'] = '*'
    response['Access-Control-Expose-Headers'] = 'X-Aurora-Projection-Missing'
    response['X-Aurora-Projection-Missing'] = '1'
    response['Cache-Control'] = 'no-store'
    return response


class ProjectionPngView(APIView):
    def get(self, request, *args, **kwargs):
        directory = request.query_params.get('directory')
        scan_name = request.query_params.get('scan_name')
        edit = request.query_params.get('edit')
        side = request.query_params.get('side')

        if not directory or not scan_name or not edit:
            return Response({'error': 'directory, scan_name, and edit are required'}, status=status.HTTP_400_BAD_REQUEST)

        directory = os.path.abspath(os.path.expanduser(unquote(directory)))
        scan_name = os.path.basename(unquote(scan_name))
        edit = os.path.basename(unquote(edit))

        scan_dir = os.path.abspath(resolve_atlas_dir(directory)) if scan_name == 'atlas' else os.path.abspath(os.path.join(directory, 'extracted', scan_name))
        try:
            if os.path.commonpath([directory, scan_dir]) != directory:
                return Response({'error': 'Invalid scan path'}, status=status.HTTP_400_BAD_REQUEST)
        except ValueError:
            return Response({'error': 'Invalid scan path'}, status=status.HTTP_400_BAD_REQUEST)

        projection_suffix = '_projection_back.png' if side == 'back' else '_projection.png'
        lossy_projection_suffix = '_lossy_projection_back.png' if side == 'back' else '_lossy_projection.png'

        if edit.endswith('.ply'):
            projection_candidates = [
                os.path.join(scan_dir, edit.replace('.ply', projection_suffix)),
            ]
        else:
            lossy_edit = edit.replace('_edit_', '_lossy_edit_')
            raw_lossy_edit = edit.replace('.nii.gz', '_lossy.nii.gz')
            projection_candidates = [
                os.path.join(scan_dir, edit.replace('.nii.gz', projection_suffix)),
                os.path.join(scan_dir, lossy_edit.replace('.nii.gz', projection_suffix)),
                os.path.join(scan_dir, raw_lossy_edit.replace('.nii.gz', projection_suffix)),
                os.path.join(scan_dir, edit.replace('.nii.gz', lossy_projection_suffix)),
                os.path.join(scan_dir, f'{edit}{lossy_projection_suffix}'),
            ]

        projection_path = next(
            (
                path for path in projection_candidates
                if os.path.isfile(path) and path.lower().endswith('.png')
            ),
            None,
        )

        if projection_path is None:
            projection_path = resolve_mesh_projection_path(scan_dir, scan_name, edit=edit, side=side)

        if projection_path is None:
            # Missing projections are normal (especially older projects); do not 404.
            return _missing_projection_png_response()

        if not projection_path.lower().endswith('.png'):
            return _missing_projection_png_response()

        response = FileResponse(open(projection_path, 'rb'), content_type='image/png')
        response['Access-Control-Allow-Origin'] = '*'
        return response


class EnsureQuickGridProjectionPngsView(APIView):
    """Generate missing latest non-elastic edit projection PNGs for Quick Grid."""

    def _scan_storage(self, directory, scan_name):
        if scan_name == 'atlas':
            scan_dir = os.path.abspath(resolve_atlas_dir(directory))
            file_stem = 'atlas'
        else:
            scan_dir = os.path.abspath(os.path.join(directory, 'extracted', scan_name))
            file_stem = scan_name

        try:
            if os.path.commonpath([directory, scan_dir]) != directory:
                return None, None
        except ValueError:
            return None, None
        return scan_dir, file_stem

    def _lossy_edit_path(self, scan_dir, edit):
        lossy_edit = edit.replace('_edit_', '_lossy_edit_')
        if lossy_edit == edit:
            return None
        return os.path.join(scan_dir, lossy_edit)

    def _edit_path(self, scan_dir, edit):
        return os.path.join(scan_dir, edit)

    def _projection_pair_exists(self, scan_dir, edit):
        if edit.endswith('.ply'):
            return mesh_projection_pair_exists(scan_dir, edit)

        projection_suffixes = [
            ('_projection.png', '_projection_back.png'),
            ('_lossy_projection.png', '_lossy_projection_back.png'),
        ]
        lossy_edit = edit.replace('_edit_', '_lossy_edit_')
        for front_suffix, back_suffix in projection_suffixes:
            front_candidates = [
                os.path.join(scan_dir, edit.replace('.nii.gz', front_suffix)),
                os.path.join(scan_dir, lossy_edit.replace('.nii.gz', front_suffix)),
            ]
            back_candidates = [
                os.path.join(scan_dir, edit.replace('.nii.gz', back_suffix)),
                os.path.join(scan_dir, lossy_edit.replace('.nii.gz', back_suffix)),
            ]
            if any(os.path.isfile(path) for path in front_candidates) and any(os.path.isfile(path) for path in back_candidates):
                return True
        return False

    def _is_elastic_file(self, filename):
        return 'elastic' in os.path.basename(filename).lower()

    def _select_latest_edit_file(self, files, split_token, excluded_suffixes=()):
        edit_numbers = []
        for path in files:
            base = os.path.basename(path)
            if self._is_elastic_file(base) or any(base.endswith(suffix) for suffix in excluded_suffixes):
                continue
            try:
                edit_number = int(base.split(split_token)[1].split('_')[0])
            except (IndexError, ValueError):
                continue
            edit_numbers.append((edit_number, path))

        if not edit_numbers:
            return None

        latest_edit_number = max(edit_numbers, key=lambda item: item[0])[0]
        matching_files = [
            path for number, path in edit_numbers
            if number == latest_edit_number
        ]
        return sorted(matching_files)[-1] if matching_files else None

    def _resolve_latest_non_elastic_edit_paths(self, scan_dir, file_stem):
        ply_edit_name, ply_edit_path = resolve_latest_preserved_mesh_edit(scan_dir, file_stem)
        if ply_edit_path:
            is_preserved = is_preserved_mesh_scan_dir(scan_dir, file_stem)
            has_mesh_projections = bool(resolve_preserved_mesh_projection_edit(scan_dir, file_stem))
            has_primary_nifti = os.path.isfile(os.path.join(scan_dir, f"{file_stem}.nii.gz"))
            if is_preserved or has_mesh_projections or not has_primary_nifti:
                return {
                    'edit': ply_edit_name,
                    'lossy_edit_path': None,
                    'edit_path': ply_edit_path,
                    'ply_edit_path': ply_edit_path,
                    'resolved_from': 'ply_edit',
                }

        lossy_edit_path = self._select_latest_edit_file(
            glob.glob(os.path.join(scan_dir, f"{file_stem}_lossy_edit_*_*.nii.gz")),
            '_lossy_edit_',
            excluded_suffixes=('_lossy_inv.nii.gz', '_lossy_fwd.nii.gz'),
        )
        if lossy_edit_path:
            edit_name = os.path.basename(lossy_edit_path).replace('_lossy', '')
            return {
                'edit': edit_name,
                'lossy_edit_path': lossy_edit_path,
                'edit_path': os.path.join(scan_dir, edit_name),
                'resolved_from': 'lossy_edit',
            }

        edit_path = self._select_latest_edit_file(
            glob.glob(os.path.join(scan_dir, f"{file_stem}_edit_*_*.nii.gz")),
            '_edit_',
            excluded_suffixes=('_inv.nii.gz', '_fwd.nii.gz'),
        )
        if edit_path:
            edit_name = os.path.basename(edit_path)
            return {
                'edit': edit_name,
                'lossy_edit_path': self._lossy_edit_path(scan_dir, edit_name),
                'edit_path': edit_path,
                'resolved_from': 'edit',
            }

        original_lossy_path = os.path.join(scan_dir, f"{file_stem}_lossy.nii.gz")
        original_path = os.path.join(scan_dir, f"{file_stem}.nii.gz")
        if os.path.isfile(original_lossy_path) or os.path.isfile(original_path):
            return {
                'edit': f"{file_stem}.nii.gz",
                'lossy_edit_path': original_lossy_path if os.path.isfile(original_lossy_path) else None,
                'edit_path': original_path,
                'resolved_from': 'original',
            }

        projection_edit = self._resolve_latest_non_elastic_projection_edit(scan_dir, file_stem)
        if projection_edit:
            return {
                'edit': projection_edit,
                'lossy_edit_path': self._lossy_edit_path(scan_dir, projection_edit),
                'edit_path': os.path.join(scan_dir, projection_edit),
                'resolved_from': 'projection_png',
            }

        ply_edit_name, ply_edit_path = resolve_latest_preserved_mesh_edit(scan_dir, file_stem)
        if ply_edit_path:
            return {
                'edit': ply_edit_name,
                'lossy_edit_path': None,
                'edit_path': ply_edit_path,
                'ply_edit_path': ply_edit_path,
                'resolved_from': 'ply_edit',
            }

        return {
            'edit': '',
            'lossy_edit_path': None,
            'edit_path': None,
            'resolved_from': 'none',
        }

    def _resolve_latest_non_elastic_projection_edit(self, scan_dir, file_stem):
        edit_candidates = []

        for path in glob.glob(os.path.join(scan_dir, f"{file_stem}_lossy_edit_*_*_projection.png")):
            base = os.path.basename(path)
            if self._is_elastic_file(base) or base.endswith('_projection_back.png'):
                continue
            try:
                edit_number = int(base.split('_lossy_edit_')[1].split('_')[0])
            except (IndexError, ValueError):
                continue
            edit_name = base.replace('_lossy_edit_', '_edit_').replace('_projection.png', '.nii.gz')
            edit_candidates.append((edit_number, edit_name))

        if not edit_candidates:
            ply_projection_edit = resolve_preserved_mesh_projection_edit(scan_dir, file_stem)
            return ply_projection_edit or ''

        return max(edit_candidates, key=lambda item: item[0])[1]

    def _to_projection_uint8(self, image_data, assume_uint8=False):
        if image_data.ndim > 3:
            channel_axis = int(np.argmin(image_data.shape))
            image_data = np.take(image_data, 0, axis=channel_axis)

        if assume_uint8:
            return np.clip(image_data, 0, 255).astype(np.uint8)

        image_data = image_data.astype(np.float32, copy=False)
        data_min = float(np.nanmin(image_data))
        data_max = float(np.nanmax(image_data))
        if data_max <= data_min:
            return np.zeros(image_data.shape, dtype=np.uint8)

        return np.clip((image_data - data_min) * (255.0 / (data_max - data_min)), 0, 255).astype(np.uint8)

    def _ensure_projection_pair(self, source_path, projection_base_path, assume_uint8=False):
        projection_path = projection_base_path.replace('.nii.gz', '_projection.png')
        back_projection_path = projection_path.replace('_projection.png', '_projection_back.png')
        generated = False

        if not os.path.isfile(projection_path) or not os.path.isfile(back_projection_path):
            source_image = nib.load(source_path).get_fdata()
            image_data_8bit = self._to_projection_uint8(source_image, assume_uint8=assume_uint8)
            source_image = None
            gc.collect()
            generate_lossy_isometric_projection_png(image_data_8bit, projection_path)
            generated = True

        return generated

    def post(self, request, *args, **kwargs):
        directory = request.data.get('directory')
        subjects = request.data.get('subjects', [])

        if not directory or not isinstance(subjects, list):
            return Response({'error': 'directory and subjects are required'}, status=status.HTTP_400_BAD_REQUEST)

        directory = os.path.abspath(os.path.expanduser(unquote(directory)))
        results = []

        for subject in subjects:
            scan_name = os.path.basename(unquote(str(subject.get('scan_name', ''))))
            requested_edit = os.path.basename(unquote(str(subject.get('edit') or '')))
            result = {
                'scan_name': scan_name,
                'edit': requested_edit,
                'ready': False,
                'generated': False,
                'debug': {},
            }

            if not scan_name:
                result['error'] = 'Missing scan_name'
                results.append(result)
                continue

            scan_dir, file_stem = self._scan_storage(directory, scan_name)
            if not scan_dir or not os.path.isdir(scan_dir):
                result['error'] = 'Invalid scan path'
                result['debug'].update({
                    'scan_dir': scan_dir,
                    'file_stem': file_stem,
                })
                results.append(result)
                continue

            resolved = self._resolve_latest_non_elastic_edit_paths(scan_dir, file_stem)
            edit = resolved['edit']
            result['edit'] = edit
            result['debug'].update({
                'requested_edit': requested_edit,
                'resolved_from': resolved['resolved_from'],
                'file_stem': file_stem,
            })

            if not edit:
                result['error'] = 'No non-elastic edit found'
                result['debug']['scan_dir'] = scan_dir
                results.append(result)
                continue

            lossy_edit_path = resolved['lossy_edit_path']
            edit_path = resolved['edit_path']
            ply_edit_path = resolved.get('ply_edit_path')
            result['debug'].update({
                'scan_dir': scan_dir,
                'lossy_edit_path': lossy_edit_path,
                'edit_path': edit_path,
                'ply_edit_path': ply_edit_path,
                'projection_pair_exists': self._projection_pair_exists(scan_dir, edit),
            })
            if self._projection_pair_exists(scan_dir, edit):
                result['ready'] = True
                print(f"[QuickGrid] {scan_name}: using existing projection PNGs for {edit}")
                results.append(result)
                continue

            if ply_edit_path and os.path.isfile(ply_edit_path):
                try:
                    print(f"[QuickGrid] {scan_name}: generating mesh projection PNGs from {ply_edit_path}")
                    result['generated'] = ensure_mesh_projection_pngs(ply_edit_path)
                    result['ready'] = True
                    result['debug']['projection_pair_exists_after'] = self._projection_pair_exists(scan_dir, edit)
                except Exception as exc:
                    print(f"Error ensuring Quick Grid mesh projection for {scan_name}: {exc}")
                    result['error'] = str(exc)
                results.append(result)
                continue

            source_path = None
            projection_base_path = None
            assume_uint8 = False
            if lossy_edit_path and os.path.isfile(lossy_edit_path):
                source_path = lossy_edit_path
                projection_base_path = lossy_edit_path
                assume_uint8 = True
            elif os.path.isfile(edit_path):
                source_path = edit_path
                projection_base_path = edit_path
                assume_uint8 = False

            result['debug'].update({
                'source_path': source_path,
                'projection_base_path': projection_base_path,
                'source_is_lossy': assume_uint8,
            })

            if not source_path:
                result['error'] = 'No source NIfTI found for projection generation'
                print(f"[QuickGrid] {scan_name}: no source NIfTI for {edit}. Checked lossy={lossy_edit_path}, edit={edit_path}")
                results.append(result)
                continue

            try:
                print(f"[QuickGrid] {scan_name}: generating projection PNGs from {source_path}")
                result['generated'] = self._ensure_projection_pair(
                    source_path,
                    projection_base_path,
                    assume_uint8=assume_uint8,
                )
                result['ready'] = True
                result['debug']['projection_pair_exists_after'] = self._projection_pair_exists(scan_dir, edit)
            except Exception as exc:
                print(f"Error ensuring Quick Grid projection for {scan_name}: {exc}")
                result['error'] = str(exc)

            results.append(result)

        return Response({'subjects': results})


class QuickAccessPathsView(APIView):
    """Returns OS-specific quick access paths for file browser"""
    def get(self, request, *args, **kwargs):
        from pathlib import Path
        
        os_type = platform.system()
        
        quick_paths = {
            'home': str(Path.home()).replace('\\', '/'),
            'desktop': str(Path.home() / 'Desktop').replace('\\', '/'),
            'documents': str(Path.home() / 'Documents').replace('\\', '/'),
            'downloads': str(Path.home() / 'Downloads').replace('\\', '/'),
            'drives': [],
            'os_type': os_type
        }
        
        try:
            if os_type == 'Windows':
                # Get Windows drive letters
                partitions = psutil.disk_partitions()
                for partition in partitions:
                    # Check if it's a drive letter (e.g., C:\, D:\, or C:, D:)
                    # partition.device can be "C:\", "C:", etc.
                    device = partition.device
                    if len(device) >= 2 and device[1] == ':':
                        # Extract just the drive letter (e.g., "C:")
                        drive_letter = device[:2]
                        quick_paths['drives'].append({
                            'label': drive_letter,
                            'path': drive_letter + '/'
                        })
            elif os_type == 'Darwin':  # macOS
                quick_paths['volumes'] = '/Volumes'
                if os.path.exists('/mnt'):
                    quick_paths['mnt'] = '/mnt'
            else:  # Linux
                if os.path.exists('/media'):
                    quick_paths['media'] = '/media'
                if os.path.exists('/mnt'):
                    quick_paths['mnt'] = '/mnt'
                # Try to add /run/media/<username> if it exists
                username = os.getenv('USER', os.getenv('USERNAME', ''))
                if username:
                    run_media_path = f'/run/media/{username}'
                    if os.path.exists(run_media_path):
                        quick_paths['run_media'] = run_media_path
        except Exception as e:
            # Fail gracefully - just return home and common paths
            print(f"Error fetching quick access paths: {e}")
        
        return Response(quick_paths)


class GetGridView(APIView):
    def _scan_metadata_path(self, scan_name, directory):
        if scan_name == "atlas":
            return os.path.join(resolve_atlas_dir(directory), "atlas.json")
        return os.path.join(directory, "extracted", scan_name, f"{scan_name}.json")

    def _load_scan_metadata(self, scan_name, directory):
        metadata_json_path = self._scan_metadata_path(scan_name, directory)
        with open(metadata_json_path, 'r') as json_file:
            return json.load(json_file)

    def mesh_preview_up_to_date(self, scan_name, directory, ignoreElastic=False):
        if scan_name == "atlas":
            return False

        preview_json_path = os.path.join(directory, "extracted", scan_name, f"{scan_name}_preview.json")
        if not os.path.exists(preview_json_path):
            return False

        try:
            with open(preview_json_path, 'r') as json_file:
                preview_data = json.load(json_file)
                preview_last_edit = preview_data.get('last_edit')
                preview_threshold = preview_data.get('threshold')
                preview_timestamp = preview_data.get('last_edit_timestamp')
        except json.JSONDecodeError:
            print(f"Error reading preview JSON for {scan_name}. Assuming outdated.")
            return False

        scan_dir = os.path.join(directory, "extracted", scan_name)
        latest_edit_file, latest_edit_file_path = resolve_latest_preserved_mesh_edit(
            scan_dir,
            scan_name,
            ignore_elastic=ignoreElastic,
        )
        if not latest_edit_file_path:
            return False

        try:
            latest_edit_timestamp = os.path.getctime(latest_edit_file_path)
        except OSError:
            print(f"Error getting timestamp for {latest_edit_file_path}. Assuming outdated.")
            return False

        try:
            metadata_data = self._load_scan_metadata(scan_name, directory)
            threshold = metadata_data.get('threshold')
        except (FileNotFoundError, json.JSONDecodeError):
            print(f"Error reading metadata JSON for {scan_name}. Assuming outdated.")
            return False

        return (
            preview_last_edit == latest_edit_file
            and preview_threshold == threshold
            and preview_timestamp == latest_edit_timestamp
        )

    def create_mesh_preview_image(self, scan_name, directory, ignoreElastic=False):
        start_time = time.time()
        print(f"[{scan_name}] Starting preserved mesh preview generation...")

        scan_dir = os.path.join(directory, "extracted", scan_name)
        latest_edit_file, latest_edit_file_path = resolve_latest_preserved_mesh_edit(
            scan_dir,
            scan_name,
            ignore_elastic=ignoreElastic,
        )
        if not latest_edit_file_path:
            raise FileNotFoundError(f"No preserved mesh PLY found for {scan_name}")

        preview_json_path = os.path.join(scan_dir, f"{scan_name}_preview.json")
        metadata_data = self._load_scan_metadata(scan_name, directory)
        threshold = metadata_data.get('threshold')

        try:
            latest_edit_timestamp = os.path.getctime(latest_edit_file_path)
        except OSError:
            latest_edit_timestamp = time.time()

        with open(preview_json_path, 'w') as json_file:
            json.dump({
                'last_edit': latest_edit_file,
                'threshold': threshold,
                'last_edit_timestamp': latest_edit_timestamp,
                'histogram_data': None,
            }, json_file)

        image_data_bytes = generate_mesh_grid_preview_jpeg(latest_edit_file_path)
        preview_path = os.path.join(scan_dir, f"{scan_name}_preview.jpg")
        with open(preview_path, 'wb') as preview_file:
            preview_file.write(image_data_bytes)

        print(f"[{scan_name}] Preserved mesh preview saved to {preview_path} in {time.time() - start_time:.2f} seconds.")
        return image_data_bytes

    def preview_up_to_date(self, scan_name, directory, ignoreElastic = False):
        # Check if the preview image is up to date by comparing the {scan_name}_preview.json last_edit, threshold, and timestamp with the latest edit and threshold
        if scan_name == "atlas":
            preview_json_path = os.path.join(resolve_atlas_dir(directory), "atlas_preview.json")
        else:
            preview_json_path = os.path.join(directory, "extracted", scan_name, f"{scan_name}_preview.json")
            
        if os.path.exists(preview_json_path):
            try:
                with open(preview_json_path, 'r') as json_file:
                    preview_data = json.load(json_file)
                    preview_last_edit = preview_data.get('last_edit')
                    preview_threshold = preview_data.get('threshold')
                    preview_timestamp = preview_data.get('last_edit_timestamp')  # New field for timestamp
            except json.JSONDecodeError:
                print(f"Error reading preview JSON for {scan_name}. Assuming outdated.")
                return False

            if scan_name == "atlas":
                latest_edit_files = glob.glob(os.path.join(resolve_atlas_dir(directory), "atlas_edit_*_*.nii.gz"))
            else:
                latest_edit_files = glob.glob(os.path.join(directory, "extracted", scan_name, f"{scan_name}_edit_*_*.nii.gz"))
                
            if not latest_edit_files:
                if scan_name == "atlas":
                    original_file_path = os.path.join(resolve_atlas_dir(directory), "atlas.nii.gz")
                else:
                    original_file_path = os.path.join(directory, "extracted", scan_name, f"{scan_name}.nii.gz")
                    
                if os.path.exists(original_file_path):
                    latest_edit_file = os.path.basename(original_file_path)
                    latest_edit_file_path = original_file_path  # Store full path for timestamp
                else:
                    return False
            else:
                # Helper function to check if a file is an elastic edit
                def is_elastic_file(filename):
                    return 'elastic' in filename.lower()
                
                edit_numbers = []
                for f in latest_edit_files:
                    try:
                        # Skip elastic files if ignoreElastic is True
                        if ignoreElastic and is_elastic_file(f):
                            continue
                        num_str = f.split('_edit_')[1].split('_')[0]
                        edit_numbers.append((int(num_str), f))
                    except (IndexError, ValueError):
                        continue

                if not edit_numbers:
                    if scan_name == "atlas":
                        original_file_path = os.path.join(resolve_atlas_dir(directory), "atlas.nii.gz")
                    else:
                        original_file_path = os.path.join(directory, "extracted", scan_name, f"{scan_name}.nii.gz")
                        
                    if os.path.exists(original_file_path):
                        latest_edit_file = os.path.basename(original_file_path)
                        latest_edit_file_path = original_file_path
                    else:
                        return False
                else:
                    # Extract the latest edit number from tuples
                    latest_edit = max(edit_numbers, key=lambda x: x[0])[0]
                    if scan_name == "atlas":
                        latest_edit_file_pattern = os.path.join(resolve_atlas_dir(directory), f"atlas_edit_{latest_edit}_*.nii.gz")
                    else:
                        latest_edit_file_pattern = os.path.join(directory, "extracted", scan_name, f"{scan_name}_edit_{latest_edit}_*.nii.gz")
                        
                    matching_files = glob.glob(latest_edit_file_pattern)
                    if not matching_files:
                        return False
                    # Filter out displacement fields (inv and fwd) to get the actual image
                    image_files = [f for f in matching_files if not (f.endswith('_inv.nii.gz') or f.endswith('_fwd.nii.gz'))]
                    if image_files:
                        latest_edit_file_path = sorted(image_files)[-1]
                    else:
                        # Fallback to original logic if no filtered files found
                        latest_edit_file_path = sorted(matching_files)[-1]
                    latest_edit_file = os.path.basename(latest_edit_file_path)

            try:
                latest_edit_timestamp = os.path.getctime(latest_edit_file_path)
            except OSError:
                print(f"Error getting timestamp for {latest_edit_file_path}. Assuming outdated.")
                return False

            if scan_name == "atlas":
                metadata_json_path = os.path.join(resolve_atlas_dir(directory), "atlas.json")
            else:
                metadata_json_path = os.path.join(directory, "extracted", scan_name, f"{scan_name}.json")
                
            try:
                with open(metadata_json_path, 'r') as json_file:
                    metadata_data = json.load(json_file)
                    threshold = metadata_data.get('threshold')
            except (FileNotFoundError, json.JSONDecodeError):
                print(f"Error reading metadata JSON for {scan_name}. Assuming outdated.")
                return False

        
            return (preview_last_edit == latest_edit_file and 
                    preview_threshold == threshold and 
                    preview_timestamp == latest_edit_timestamp)
        else:
            return False

    # Helper function to resize images while preserving aspect ratio
    def resize_with_aspect_ratio(self, img, target_size, bg_color="black"):
        """
        Resizes a PIL Image to fit within a target size, preserving aspect ratio.
        This handles both scaling down and scaling up smaller images.
        Pads with a background color if necessary.
        """
        # Calculate aspect ratios
        img_aspect = img.width / img.height
        target_aspect = target_size[0] / target_size[1]
        
        if img_aspect > target_aspect:
            # Image is wider than target area: fit to target width
            new_width = target_size[0]
            new_height = int(new_width / img_aspect)
        else:
            # Image is taller than target area: fit to target height
            new_height = target_size[1]
            new_width = int(new_height * img_aspect)
            
        # Resize image (this scales up or down as needed)
        img_resized = img.resize((new_width, new_height), Image.Resampling.LANCZOS)
        
        new_img = Image.new("RGB", target_size, bg_color)
        # Calculate position to paste the scaled image (centered)
        paste_x = (target_size[0] - new_width) // 2
        paste_y = (target_size[1] - new_height) // 2
        new_img.paste(img_resized, (paste_x, paste_y))
        return new_img

    def create_preview_image(self, scan_name, directory, ignoreElastic=False):
        start_time = time.time() # Start timing
        print(f"[{scan_name}] Starting preview generation...")

        # 1. Load Data
        latest_edit = 0
        # Find the latest edit number for lossy files specifically
        if scan_name == "atlas":
            lossy_edit_files = glob.glob(os.path.join(resolve_atlas_dir(directory), "atlas_lossy_edit_*_*.nii.gz"))
            lossy_original_file = os.path.join(resolve_atlas_dir(directory), "atlas_lossy.nii.gz")
        else:
            lossy_edit_files = glob.glob(os.path.join(directory, "extracted", scan_name, f"{scan_name}_lossy_edit_*_*.nii.gz"))
            lossy_original_file = os.path.join(directory, "extracted", scan_name, f"{scan_name}_lossy.nii.gz")

        latest_lossy_edit_file_path = lossy_original_file # Default to original lossy file
        latest_edit_file_identifier = os.path.basename(lossy_original_file).replace("_lossy", "") # Identifier for preview.json (points to non-lossy version)

        if lossy_edit_files:
            # Helper function to check if a file is an elastic edit
            def is_elastic_file(filename):
                return 'elastic' in filename.lower()
            
            edit_numbers = []
            for f in lossy_edit_files:
                try:
                    # Skip elastic files if ignoreElastic is True
                    if ignoreElastic and is_elastic_file(f):
                        continue
                    num_str = f.split('_lossy_edit_')[1].split('_')[0]
                    edit_numbers.append((int(num_str), f))
                except (IndexError, ValueError):
                    continue

            if edit_numbers:
                # Find the latest edit number from tuples
                latest_edit = max(edit_numbers, key=lambda x: x[0])[0]
                # Find the specific lossy file corresponding to the latest edit number
                if scan_name == "atlas":
                    latest_lossy_edit_file_pattern = os.path.join(resolve_atlas_dir(directory), f"atlas_lossy_edit_{latest_edit}_*.nii.gz")
                else:
                    latest_lossy_edit_file_pattern = os.path.join(directory, "extracted", scan_name, f"{scan_name}_lossy_edit_{latest_edit}_*.nii.gz")
                    
                matching_files = glob.glob(latest_lossy_edit_file_pattern)
                if matching_files:
                    # Filter out displacement fields (inv and fwd) to get the actual image
                    image_files = [f for f in matching_files if not (f.endswith('_lossy_inv.nii.gz') or f.endswith('_lossy_fwd.nii.gz'))]
                    if image_files:
                        latest_lossy_edit_file_path = sorted(image_files)[-1]
                    else:
                        # Fallback to original logic if no filtered files found
                        latest_lossy_edit_file_path = sorted(matching_files)[-1]
                    # Get the corresponding non-lossy filename for the preview.json identifier
                    latest_edit_file_identifier = os.path.basename(latest_lossy_edit_file_path).replace("_lossy", "")

        load_start_time = time.time()
        # Load the latest lossy NIfTI file
        try:
            latest_edit_image_nii = nib.load(latest_lossy_edit_file_path)
            latest_edit_image_data = latest_edit_image_nii.get_fdata()
        except FileNotFoundError:
             print(f"Error: Could not find NIfTI file: {latest_lossy_edit_file_path}")
             # Return placeholder/error data
             img = Image.new('RGB', (QUADRANT_RENDER_SIZE * 2, QUADRANT_RENDER_SIZE * 2), color = 'black')
             draw = ImageDraw.Draw(img)
             draw.text((10, 10), f"Error: NIfTI file not found\n{os.path.basename(latest_lossy_edit_file_path)}", fill="red")
             buf = io.BytesIO()
             img.save(buf, format='JPEG')
             buf.seek(0)
             return buf.read()

        print(f"[{scan_name}] NIfTI loaded in {time.time() - load_start_time:.2f} seconds.")

        metadata_start_time = time.time()
        # Load metadata
        if scan_name == "atlas":
            metadata_json_path = os.path.join(resolve_atlas_dir(directory), "atlas.json")
        else:
            metadata_json_path = os.path.join(directory, "extracted", scan_name, f"{scan_name}.json")
            
        try:
            with open(metadata_json_path, 'r') as json_file:
                metadata_data = json.load(json_file)
        except (FileNotFoundError, json.JSONDecodeError):
             print(f"Error: Could not load metadata JSON for {scan_name}")
             # Return placeholder/error data (similar to above)
             img = Image.new('RGB', (QUADRANT_RENDER_SIZE * 2, QUADRANT_RENDER_SIZE * 2), color = 'black')
             draw = ImageDraw.Draw(img)
             draw.text((10, 10), f"Error: Metadata JSON missing/corrupt\n{scan_name}.json", fill="red")
             buf = io.BytesIO()
             img.save(buf, format='JPEG')
             buf.seek(0)
             return buf.read()

        print(f"[{scan_name}] Metadata loaded in {time.time() - metadata_start_time:.2f} seconds.")

        threshold_orig = metadata_data.get('threshold')

        # Get lossy parameters
        lossy_params = metadata_data.get('lossy_compression', [])
        # If lossy_params is a dict then turn into a list (recover legacy format)
        if isinstance(lossy_params, dict):
            lossy_params = [lossy_params]
            # if the dict has no filename, add it
            if 'filename' not in lossy_params[0]:
                lossy_params[0]['filename'] = os.path.basename(latest_lossy_edit_file_path)
            # save the updated metadata
            with open(metadata_json_path, 'w') as json_file:
                json.dump(metadata_data, json_file, indent=4)
        # Get the lossy parameters for the current lossy file
        lossy_filename = os.path.basename(latest_lossy_edit_file_path)
        matching_lossy_params = [p for p in lossy_params if p['filename'] == lossy_filename]
        if not matching_lossy_params: # if no lossy parameters found, use the last one
            print(f"Warning: No lossy parameters found for {scan_name}. Using default values.")
            lossy_params = lossy_params[-1] if lossy_params else {}
        else:
            lossy_params = matching_lossy_params[0]
        # Get the scale factor, zero point shift, voxel size, and resolution factor
        scale_factor = lossy_params.get('scale_factor', 1.0)
        zero_point_shift = lossy_params.get('zero_point_shift', 0.0)
        voxel_size = metadata_data.get('voxel_size', 1.0)
        resolution_factor = lossy_params.get('resolution_factor', 1.0)

        # Generate a histogram of the lossy image
        hist, bin_edges = np.histogram(latest_edit_image_data, bins=65, range=(0, 255))  
        histogram_data = {
            'bins': bin_edges.tolist(),
            'frequency': hist.tolist()
        }
        # Update preview JSON file *before* generating image
        if scan_name == "atlas":
            preview_json_path = os.path.join(resolve_atlas_dir(directory), "atlas_preview.json")
        else:
            preview_json_path = os.path.join(directory, "extracted", scan_name, f"{scan_name}_preview.json")
        
        # Get the timestamp of the latest edit file for tracking changes
        try:
            latest_edit_timestamp = os.path.getctime(latest_lossy_edit_file_path.replace("_lossy", ""))
        except OSError:
            print(f"Warning: Could not get timestamp for {latest_lossy_edit_file_path.replace('_lossy', '')}")
            latest_edit_timestamp = time.time()  # Use current time as fallback
        
        with open(preview_json_path, 'w') as json_file:
            json.dump({
                'last_edit': latest_edit_file_identifier, 
                'threshold': threshold_orig, 
                'last_edit_timestamp': latest_edit_timestamp, # Add timestamp tracking
                'histogram_data': histogram_data,
            }, json_file)

        threshold_adjust_start_time = time.time()
        # 2. Adjust Threshold for lossy image
        if scale_factor != 0:
            adjusted_threshold = (threshold_orig - zero_point_shift) / scale_factor
        else:
            adjusted_threshold = threshold_orig if zero_point_shift == 0 else (threshold_orig - zero_point_shift)
            print(f"Warning: scale_factor is zero or missing for {scan_name}. Using threshold {adjusted_threshold}")

        # Ensure threshold is within the range of the lossy data (often 0-255 for uint8)
        data_min, data_max = np.min(latest_edit_image_data), np.max(latest_edit_image_data)
        adjusted_threshold = np.clip(adjusted_threshold, data_min, data_max)
        print(f"Scan: {scan_name}, Orig Threshold: {threshold_orig}, Adjusted Threshold: {adjusted_threshold}, Data Range: [{data_min}, {data_max}]")
        print(f"[{scan_name}] Threshold adjusted in {time.time() - threshold_adjust_start_time:.2f} seconds.")

        centroid_start_time = time.time()
        # 3. Calculate Centroid (using center_of_mass on thresholded data)
        binary_image = latest_edit_image_data > adjusted_threshold
        if np.any(binary_image):
             # Use scipy.ndimage.center_of_mass on the binary mask for geometric center
             centroid_voxel = ndimage.center_of_mass(binary_image)
             # Ensure centroid coordinates are integers for slicing
             centroid_voxel = tuple(int(round(c)) for c in centroid_voxel)
             # Clamp centroid coordinates to be within image bounds
             centroid_voxel = tuple(np.clip(c, 0, s - 1) for c, s in zip(centroid_voxel, latest_edit_image_data.shape))
        else:
             # Fallback if no voxels are above threshold: use image center
             centroid_voxel = tuple(s // 2 for s in latest_edit_image_data.shape)
             print(f"Warning: No voxels above threshold {adjusted_threshold} for {scan_name}. Using image center {centroid_voxel} for centroid.")

        # Assuming Nifti shape is (X, Y, Z)
        centroid_x, centroid_y, centroid_z = centroid_voxel
        print(f"[{scan_name}] Centroid calculated in {time.time() - centroid_start_time:.2f} seconds.")

        quad1_start_time = time.time()
        # 4. Generate Quadrant 1 (Z-Sum Projection)
        z_sum_projection = np.sum(latest_edit_image_data, axis=2)
        # Normalize for display
        z_sum_norm = exposure.rescale_intensity(z_sum_projection, out_range=(0, 255)).astype(np.uint8)
        print(f"[{scan_name}] Quadrant 1 (Z-Sum Projection) generated in {time.time() - quad1_start_time:.2f} seconds.")

        quad2_start_time = time.time()
        # 5. Generate Quadrant 2 (Marching Cubes 3D View)
        quadrant2_img_array = None # Initialize
        try:
            # Calculate spacing for the lossy image
            lossy_spacing = float(voxel_size) * float(resolution_factor) # Ensure float
            spacing_tuple = (lossy_spacing, lossy_spacing, lossy_spacing)

            # Calculate dynamic step size based on active voxel count to keep mesh size reasonable
            # Marching cubes complexity scales with N / (step_size^3).
            # These cutoffs aim for roughly 50k-80k "effective" voxels processed to keep time consistent.
            active_voxels = np.count_nonzero(binary_image)
            if active_voxels > 50_000_000:
                dynamic_step = 9
            elif active_voxels > 30_000_000:
                dynamic_step = 8
            elif active_voxels > 20_000_000:
                dynamic_step = 7
            elif active_voxels > 12_000_000:
                dynamic_step = 6
            elif active_voxels > 7_000_000:
                dynamic_step = 5
            elif active_voxels > 3_500_000:
                dynamic_step = 4
            elif active_voxels > 1_500_000:
                dynamic_step = 3
            elif active_voxels > 500_000:
                dynamic_step = 2
            else:
                dynamic_step = 1

            print(f"[{scan_name}] Active voxels: {active_voxels:,}, using step_size: {dynamic_step}")

            # Use Max Pooling (block_reduce) to downsample strategically.
            # Max pooling ensures that thin, high-intensity structures (like edges or small muscles/bones)
            # are preserved and not "eaten away" or blurred below the threshold.
            if dynamic_step > 1:
                print(f"[{scan_name}] Applying Max Pooling block reduction with size: {dynamic_step}")
                reduced_image_data = measure.block_reduce(
                    latest_edit_image_data, 
                    block_size=(dynamic_step, dynamic_step, dynamic_step), 
                    func=np.max
                )
                
                # Apply a mild Gaussian blur to the downsampled volume to smooth blocky edges
                smoothed_image_data = gaussian_filter(reduced_image_data, sigma=1.0)
                
                # Since we actually shrunk the array, we tell marching cubes to use step_size=1
                # and compensate by multiplying the physical spacing.
                effective_spacing = (spacing_tuple[0] * dynamic_step, 
                                     spacing_tuple[1] * dynamic_step, 
                                     spacing_tuple[2] * dynamic_step)
                effective_step = 1
            else:
                smoothed_image_data = latest_edit_image_data
                effective_spacing = spacing_tuple
                effective_step = 1

            # Run marching cubes
            verts, faces, _, _ = measure.marching_cubes(smoothed_image_data, level=adjusted_threshold, spacing=effective_spacing, step_size=effective_step)

            if len(faces) > 0:
                faces = faces[:, ::-1]

            # Create a 3D plot using matplotlib
            fig_3d = plt.figure(figsize=(8, 8), frameon=False) # Control figure size
            fig_3d.subplots_adjust(0, 0, 1, 1)  # Remove all padding
            ax_3d = fig_3d.add_subplot(111, projection='3d')
            if len(verts) > 0 and len(faces) > 0:
                 # Plot the mesh
                 ax_3d.plot_trisurf(verts[:, 0], verts[:, 1], faces, verts[:, 2], color='lightgray', shade=True, edgecolor=None, alpha=1.0) 
            else:
                 # Handle empty mesh case
                 ax_3d.text(0.5, 0.5, 0.5, "No Mesh", horizontalalignment='center', verticalalignment='center', transform=ax_3d.transAxes, color='black')

            shape_mm = np.array(latest_edit_image_data.shape) * lossy_spacing
            ax_3d.set_xlim(0, shape_mm[0])
            ax_3d.set_ylim(0, shape_mm[1])
            ax_3d.set_zlim(0, shape_mm[2])

            # Set equal aspect ratio to prevent distortion
            ax_3d.set_box_aspect([shape_mm[0], shape_mm[1], shape_mm[2]])

            # Improve appearance
            ax_3d.xaxis.pane.fill = False # Remove planes
            ax_3d.yaxis.pane.fill = False
            ax_3d.zaxis.pane.fill = False
            ax_3d.grid(False) # No grid
            ax_3d.set_xticks([]) # No ticks
            ax_3d.set_yticks([])
            ax_3d.set_zticks([])
            # Make the axes invisible to remove boundary box
            ax_3d.set_axis_off()
            
            # Set background color
            ax_3d.set_facecolor('black')
            fig_3d.patch.set_facecolor('black')
            
            # Remove top title to maximize 3D space
            ax_3d.set_title("", pad=0)
            ax_3d.view_init(elev=-30, azim=25, roll=90) # Adjust viewing angle, elev is left-right (negative is right), azim is up-down (negative is down), roll is roll

            # Remove margin padding completely
            plt.margins(0, 0, 0)
            plt.tight_layout(pad=0, h_pad=0, w_pad=0)

            # Render the 3D plot to a buffer
            buf_3d = io.BytesIO()
            fig_3d.savefig(buf_3d, format='png', facecolor="black", bbox_inches='tight', pad_inches=0, dpi=200)
            buf_3d.seek(0)
            img_3d = Image.open(buf_3d)
            plt.close(fig_3d) # Close the figure to free memory
            quadrant2_img_array = np.array(img_3d)
            buf_3d.close()

        except Exception as e:
            print(f"Error generating 3D preview for {scan_name}: {e}")
            # Create a placeholder image indicating error
            img_placeholder = Image.new('RGB', (QUADRANT_RENDER_SIZE, QUADRANT_RENDER_SIZE), color = 'darkred')
            draw = ImageDraw.Draw(img_placeholder)
            draw.text((10, 10), "3D Preview Error", fill="white")
            quadrant2_img_array = np.array(img_placeholder)

        print(f"[{scan_name}] Quadrant 2 (3D View) generated in {time.time() - quad2_start_time:.2f} seconds.")

        quad3_start_time = time.time()
        # 6. Generate Quadrant 3 (X, Z Slice at Centroid Y)
        # Slice along Y axis (axis=1) at centroid_y
        xz_slice = latest_edit_image_data[:, centroid_y, :]
        # Normalize and ensure correct orientation (transpose if needed)
        xz_slice_norm = np.rot90(xz_slice).astype(np.uint8) # Rotate for better view
        print(f"[{scan_name}] Quadrant 3 (XZ Slice) generated in {time.time() - quad3_start_time:.2f} seconds.")

        quad4_start_time = time.time()
        # 7. Generate Quadrant 4 (Y, Z Slice at Centroid X)
        # Slice along X axis (axis=0) at centroid_x
        yz_slice = latest_edit_image_data[centroid_x, :, :]
        # Normalize and ensure correct orientation
        yz_slice_norm = np.rot90(yz_slice).astype(np.uint8) # Rotate for better view
        print(f"[{scan_name}] Quadrant 4 (YZ Slice) generated in {time.time() - quad4_start_time:.2f} seconds.")

        combine_start_time = time.time()
        # 8. Combine Quadrants
        # Ensure all images are RGB for consistent stacking
        if len(quadrant2_img_array.shape) == 3 and quadrant2_img_array.shape[2] == 4: # RGBA from PNG
            # Blend with black background if alpha exists
            alpha = quadrant2_img_array[:, :, 3] / 255.0
            bg = Image.new('RGB', (QUADRANT_RENDER_SIZE, QUADRANT_RENDER_SIZE), color='black') # PIL size is (width, height)
            fg = Image.fromarray(quadrant2_img_array[:, :, :3])
            # Resize fg before pasting onto bg to handle potential size mismatch from fig_3d
            fg_resized = self.resize_with_aspect_ratio(fg, (QUADRANT_RENDER_SIZE, QUADRANT_RENDER_SIZE), bg_color='black')
            # Don't use the original mask with the resized image - they won't match dimensions
            bg.paste(fg_resized, (0,0))
            quadrant2_img_array = np.array(bg)
        elif len(quadrant2_img_array.shape) == 2: # Grayscale
            quadrant2_img_array = np.stack([quadrant2_img_array]*3, axis=-1)
        elif quadrant2_img_array is None:
            # Create a placeholder if it failed earlier and wasn't caught
            img_placeholder = Image.new('RGB', (QUADRANT_RENDER_SIZE, QUADRANT_RENDER_SIZE), color = 'darkred')
            draw = ImageDraw.Draw(img_placeholder)
            draw.text((10, 10), "3D Preview Error", fill="white")
            quadrant2_img_array = np.array(img_placeholder)

        # Convert grayscale slices to RGB
        z_sum_rgb = np.stack([z_sum_norm]*3, axis=-1)
        xz_slice_rgb = np.stack([xz_slice_norm]*3, axis=-1)
        yz_slice_rgb = np.stack([yz_slice_norm]*3, axis=-1)

        # Resize images to a common size (e.g., 512x512)
        target_size = (QUADRANT_RENDER_SIZE, QUADRANT_RENDER_SIZE)
        
        # Convert all arrays to PIL images safely
        try:
            img_q1_pil = Image.fromarray(z_sum_rgb.astype(np.uint8))
            img_q2_pil = Image.fromarray(quadrant2_img_array.astype(np.uint8))
            img_q3_pil = Image.fromarray(xz_slice_rgb.astype(np.uint8))
            img_q4_pil = Image.fromarray(yz_slice_rgb.astype(np.uint8))
        except Exception as e:
            print(f"Error converting arrays to PIL images: {e}")
            # Create fallback images if conversion fails
            img_q1_pil = Image.new('RGB', target_size, color='black')
            img_q2_pil = Image.new('RGB', target_size, color='black')
            img_q3_pil = Image.new('RGB', target_size, color='black')
            img_q4_pil = Image.new('RGB', target_size, color='black')

        # Safely resize images with error handling
        try:
            img_q1 = self.resize_with_aspect_ratio(img_q1_pil, target_size)
            img_q2 = self.resize_with_aspect_ratio(img_q2_pil, target_size)
            img_q3 = self.resize_with_aspect_ratio(img_q3_pil, target_size)
            img_q4 = self.resize_with_aspect_ratio(img_q4_pil, target_size)
        except Exception as e:
            print(f"Error resizing images: {e}")
            img_q1 = Image.new('RGB', target_size, color='black')
            img_q2 = Image.new('RGB', target_size, color='black')
            img_q3 = Image.new('RGB', target_size, color='black')
            img_q4 = Image.new('RGB', target_size, color='black')

        # Create the grid image
        grid_img = Image.new('RGB', (target_size[0]*2, target_size[1]*2))
        
        # Paste images with error handling
        try:
            grid_img.paste(img_q1, (0, 0))
            grid_img.paste(img_q2, (target_size[0], 0))
            grid_img.paste(img_q3, (0, target_size[1]))
            grid_img.paste(img_q4, (target_size[0], target_size[1]))
        except Exception as e:
            print(f"Error pasting images onto grid: {e}")
            # If pasting fails, create a simple error image
            grid_img = Image.new('RGB', (target_size[0]*2, target_size[1]*2), color='black')
            draw = ImageDraw.Draw(grid_img)
            draw.text((10, 10), f"Error creating preview: {e}", fill="white")
            
        # Add titles
        draw = ImageDraw.Draw(grid_img)
        try:
            # Try loading a simple font
            font = ImageFont.truetype("DejaVuSans.ttf", 20) # Use a common sans-serif font if available
        except IOError:
            font = ImageFont.load_default() # Fallback

        # Add titles with background box for better visibility
        def draw_text_with_bg(draw, pos, text, font, text_color="white", bg_color="black"):
             bbox = draw.textbbox(pos, text, font=font)
             # Add small padding
             bg_bbox = (bbox[0]-2, bbox[1]-1, bbox[2]+2, bbox[3]+1)
             try: # Handle potential RGBA color for background
                 draw.rectangle(bg_bbox, fill=bg_color)
             except TypeError: # Fallback to RGB if RGBA fails
                 draw.rectangle(bg_bbox, fill=bg_color[:3])
             draw.text(pos, text, fill=text_color, font=font)

        draw_text_with_bg(draw, (5, 5), "Z Sum Projection", font=font)
        draw_text_with_bg(draw, (target_size[0] + 5, 5), "3D Marching Cubes", font=font)
        draw_text_with_bg(draw, (5, target_size[1] + 5), f"XZ Slice (Y={centroid_y})", font=font)
        draw_text_with_bg(draw, (target_size[0] + 5, target_size[1] + 5), f"YZ Slice (X={centroid_x})", font=font)

        print(f"[{scan_name}] Quadrants combined and titles added in {time.time() - combine_start_time:.2f} seconds.")

        save_start_time = time.time()
        # 9. Save/Return Image
        buf_final = io.BytesIO()
        grid_img.save(buf_final, format='JPEG', quality=GRID_PREVIEW_JPEG_QUALITY)
        buf_final.seek(0)
        image_data_bytes = buf_final.read()
        buf_final.close()

        # Save the image to disk as well
        if scan_name == "atlas":
            preview_path = os.path.join(resolve_atlas_dir(directory), "atlas_preview.jpg")
        else:
            preview_path = os.path.join(directory, "extracted", scan_name, f"{scan_name}_preview.jpg")
            
        try:
            with open(preview_path, 'wb') as f:
                f.write(image_data_bytes)
            print(f"Preview image saved to {preview_path}")
        except IOError as e:
            print(f"Error saving preview image {preview_path}: {e}")

        print(f"[{scan_name}] Final image saved/encoded in {time.time() - save_start_time:.2f} seconds.")

        # Clean up large data structures
        cleanup_start_time = time.time()
        latest_edit_image_data = None
        binary_image = None
        verts = faces = None
        gc.collect()
        print(f"[{scan_name}] Cleanup performed in {time.time() - cleanup_start_time:.2f} seconds.")

        total_time = time.time() - start_time
        print(f"[{scan_name}] Total preview generation time: {total_time:.2f} seconds.")
        return image_data_bytes # Return bytes for the response

    def get_histogram_data(self, scan_name, directory):
        # Check the preview.json file for the histogram data
        if scan_name == "atlas":
            preview_json_path = os.path.join(resolve_atlas_dir(directory), "atlas_preview.json")
        else:
            preview_json_path = os.path.join(directory, "extracted", scan_name, f"{scan_name}_preview.json")
            
        with open(preview_json_path, 'r') as jf:
            preview_data = json.load(jf)
        histogram_data = preview_data.get('histogram_data', None)
        return histogram_data

    def post(self, request, *args, **kwargs):
        scan_name = request.data.get('scan_name')
        directory = request.data.get('directory')
        ignoreElastic = request.data.get('ignoreElastic', False)

        if not scan_name or not directory:
            return Response({'error': 'Missing scan_name or directory'}, status=status.HTTP_400_BAD_REQUEST)

        is_preserved_mesh = False
        if scan_name != "atlas":
            try:
                metadata_data = self._load_scan_metadata(scan_name, directory)
                is_preserved_mesh = _is_preserved_mesh_metadata(metadata_data)
            except (FileNotFoundError, json.JSONDecodeError):
                is_preserved_mesh = False

        # Verify if {scan_name}_preview.jpg exists in the directory
        if scan_name == "atlas":
            preview_path = os.path.join(resolve_atlas_dir(directory), "atlas_preview.jpg")
            preview_json_path = os.path.join(resolve_atlas_dir(directory), "atlas_preview.json")
        else:
            preview_path = os.path.join(directory, "extracted", scan_name, f"{scan_name}_preview.jpg")
            preview_json_path = os.path.join(directory, "extracted", scan_name, f"{scan_name}_preview.json")

        preview_is_current = (
            self.mesh_preview_up_to_date(scan_name, directory, ignoreElastic)
            if is_preserved_mesh
            else self.preview_up_to_date(scan_name, directory, ignoreElastic)
        )

        # Check if preview exists and is up to date
        if os.path.exists(preview_path) and os.path.exists(preview_json_path):
            if preview_is_current:
                print(f"Preview for {scan_name} is up to date. Loading existing.")
                try:
                    with open(preview_path, 'rb') as image_file:
                        image_data = image_file.read()
                    histogram_data = self.get_histogram_data(scan_name, directory)
                    # return the image data as a base64 encoded string
                    return Response({'image_data': base64.b64encode(image_data).decode('utf-8'), 'histogram_data': histogram_data})
                except IOError as e:
                     print(f"Error reading existing preview file {preview_path}: {e}")
                     # Fall through to regenerate if reading fails
            else:
                 print(f"Preview for {scan_name} is outdated. Regenerating.")
                 # Fall through to regenerate
        else:
            print(f"Preview for {scan_name} not found or incomplete. Generating.")
            # Fall through to generate

        # Generate or Regenerate Preview
        try:
            if is_preserved_mesh:
                preview_image_bytes = self.create_mesh_preview_image(scan_name, directory, ignoreElastic)
            else:
                preview_image_bytes = self.create_preview_image(scan_name, directory, ignoreElastic)
            histogram_data = self.get_histogram_data(scan_name, directory)
            return Response({'image_data': base64.b64encode(preview_image_bytes).decode('utf-8'), 'histogram_data': histogram_data})
        except Exception as e:
             print(f"Error occurred during preview generation for {scan_name}: {e}")
             # Optionally: return a specific error image or message
             # For now, return a server error
             return Response({'error': f'Failed to generate preview: {e}'}, status=status.HTTP_500_INTERNAL_SERVER_ERROR)


class CreateFolderView(APIView):
    def post(self, request, *args, **kwargs):
        path = request.data.get('path')
        folder_name = request.data.get('folderName')
        try:
            full_path = os.path.join(path, folder_name)
            os.makedirs(full_path)
            return Response({'message': 'Folder created successfully!'})
        except Exception as e:
            return Response({'error': str(e)}, status=400)


class getDataSizeDirectoryView(APIView):
    CACHE_TTL_SECONDS = 30
    MAX_SCAN_SECONDS = 2.5
    _cache = {}
    _cache_lock = threading.Lock()
    _inflight = set()

    def _normalize_directory(self, directory):
        if not isinstance(directory, str) or not directory.strip():
            raise ValueError("A directory path is required.")
        directory = os.path.abspath(os.path.expanduser(directory))
        if not os.path.isdir(directory):
            raise FileNotFoundError(f"Directory does not exist: {directory}")
        return directory

    def _get_cached_payload(self, directory):
        now = time.monotonic()
        with self._cache_lock:
            cached = self._cache.get(directory)
            if cached and now - cached['timestamp'] <= self.CACHE_TTL_SECONDS:
                payload = dict(cached['payload'])
                payload['cached'] = True
                return payload
        return None

    def _store_cached_payload(self, directory, payload):
        with self._cache_lock:
            self._cache[directory] = {
                'timestamp': time.monotonic(),
                'payload': dict(payload),
            }

    def _disk_payload(self, directory):
        usage = psutil.disk_usage(directory)
        total_storage = float(usage.total) / (1024 ** 3)
        occupied_storage = float(usage.used) / (1024 ** 3)
        return {
            'total_size': total_storage,
            'occupied_size': occupied_storage,
        }

    def get_total_storage(self, directory):
        # Get the total storage of the filesystem containing the directory in GB
        total_storage = float(psutil.disk_usage(directory).total) / (1024 ** 3)        
        print("Total storage: "+str(total_storage))
        return total_storage
    
    def get_occupied_storage(self, directory):
        # Get the occupied storage of the filesystem containing the directory in GB
        occupied_storage = float(psutil.disk_usage(directory).used) / (1024 ** 3)
        print("Occupied storage: "+str(occupied_storage))
        return occupied_storage
    
    def get_data_size_directory(self, directory, deadline=None):
        # Get the cumulative size of all files in the directory in GB
        total_size = 0
        for root, dirs, files in os.walk(directory):
            if deadline is not None and time.monotonic() >= deadline:
                return None
            for file in files:
                file_path = os.path.join(root, file)
                try:
                    total_size += os.path.getsize(file_path)
                except (OSError, FileNotFoundError):
                    # Skip files that can't be accessed (broken symlinks, permission denied, etc.)
                    continue
                if deadline is not None and time.monotonic() >= deadline:
                    return None
        # Convert bytes to gigabytes and return as float
        print("Total size: "+str(float(total_size) / (1024 ** 3)))
        return float(total_size) / (1024 ** 3)
    
    def post(self, request, *args, **kwargs):
        try:
            directory = self._normalize_directory(request.data.get('directory'))
        except (ValueError, FileNotFoundError) as exc:
            return Response({'error': str(exc)}, status=status.HTTP_400_BAD_REQUEST)

        cached_payload = self._get_cached_payload(directory)
        if cached_payload is not None:
            return Response(cached_payload)

        with self._cache_lock:
            if directory in self._inflight:
                stale = self._cache.get(directory)
                if stale:
                    payload = dict(stale['payload'])
                    payload.update({
                        'cached': True,
                        'deferred': True,
                        'message': 'Directory size is already being refreshed; returning the previous result.',
                    })
                    return Response(payload)

                payload = self._disk_payload(directory)
                payload.update({
                    'size': None,
                    'complete': False,
                    'deferred': True,
                    'message': 'Directory size is already being calculated.',
                })
                return Response(payload, status=status.HTTP_202_ACCEPTED)

            self._inflight.add(directory)

        try:
            payload = self._disk_payload(directory)
            size = self.get_data_size_directory(
                directory,
                deadline=time.monotonic() + self.MAX_SCAN_SECONDS,
            )
            payload.update({
                'size': size,
                'complete': size is not None,
                'cached': False,
            })
            if size is None:
                payload['message'] = 'Directory size scan took too long and was skipped to keep Aurora responsive.'
            else:
                self._store_cached_payload(directory, payload)
            return Response(payload)
        except OSError as exc:
            return Response({'error': str(exc)}, status=status.HTTP_400_BAD_REQUEST)
        finally:
            with self._cache_lock:
                self._inflight.discard(directory)
        


# ----------- PRE-PROCESSING -------------------

class ExtractScansView(APIView):

    MESH_SUBTYPE_EXTENSIONS = {
        'OBJ Mesh': '.obj',
        'PLY Mesh': '.ply',
        'STL Mesh': '.stl',
        'glTF Mesh': '.gltf',
        'GLB Mesh': '.glb',
        'OpenUSD Mesh': '.usdz',
        'USDZ Mesh': '.usdz',  # legacy alias
    }
    MESH_MAX_VOXEL_CUBE = 512
    MESH_VOXEL_PADDING = 2

    @staticmethod
    def _reduce_extra_dims_to_3d(arr):
        """
        Reduce volumes with more than 3 dimensions to 3D.
        The axis with the smallest extent is treated as channels (or time);
        index 0 is taken along that axis until the array is 3D.
        """
        out = arr
        while out.ndim > 3:
            channel_axis = int(np.argmin(out.shape))
            out = np.take(out, 0, axis=channel_axis)
        return out

    def _is_segmentation_name(self, name):
        n = name.lower()
        return n.endswith('.seg') or '.seg.' in n

    @classmethod
    def _is_mesh_subtype(cls, subtype):
        return subtype in cls.MESH_SUBTYPE_EXTENSIONS

    @classmethod
    def _mesh_extension_for_subtype(cls, subtype):
        return cls.MESH_SUBTYPE_EXTENSIONS.get(subtype)

    def _mesh_source_path(self, directory, scan_name, scan_subtype):
        ext = self._mesh_extension_for_subtype(scan_subtype)
        if not ext:
            return None

        if scan_subtype in ('OpenUSD Mesh', 'USDZ Mesh'):
            from .openUsdMeshTools import (
                OPENUSD_ARCHIVE_EXTENSIONS,
                OPENUSD_STAGE_EXTENSIONS,
                find_usd_stage_in_directory,
            )

            folder_candidate = os.path.join(directory, scan_name)
            if os.path.isdir(folder_candidate) and find_usd_stage_in_directory(folder_candidate):
                return folder_candidate

            for ext in OPENUSD_ARCHIVE_EXTENSIONS + OPENUSD_STAGE_EXTENSIONS:
                candidates = [
                    os.path.join(directory, f"{scan_name}{ext}"),
                    os.path.join(directory, f"{scan_name}{ext.upper()}"),
                ]
                for candidate in candidates:
                    if os.path.exists(candidate):
                        return candidate
            try:
                scan_lower = scan_name.lower()
                for entry in os.listdir(directory):
                    entry_lower = entry.lower()
                    for ext in OPENUSD_ARCHIVE_EXTENSIONS + OPENUSD_STAGE_EXTENSIONS:
                        if entry_lower == f"{scan_lower}{ext}":
                            return os.path.join(directory, entry)
            except Exception:
                pass
            return None

        candidates = [
            os.path.join(directory, f"{scan_name}{ext}"),
            os.path.join(directory, f"{scan_name}{ext.upper()}"),
        ]
        for candidate in candidates:
            if os.path.exists(candidate):
                return candidate
        try:
            scan_lower = scan_name.lower()
            ext_lower = ext.lower()
            for entry in os.listdir(directory):
                entry_lower = entry.lower()
                if entry_lower == f"{scan_lower}{ext_lower}":
                    return os.path.join(directory, entry)
        except Exception:
            pass
        return None

    def _load_mesh_for_extraction(self, mesh_path, scale_factor=1.0):
        from .openUsdMeshTools import is_openusd_mesh_source, load_trimesh_from_openusd

        if is_openusd_mesh_source(mesh_path):
            mesh = load_trimesh_from_openusd(mesh_path)
            if mesh.vertices is None or len(mesh.vertices) == 0 or mesh.faces is None or len(mesh.faces) == 0:
                raise ValueError(f"Mesh has no vertices or faces: {mesh_path}")
            if scale_factor != 1.0:
                mesh.vertices = np.asarray(mesh.vertices, dtype=np.float64) * float(scale_factor)
            return ensure_welded_trimesh(mesh)

        loaded = trimesh.load(mesh_path, process=False)
        if isinstance(loaded, trimesh.Scene):
            geometries = [
                geom for geom in loaded.geometry.values()
                if isinstance(geom, trimesh.Trimesh) and len(geom.vertices) > 0
            ]
            if not geometries:
                raise ValueError(f"No triangle mesh geometry found in {mesh_path}")
            mesh = trimesh.util.concatenate(geometries)
        elif isinstance(loaded, trimesh.Trimesh):
            mesh = loaded.copy()
        else:
            raise ValueError(f"Unsupported mesh content in {mesh_path}")

        if mesh.vertices is None or len(mesh.vertices) == 0 or mesh.faces is None or len(mesh.faces) == 0:
            raise ValueError(f"Mesh has no vertices or faces: {mesh_path}")

        if scale_factor != 1.0:
            mesh.vertices = np.asarray(mesh.vertices, dtype=np.float64) * float(scale_factor)
        # Face projects are a single surface: weld triangle-soup PLYs so metadata
        # and the preserved PLY share index-connected geometry.
        return ensure_welded_trimesh(mesh)

    def _mesh_summary(self, mesh, scan_name, scale_factor=1.0, group_label=None):
        vertices = np.asarray(mesh.vertices, dtype=np.float64)
        bounds = np.asarray(mesh.bounds, dtype=np.float64)
        extents = np.asarray(mesh.extents, dtype=np.float64)
        centroid = _mesh_surface_centroid(vertices)
        centered = vertices - centroid
        centroid_size = float(np.sqrt(np.mean(np.sum(centered * centered, axis=1)))) if len(vertices) else 0.0
        return {
            'name': scan_name,
            'centroid': centroid.tolist(),
            'centroid_size': centroid_size,
            'bounds': bounds.tolist(),
            'extents': extents.tolist(),
            'vertex_count': int(len(mesh.vertices)),
            'face_count': int(len(mesh.faces)),
            'is_watertight': bool(mesh.is_watertight),
            'scale_factor': float(scale_factor),
            'scale_group': group_label,
        }

    def _collect_mesh_infos(self, directory, scans):
        infos = []
        for scan in scans:
            scan_name = scan.get('name')
            scan_subtype = scan.get('subtype')
            if not scan_name or not self._is_mesh_subtype(scan_subtype):
                continue
            mesh_path = self._mesh_source_path(directory, scan_name, scan_subtype)
            if not mesh_path:
                continue
            try:
                mesh = self._load_mesh_for_extraction(mesh_path)
                summary = self._mesh_summary(mesh, scan_name)
                summary.update({
                    'subtype': scan_subtype,
                    'source_file': os.path.basename(mesh_path),
                })
                infos.append(summary)
            except Exception as e:
                infos.append({
                    'name': scan_name,
                    'subtype': scan_subtype,
                    'source_file': os.path.basename(mesh_path),
                    'error': str(e),
                    'centroid_size': 0.0,
                    'extents': [0.0, 0.0, 0.0],
                })
        return infos

    def _group_mesh_infos_by_scale(self, mesh_infos):
        valid_infos = [info for info in mesh_infos if info.get('centroid_size', 0) > 0 and not info.get('error')]
        valid_infos.sort(key=lambda info: info['centroid_size'])
        groups = []
        for info in valid_infos:
            if not groups:
                groups.append([info])
                continue
            group_sizes = [item['centroid_size'] for item in groups[-1]]
            group_center = float(np.median(group_sizes))
            if group_center > 0 and info['centroid_size'] > group_center * 1.5:
                groups.append([info])
            else:
                groups[-1].append(info)

        result = []
        for idx, group in enumerate(groups):
            label = f"Group {chr(ord('A') + idx)}"
            sizes = [item['centroid_size'] for item in group]
            result.append({
                'label': label,
                'subjects': [item['name'] for item in group],
                'centroid_size_mean': float(np.mean(sizes)),
                'centroid_size_min': float(np.min(sizes)),
                'centroid_size_max': float(np.max(sizes)),
                'default_scale_factor': 1.0,
            })
        return result

    def _mesh_scale_factor_for_scan(self, scan_name, mesh_options):
        subject_factors = mesh_options.get('subject_scale_factors') or {}
        try:
            return float(subject_factors.get(scan_name, 1.0))
        except (TypeError, ValueError):
            return 1.0

    def _derive_mesh_voxel_size(self, directory, scans, mesh_options):
        scaled_infos = []
        skipped = set(mesh_options.get('skipped_subjects') or [])
        for scan in scans:
            scan_name = scan.get('name')
            scan_subtype = scan.get('subtype')
            if not scan_name or scan_name in skipped or not self._is_mesh_subtype(scan_subtype):
                continue
            mesh_path = self._mesh_source_path(directory, scan_name, scan_subtype)
            if not mesh_path:
                continue
            scale_factor = self._mesh_scale_factor_for_scan(scan_name, mesh_options)
            mesh = self._load_mesh_for_extraction(mesh_path, scale_factor=scale_factor)
            scaled_infos.append(self._mesh_summary(mesh, scan_name, scale_factor=scale_factor))

        if not scaled_infos:
            return 1.0

        avg_centroid_size = float(np.mean([info['centroid_size'] for info in scaled_infos if info['centroid_size'] > 0])) or 1.0
        max_extent = max(float(np.max(info['extents'])) for info in scaled_infos)
        usable_dim = max(self.MESH_MAX_VOXEL_CUBE - (2 * self.MESH_VOXEL_PADDING), 1)
        voxel_size = max((avg_centroid_size * 2.0) / self.MESH_MAX_VOXEL_CUBE, max_extent / usable_dim, 1e-6)
        return float(voxel_size)

    def _save_mesh_as_ply(self, mesh, output_path):
        return PreservedMeshEditWriter.save(mesh, output_path)

    def _voxelize_mesh_to_volume(self, mesh, voxel_size):
        warning = None
        try:
            voxel_grid = mesh.voxelized(float(voxel_size))
            if mesh.is_watertight:
                try:
                    voxel_grid = voxel_grid.fill()
                except Exception as e:
                    warning = f"Mesh is watertight but fill failed; saved surface voxels only: {e}"
            else:
                warning = "Mesh is not watertight; saved surface voxels only."
            matrix = np.asarray(voxel_grid.matrix, dtype=bool)
            if matrix.size == 0 or not np.any(matrix):
                raise ValueError("Voxelization produced an empty volume")
            # Trimesh stores voxels on array axes (mesh X, Y, Z). Aurora NIfTI
            # volumes use (Z, Y, X) storage like DICOM stacks; marching cubes and
            # other mesh paths swap axes 0/2 on read. Match that convention here
            # so voxelized meshes align with the original mesh after extraction.
            matrix = np.swapaxes(matrix, 0, 2)
            matrix = np.pad(matrix, self.MESH_VOXEL_PADDING, mode='constant', constant_values=False)
            return matrix.astype(np.uint16) * np.uint16(65535), warning
        except Exception as e:
            raise ValueError(f"Could not voxelize mesh: {e}")
    
    def _find_segmentations_map(self, directory):
        """
        Map base scan name -> absolute segmentation path.
        Recognizes files like '<base>.seg.nii.gz' / '<base>.seg.mnc' and folders
        named '<base>.seg' containing one of: .nii.gz, .nii, .mnc, .tiff, .tif.
        Priority: nii.gz > nii > mnc > tiff > tif.
        """
        priority = {'nii.gz': 0, 'nii': 1, 'mnc': 2, 'tiff': 3, 'tif': 4}
        seg_map = {}

        def maybe_set(base_name, path, ext_key):
            if base_name not in seg_map:
                seg_map[base_name] = (path, priority[ext_key])
            else:
                _, pr = seg_map[base_name]
                if priority[ext_key] < pr:
                    seg_map[base_name] = (path, priority[ext_key])

        try:
            for entry in os.listdir(directory):
                path = os.path.join(directory, entry)
                name_lower = entry.lower()

                # File case: '<base>.seg.<ext>'
                if os.path.isfile(path):
                    seg_token = ('.seg.' in name_lower) or name_lower.endswith('.seg')
                    if not seg_token:
                        continue

                    # Get base name before '.seg'
                    seg_idx = name_lower.find('.seg')
                    if seg_idx == -1:
                        continue
                    base_name = entry[:seg_idx]

                    # Determine ext (nii.gz must be checked before .nii)
                    if name_lower.endswith('.nii.gz'):
                        maybe_set(base_name, path, 'nii.gz')
                    elif name_lower.endswith('.nii'):
                        maybe_set(base_name, path, 'nii')
                    elif name_lower.endswith('.mnc'):
                        maybe_set(base_name, path, 'mnc')
                    elif name_lower.endswith('.tiff'):
                        maybe_set(base_name, path, 'tiff')
                    elif name_lower.endswith('.tif'):
                        maybe_set(base_name, path, 'tif')

                # Folder case: '<base>.seg' directory
                elif os.path.isdir(path) and name_lower.endswith('.seg'):
                    base_name = entry[:-4]  # strip '.seg'
                    best = None
                    best_pr = 1_000
                    for root, _, files in os.walk(path):
                        for f in files:
                            f_lower = f.lower()
                            fpath = os.path.join(root, f)
                            if f_lower.endswith('.nii.gz') and priority['nii.gz'] < best_pr:
                                best, best_pr = fpath, priority['nii.gz']
                            elif f_lower.endswith('.nii') and priority['nii'] < best_pr:
                                best, best_pr = fpath, priority['nii']
                            elif f_lower.endswith('.mnc') and priority['mnc'] < best_pr:
                                best, best_pr = fpath, priority['mnc']
                            elif f_lower.endswith('.tiff') and priority['tiff'] < best_pr:
                                best, best_pr = fpath, priority['tiff']
                            elif f_lower.endswith('.tif') and priority['tif'] < best_pr:
                                best, best_pr = fpath, priority['tif']
                    if best is not None:
                        b_lower = best.lower()
                        if b_lower.endswith('.nii.gz'):
                            maybe_set(base_name, best, 'nii.gz')
                        elif b_lower.endswith('.nii'):
                            maybe_set(base_name, best, 'nii')
                        elif b_lower.endswith('.mnc'):
                            maybe_set(base_name, best, 'mnc')
                        elif b_lower.endswith('.tiff'):
                            maybe_set(base_name, best, 'tiff')
                        elif b_lower.endswith('.tif'):
                            maybe_set(base_name, best, 'tif')
        except Exception as e:
            print(f"Warning: failed scanning for segmentations in {directory}: {e}")

        return {k: v[0] for k, v in seg_map.items()}
    def _load_segmentation_mask(self, seg_path):
        """
        Load a segmentation file into a 3D uint8 mask (values 0/1).
        Supports: .nii.gz/.nii, .tif/.tiff
        """
        try:
            name_lower = seg_path.lower()
            if name_lower.endswith('.nii.gz') or name_lower.endswith('.nii'):
                nii = nib.load(seg_path)
                arr = nii.get_fdata()
                if arr.ndim > 3:
                    arr = self._reduce_extra_dims_to_3d(arr)
                mask = (arr > 0).astype(np.uint8)
                return mask
            elif name_lower.endswith('.tiff') or name_lower.endswith('.tif'):
                arr = tifffile.imread(seg_path)
                if arr.ndim == 2:
                    # Single slice; add z dimension
                    arr = arr[np.newaxis, ...]
                elif arr.ndim > 3:
                    arr = self._reduce_extra_dims_to_3d(arr)
                mask = (arr > 0).astype(np.uint8)
                return mask
            elif name_lower.endswith('.mnc'):
                mnc = nib.load(seg_path)
                arr = mnc.get_fdata()
                if arr.ndim > 3:
                    arr = self._reduce_extra_dims_to_3d(arr)
                mask = (arr > 0).astype(np.uint8)
                return mask
            else:
                print(f"Warning: Unsupported segmentation file type: {seg_path}")
                return None
        except Exception as e:
            print(f"Warning: Failed to load segmentation mask {seg_path}: {e}")
            return None

    def _safe_zoom_mask(self, arr, target_shape):
        """
        Scale mask to target shape using nearest-neighbor, then crop/pad as needed.
        """
        
        zoom_factors = [target_shape[i] / arr.shape[i] for i in range(len(target_shape))]
        scaled = zoom(arr, zoom_factors, order=0)
        if scaled.shape != target_shape:
            result = np.zeros(target_shape, dtype=arr.dtype)
            slices = tuple(slice(0, min(scaled.shape[i], target_shape[i])) for i in range(len(target_shape)))
            result[slices] = scaled[slices]
            return result
        return scaled

    def _save_segmentation_masks(self, scan_out_folder, scan_name, seg_mask):
        """
        Save segmentation masks aligned to both full and lossy images if they exist.
        Uses naming consistent with SaveMaskView: <edit>.nii.mask.gz
        """
        try:
            # Full-res
            full_img_path = os.path.join(scan_out_folder, f"{scan_name}.nii.gz")
            if os.path.exists(full_img_path):
                full_img = nib.load(full_img_path)
                full_shape = full_img.header.get_data_shape()
                full_mask = self._safe_zoom_mask(seg_mask, (full_shape[0], full_shape[1], full_shape[2]))
                full_mask_img = nib.Nifti1Image(full_mask.astype(np.uint8), full_img.affine, header=full_img.header)
                full_temp = os.path.join(scan_out_folder, f"{scan_name}_mask.nii.gz")
                full_final = os.path.join(scan_out_folder, f"{scan_name}.nii.mask.gz")
                nib.save(full_mask_img, full_temp)
                os.rename(full_temp, full_final)

            # Lossy
            lossy_img_path = os.path.join(scan_out_folder, f"{scan_name}_lossy.nii.gz")
            if os.path.exists(lossy_img_path):
                lossy_img = nib.load(lossy_img_path)
                lossy_shape = lossy_img.header.get_data_shape()
                lossy_mask = self._safe_zoom_mask(seg_mask, (lossy_shape[0], lossy_shape[1], lossy_shape[2]))
                lossy_mask_img = nib.Nifti1Image(lossy_mask.astype(np.uint8), lossy_img.affine, header=lossy_img.header)
                lossy_temp = os.path.join(scan_out_folder, f"{scan_name}_lossy_mask.nii.gz")
                lossy_final = os.path.join(scan_out_folder, f"{scan_name}_lossy.nii.mask.gz")
                nib.save(lossy_mask_img, lossy_temp)
                os.rename(lossy_temp, lossy_final)
        except Exception as e:
            print(f"Warning: Failed to save segmentation masks for {scan_name}: {e}")

    # Midpoint of full uint16 range — used for intentionally scaled binary volumes
    BINARY_UINT16_THRESHOLD = 32767

    def _is_binary_label_image(self, image_data):
        """True when the volume has exactly two discrete label values (e.g. 0/1, 0/255)."""
        data = np.asarray(image_data)
        if data.size == 0:
            return False

        flat = data.ravel()
        if flat.size > 5_000_000:
            flat = flat[::max(1, flat.size // 2_000_000)]

        if np.issubdtype(data.dtype, np.floating):
            rounded = np.round(flat)
            if np.max(np.abs(flat - rounded)) > 1e-3:
                return False
            flat = rounded

        return len(np.unique(flat)) == 2

    def _scale_binary_to_uint16(self, image_data):
        """Scale a two-label image to uint16 0/65535 so downstream steps treat it like normal int16."""
        result, _, _ = self._scale_binary_to_uint16_with_labels(image_data)
        return result

    def _scale_binary_to_uint16_with_labels(self, image_data):
        """Same as _scale_binary_to_uint16 but also returns the two original label values."""
        data = np.round(np.asarray(image_data, dtype=np.float64))
        data_min = float(np.min(data))
        data_max = float(np.max(data))
        scaled = (data - data_min) / (data_max - data_min) * 65535.0
        result = scaled.astype(np.uint16)
        print(f"Scaled binary image from [{data_min:g}, {data_max:g}] to uint16 [0, 65535]")
        return result, data_min, data_max

    @staticmethod
    def _intensity_dtype_family(dtype):
        """Coarse dtype family used for intensity value-family clustering."""
        dt = np.dtype(dtype)
        if dt == np.dtype(np.uint16):
            return 'uint16'
        if np.issubdtype(dt, np.floating):
            return 'float'
        if dt in (np.dtype(np.int8), np.dtype(np.uint8)):
            return 'int8'
        if dt == np.dtype(np.int16):
            return 'int16'
        if np.issubdtype(dt, np.integer):
            return 'int32+'
        return 'other'

    @staticmethod
    def _intensity_range_key(data_min, data_max):
        """Log-ish magnitude used to cluster value families (mesh-style)."""
        span = abs(float(data_max) - float(data_min))
        mid = 0.5 * (float(data_min) + float(data_max))
        return float(np.log10(max(abs(mid), span, 1e-12) + 1e-12))

    def _subsample_for_stats(self, image_data):
        flat = np.asarray(image_data).ravel()
        if flat.size > 5_000_000:
            flat = flat[::max(1, flat.size // 2_000_000)]
        return flat

    def _compute_intensity_scan_stats(self, scan_name, image_data):
        """Per-scan dtype/range probe used by intensity extract preflight."""
        arr = np.asarray(image_data)
        if arr.ndim > 3:
            arr = self._reduce_extra_dims_to_3d(arr)
        dtype_str = str(arr.dtype)
        is_uint16 = arr.dtype == np.uint16
        is_binary = False if is_uint16 else self._is_binary_label_image(arr)
        sample = self._subsample_for_stats(arr)
        # Prefer full-array extrema when affordable; otherwise use the subsample.
        if arr.size <= 50_000_000:
            data_min = float(np.min(arr))
            data_max = float(np.max(arr))
        else:
            data_min = float(np.min(sample))
            data_max = float(np.max(sample))
        dtype_family = self._intensity_dtype_family(arr.dtype)
        # Only types whose native domain cannot be preserved losslessly in uint16
        # need the user to pick a value range; everything else keeps its full range.
        needs_range_decision = bool(
            not is_uint16 and not is_binary and dtype_family in ('float', 'int32+', 'other')
        )
        if is_uint16:
            range_policy = 'passthrough'
        elif is_binary:
            range_policy = 'binary'
        elif needs_range_decision:
            range_policy = 'window'
        else:
            range_policy = 'native'
        return {
            'name': scan_name,
            'dtype': dtype_str,
            'dtype_family': dtype_family,
            'min': data_min,
            'max': data_max,
            'is_uint16': bool(is_uint16),
            'is_binary': bool(is_binary),
            'passthrough': bool(is_uint16),
            'needs_intensity_decision': bool(not is_uint16 and not is_binary),
            'needs_range_decision': needs_range_decision,
            'range_policy': range_policy,
            'range_key': self._intensity_range_key(data_min, data_max),
        }

    def _load_raw_volume_for_probe(self, directory, scan):
        """
        Load raw volume voxels for intensity preflight (no dtype standardization).
        Returns (image_data, error_message).
        """
        scan_name = scan.get('name')
        scan_subtype = scan.get('subtype')
        try:
            if scan_subtype == "SCANCO vivaCT":
                aim_file = os.path.join(directory, f"{scan_name}.aim")
                if not os.path.exists(aim_file):
                    aim_file = os.path.join(directory, f"{scan_name}.AIM")
                if not os.path.exists(aim_file):
                    return None, f"AIM file not found for {scan_name}"
                return aim2numpy.extract(aim_file), None

            if scan_subtype == "TIFF Folder":
                scan_folder = os.path.join(directory, scan_name)
                image_data, _ = self.load_zeiss_image(scan_folder)
                return image_data, None

            if scan_subtype == "DICOM":
                scan_folder = os.path.join(directory, scan_name)
                _, image_data, _ = self.load_dicom_image(scan_folder)
                return image_data, None

            if scan_subtype == "Multi-page TIFF":
                scan_folder_tiff = os.path.join(directory, scan_name + ".tiff")
                scan_folder_tif = os.path.join(directory, scan_name + ".tif")
                if os.path.exists(scan_folder_tiff):
                    scan_folder = scan_folder_tiff
                elif os.path.exists(scan_folder_tif):
                    scan_folder = scan_folder_tif
                else:
                    return None, f"TIFF not found for {scan_name}"
                image_data, _, _ = self.load_multi_page_tiff(scan_folder)
                return image_data, None

            if scan_subtype == "NIfTI (.nii.gz)":
                path = os.path.join(directory, f"{scan_name}.nii.gz")
                if not os.path.exists(path):
                    return None, f"NIfTI not found for {scan_name}"
                return np.asanyarray(nib.load(path).dataobj), None

            if scan_subtype == "NIfTI (.nii)":
                path = os.path.join(directory, f"{scan_name}.nii")
                if not os.path.exists(path):
                    return None, f"NIfTI not found for {scan_name}"
                return np.asanyarray(nib.load(path).dataobj), None

            if scan_subtype == "MINC":
                mnc_file = os.path.join(directory, f"{scan_name}.mnc")
                if not os.path.exists(mnc_file):
                    mnc_file = os.path.join(directory, f"{scan_name}.MNC")
                if not os.path.exists(mnc_file):
                    return None, f"MINC not found for {scan_name}"
                image_data, _, _ = self.load_minc_image(mnc_file)
                if image_data is None:
                    return None, f"Failed to load MINC for {scan_name}"
                return image_data, None

            return None, f"Unsupported subtype for intensity probe: {scan_subtype}"
        except Exception as e:
            return None, str(e)

    def _collect_intensity_scan_stats(self, directory, volume_scans):
        stats = []
        for scan in volume_scans:
            scan_name = scan.get('name')
            if not scan_name:
                continue
            image_data, error = self._load_raw_volume_for_probe(directory, scan)
            if error or image_data is None:
                stats.append({
                    'name': scan_name,
                    'dtype': 'unknown',
                    'dtype_family': 'other',
                    'min': 0.0,
                    'max': 0.0,
                    'is_uint16': False,
                    'is_binary': False,
                    'passthrough': False,
                    'needs_intensity_decision': False,
                    'needs_range_decision': False,
                    'range_policy': 'error',
                    'range_key': 0.0,
                    'error': error or 'load failed',
                })
                continue
            try:
                stats.append(self._compute_intensity_scan_stats(scan_name, image_data))
            except Exception as e:
                stats.append({
                    'name': scan_name,
                    'dtype': str(getattr(image_data, 'dtype', 'unknown')),
                    'dtype_family': 'other',
                    'min': 0.0,
                    'max': 0.0,
                    'is_uint16': False,
                    'is_binary': False,
                    'passthrough': False,
                    'needs_intensity_decision': False,
                    'needs_range_decision': False,
                    'range_policy': 'error',
                    'range_key': 0.0,
                    'error': str(e),
                })
            finally:
                image_data = None
        return stats

    def _group_intensity_stats_by_value_family(self, intensity_stats):
        """
        Cluster non-passthrough volumes into value families by dtype family + range magnitude.
        uint16 passthrough subjects are returned as a separate informational group.
        """
        passthrough = [s for s in intensity_stats if s.get('passthrough') and not s.get('error')]
        decision = [
            s for s in intensity_stats
            if s.get('needs_range_decision') and not s.get('error')
        ]

        # Split decision scans by dtype family first, then by range magnitude within family.
        by_family = {}
        for s in decision:
            by_family.setdefault(s['dtype_family'], []).append(s)

        groups = []
        for family, members in by_family.items():
            members = sorted(members, key=lambda item: item.get('range_key', 0.0))
            clusters = []
            for info in members:
                if not clusters:
                    clusters.append([info])
                    continue
                keys = [item.get('range_key', 0.0) for item in clusters[-1]]
                center = float(np.median(keys))
                # ~1.5x on linear magnitude ≈ ~0.176 on log10; use absolute log gap.
                if abs(info.get('range_key', 0.0) - center) > 0.176:
                    clusters.append([info])
                else:
                    clusters[-1].append(info)

            for cluster in clusters:
                mins = [item['min'] for item in cluster]
                maxs = [item['max'] for item in cluster]
                groups.append({
                    'label': None,  # filled below
                    'subjects': [item['name'] for item in cluster],
                    'dtype_family': family,
                    'dtypes': sorted({item['dtype'] for item in cluster}),
                    'window_min': float(np.min(mins)),
                    'window_max': float(np.max(maxs)),
                    'passthrough': False,
                    'action_default': 'group_window',
                })

        # Stable labels Group A, B, ...
        for idx, group in enumerate(groups):
            group['label'] = f"Group {chr(ord('A') + idx)}"

        if passthrough:
            groups.append({
                'label': 'uint16 passthrough',
                'subjects': [item['name'] for item in passthrough],
                'dtype_family': 'uint16',
                'dtypes': ['uint16'],
                'window_min': float(np.min([item['min'] for item in passthrough])),
                'window_max': float(np.max([item['max'] for item in passthrough])),
                'passthrough': True,
                'action_default': 'passthrough',
            })

        return groups

    def _infer_existing_intensity_policy(self, extracted_dir):
        """Read intensity_value_mapping from already-extracted subjects."""
        groups_by_key = {}
        mapped_subjects = []
        unmapped_subjects = []

        if not os.path.isdir(extracted_dir):
            return {
                'has_quantitative_mapping': False,
                'mode': None,
                'groups': [],
                'mapped_subjects': [],
                'unmapped_subjects': [],
            }

        for entry in sorted(os.listdir(extracted_dir)):
            subject_dir = os.path.join(extracted_dir, entry)
            if not os.path.isdir(subject_dir):
                continue
            json_path = os.path.join(subject_dir, f"{entry}.json")
            if not os.path.exists(json_path):
                continue
            try:
                with open(json_path, 'r') as jf:
                    meta = json.load(jf)
            except Exception:
                continue
            if meta.get('is_mesh') and meta.get('voxelized') is False:
                continue
            mapping = meta.get('intensity_value_mapping')
            # Every extracted subject stores a reverse mapping, but only cohort windows
            # chosen in the extraction dialog define a reusable project policy.
            if not mapping or mapping.get('mode') not in ('shared_project', 'shared_subgroup'):
                unmapped_subjects.append(entry)
                continue
            mapped_subjects.append(entry)
            group_label = mapping.get('group_label') or 'existing'
            key = (
                group_label,
                float(mapping.get('window_min', 0.0)),
                float(mapping.get('window_max', 0.0)),
                mapping.get('mode'),
            )
            if key not in groups_by_key:
                groups_by_key[key] = {
                    'label': group_label,
                    'subjects': [],
                    'window_min': float(mapping.get('window_min', 0.0)),
                    'window_max': float(mapping.get('window_max', 0.0)),
                    'mode': mapping.get('mode'),
                    'mapping_scale': mapping.get('mapping_scale'),
                    'mapping_shift': mapping.get('mapping_shift'),
                    'passthrough': False,
                    'from_existing': True,
                }
            groups_by_key[key]['subjects'].append(entry)

        groups = list(groups_by_key.values())
        mode = None
        if groups:
            modes = {g.get('mode') for g in groups if g.get('mode')}
            if len(modes) == 1:
                mode = next(iter(modes))
            else:
                mode = 'shared_subgroup'

        return {
            'has_quantitative_mapping': len(mapped_subjects) > 0,
            'mode': mode,
            'groups': groups,
            'mapped_subjects': mapped_subjects,
            'unmapped_subjects': unmapped_subjects,
        }

    @staticmethod
    def _build_linear_value_mapping(
        original_dtype,
        output_dtype,
        mapping_scale,
        mapping_shift,
        mode,
        window_min=None,
        window_max=None,
        group_label=None,
    ):
        """
        Reverse mapping metadata for any extraction path.

        `mode` distinguishes cohort windows (shared_project / shared_subgroup, chosen in the
        extraction dialog) from automatic ones (passthrough / native / individual / binary_labels).
        Only cohort modes define a project-wide window policy.
        """
        return {
            'mode': mode,
            'group_label': group_label,
            'original_dtype': str(original_dtype),
            'output_dtype': str(output_dtype),
            'window_min': None if window_min is None else float(window_min),
            'window_max': None if window_max is None else float(window_max),
            'mapping_scale': float(mapping_scale),
            'mapping_shift': float(mapping_shift),
            'formula': 'original = stored * mapping_scale + mapping_shift',
        }

    @staticmethod
    def _build_intensity_value_mapping(original_dtype, window_min, window_max, mode, group_label):
        window_min = float(window_min)
        window_max = float(window_max)
        if window_max <= window_min:
            mapping_scale = 0.0
            mapping_shift = window_min
        else:
            mapping_scale = (window_max - window_min) / 65535.0
            mapping_shift = window_min
        return {
            'mode': mode,
            'group_label': group_label,
            'original_dtype': str(original_dtype),
            'output_dtype': 'uint16',
            'window_min': window_min,
            'window_max': window_max,
            'mapping_scale': float(mapping_scale),
            'mapping_shift': float(mapping_shift),
            'formula': 'original = uint16 * mapping_scale + mapping_shift',
        }

    def _apply_shared_intensity_window(self, image_data, window_min, window_max):
        """Clip to shared window and scale to uint16. Returns (uint16 array, mapping fields without dtype/mode)."""
        image_data_float = np.asarray(image_data, dtype=np.float64)
        window_min = float(window_min)
        window_max = float(window_max)
        clipped = np.clip(image_data_float, window_min, window_max)
        if window_max > window_min:
            scaled = (clipped - window_min) / (window_max - window_min) * 65535.0
        else:
            scaled = np.zeros_like(clipped)
        return scaled.astype(np.uint16)

    def _intensity_window_for_scan(self, scan_name, intensity_options):
        """Resolve shared window for a scan from intensity_extraction_options. None => individual/passthrough."""
        if not intensity_options:
            return None
        if not intensity_options.get('quantitative'):
            return None
        mode = intensity_options.get('mode') or 'individual'
        if mode == 'individual':
            return None
        subject_windows = intensity_options.get('subject_windows') or {}
        if scan_name in subject_windows:
            win = subject_windows[scan_name]
            return {
                'window_min': float(win['window_min']),
                'window_max': float(win['window_max']),
                'mode': win.get('mode') or mode,
                'group_label': win.get('group_label'),
            }
        for group in intensity_options.get('groups') or []:
            if group.get('passthrough') or group.get('action') == 'passthrough':
                continue
            if scan_name in (group.get('subjects') or []):
                return {
                    'window_min': float(group['window_min']),
                    'window_max': float(group['window_max']),
                    'mode': group.get('mode') or mode,
                    'group_label': group.get('label'),
                }
        return None

    def _assign_pending_to_existing_intensity_groups(self, pending_stats, existing_policy):
        """
        For incremental extract: match pending non-uint16 scans to existing mapped groups.
        Returns (assignments, new_subgroup_alerts).
        assignments: list of {name, group_label, window_min, window_max, is_new_subgroup}
        """
        existing_groups = [
            g for g in (existing_policy.get('groups') or [])
            if not g.get('passthrough')
        ]
        assignments = []
        alerts = []

        for stat in pending_stats:
            if not stat.get('needs_range_decision') or stat.get('error'):
                continue
            best = None
            best_score = None
            scan_mid = 0.5 * (stat['min'] + stat['max'])
            scan_span = max(abs(stat['max'] - stat['min']), 1e-12)
            for group in existing_groups:
                g_min = float(group['window_min'])
                g_max = float(group['window_max'])
                g_mid = 0.5 * (g_min + g_max)
                g_span = max(abs(g_max - g_min), 1e-12)
                # Overlap score: distance of scan midpoint to group window, normalized.
                if scan_mid < g_min:
                    dist = (g_min - scan_mid) / g_span
                elif scan_mid > g_max:
                    dist = (scan_mid - g_max) / g_span
                else:
                    dist = 0.0
                # Also penalize very different spans
                span_ratio = max(scan_span / g_span, g_span / scan_span)
                score = dist + 0.25 * max(0.0, span_ratio - 1.0)
                if best_score is None or score < best_score:
                    best_score = score
                    best = group

            # Far outside: midpoint more than 50% of group span beyond window, or span wildly different
            is_new = best is None or best_score is None or best_score > 0.5
            if is_new:
                label = f"new:{stat['name']}"
                assignments.append({
                    'name': stat['name'],
                    'group_label': label,
                    'window_min': float(stat['min']),
                    'window_max': float(stat['max']),
                    'is_new_subgroup': True,
                    'suggested_nearest': best.get('label') if best else None,
                })
                alerts.append({
                    'scan': stat['name'],
                    'dtype': stat.get('dtype'),
                    'min': float(stat['min']),
                    'max': float(stat['max']),
                    'message': (
                        f"{stat['name']} falls outside existing intensity groups "
                        f"and looks like a new value family."
                    ),
                    'suggested_nearest': best.get('label') if best else None,
                })
            else:
                assignments.append({
                    'name': stat['name'],
                    'group_label': best['label'],
                    'window_min': float(best['window_min']),
                    'window_max': float(best['window_max']),
                    'is_new_subgroup': False,
                    'suggested_nearest': best['label'],
                })
        return assignments, alerts

    def _prepare_scan_image_data(self, image_data, intensity_options=None, scan_name=None):
        """
        Detect binary input, apply shared quantitative window when requested,
        otherwise standard dtype conversion.

        Returns:
            tuple: (image_data, is_binary, intensity_value_mapping_or_None)
        """
        if self._is_binary_label_image(image_data):
            scaled, label_min, label_max = self._scale_binary_to_uint16_with_labels(image_data)
            binary_mapping = self._build_linear_value_mapping(
                np.asarray(image_data).dtype,
                'uint16',
                (label_max - label_min) / 65535.0 if label_max > label_min else 0.0,
                label_min,
                'binary_labels',
                window_min=label_min,
                window_max=label_max,
            )
            return scaled, True, binary_mapping

        arr = np.asarray(image_data)
        if arr.dtype == np.uint16:
            return arr.astype(np.uint16), False, self._build_linear_value_mapping(
                arr.dtype, 'uint16', 1.0, 0.0, 'passthrough', window_min=0.0, window_max=65535.0
            )

        window = self._intensity_window_for_scan(scan_name, intensity_options) if scan_name else None
        if window is not None:
            original_dtype = arr.dtype
            converted = self._apply_shared_intensity_window(
                arr, window['window_min'], window['window_max']
            )
            mapping = self._build_intensity_value_mapping(
                original_dtype,
                window['window_min'],
                window['window_max'],
                window.get('mode') or 'shared_subgroup',
                window.get('group_label'),
            )
            print(
                f"Shared intensity window [{window['window_min']:g}, {window['window_max']:g}] "
                f"→ uint16 for {scan_name}"
            )
            return converted, False, mapping

        converted, auto_mapping = self._standardize_image_dtype_with_mapping(arr)
        return converted, False, auto_mapping

    def _standardize_image_dtype_with_mapping(self, image_data):
        """
        Standardize dtype and describe how to get back to the original values.

        Bounded integer types keep their full native domain (no fake precision expansion);
        wide types (float / int32+) are stretched from their own observed range, which is
        the per-scan equivalent of a shared window.
        """
        arr = np.asarray(image_data)
        original_dtype = arr.dtype
        converted = self._standardize_image_dtype(arr)

        native_domains = {
            np.dtype(np.uint8): (0.0, 255.0, 1.0, 0.0),
            np.dtype(np.int8): (-128.0, 127.0, 1.0, -128.0),
            np.dtype(np.uint16): (0.0, 65535.0, 1.0, 0.0),
            np.dtype(np.int16): (-32768.0, 32767.0, 1.0, -32768.0),
        }
        native = native_domains.get(np.dtype(original_dtype))
        if native is not None:
            domain_min, domain_max, scale, shift = native
            return converted, self._build_linear_value_mapping(
                original_dtype, converted.dtype, scale, shift, 'native',
                window_min=domain_min, window_max=domain_max,
            )

        data_min = float(np.min(arr)) if arr.size else 0.0
        data_max = float(np.max(arr)) if arr.size else 0.0
        scale = (data_max - data_min) / 65535.0 if data_max > data_min else 0.0
        return converted, self._build_linear_value_mapping(
            original_dtype, converted.dtype, scale, data_min, 'individual',
            window_min=data_min, window_max=data_max,
        )

    def _standardize_image_dtype(self, image_data):
        """
        Standardize image data types according to the following rules:
        - 8-bit (int8/uint8) → uint8 
        - 16-bit (int16/uint16) → uint16
        - 32-bit or 64-bit (any type) → uint16 (with proper scaling)
        
        Args:
            image_data (numpy array): The image data to standardize
            
        Returns:
            numpy array: The standardized image data
        """
        original_dtype = image_data.dtype
        print(f"Original data type: {original_dtype}")
        
        # 8-bit data types - convert to uint8
        if original_dtype in [np.int8, np.uint8]:
            if original_dtype == np.int8:
                # Convert int8 to uint8 by shifting the range
                # int8 range: -128 to 127 → uint8 range: 0 to 255
                image_data = image_data.astype(np.float32)
                image_data = image_data + 128  # Shift by 128
                image_data = np.clip(image_data, 0, 255)  # Ensure valid range
                image_data = image_data.astype(np.uint8)
                print(f"Converted int8 to uint8")
            else:
                # Already uint8, just ensure type
                image_data = image_data.astype(np.uint8)
                print(f"Keeping as uint8")
                
        # 16-bit data types - convert to uint16
        elif original_dtype in [np.int16, np.uint16]:
            if original_dtype == np.int16:
                # Convert int16 to uint16 by shifting the range
                # int16 range: -32768 to 32767 → uint16 range: 0 to 65535
                image_data = image_data.astype(np.float32)
                image_data = image_data + 32768  # Shift by 32768
                image_data = np.clip(image_data, 0, 65535)  # Ensure valid range
                image_data = image_data.astype(np.uint16)
                print(f"Converted int16 to uint16")
            else:
                # Already uint16, just ensure type
                image_data = image_data.astype(np.uint16)
                print(f"Keeping as uint16")
                
        # 32-bit or 64-bit data types - convert to uint16 with proper scaling
        elif original_dtype in [np.int32, np.uint32, np.int64, np.uint64, np.float16, np.float32, np.float64]:
            # Convert to float for processing
            image_data_float = image_data.astype(np.float64)

            print(f"Converting {original_dtype} to uint16 with scaling")
            
            # Get min and max values for scaling
            data_min = np.min(image_data_float)
            data_max = np.max(image_data_float)
            
            print(f"Data range: {data_min} to {data_max}")
            
            # Scale to uint16 range (0-65535)
            if data_max > data_min:
                # Normalize to 0-1 range first
                image_data_normalized = (image_data_float - data_min) / (data_max - data_min)
                # Scale to uint16 range
                image_data = (image_data_normalized * 65535).astype(np.uint16)
            else:
                # All values are the same, set to 0
                image_data = np.zeros_like(image_data_float, dtype=np.uint16)
                
            print(f"Converted {original_dtype} to uint16")
            
        else:
            # Unknown data type, try to convert to uint16
            print(f"Unknown data type {original_dtype}, attempting conversion to uint16")
            try:
                image_data_float = image_data.astype(np.float64)
                data_min = np.min(image_data_float)
                data_max = np.max(image_data_float)
                
                if data_max > data_min:
                    image_data_normalized = (image_data_float - data_min) / (data_max - data_min)
                    image_data = (image_data_normalized * 65535).astype(np.uint16)
                else:
                    image_data = np.zeros_like(image_data_float, dtype=np.uint16)
            except Exception as e:
                print(f"Error converting {original_dtype} to uint16: {e}")
                # Fallback to uint16 with clipping
                image_data = np.clip(image_data.astype(np.float64), 0, 65535).astype(np.uint16)
        
        print(f"Final data type: {image_data.dtype}")
        return image_data

    def _safe_threshold_li(self, data):
        """Compute Li threshold with a safe initial guess for sparse/binary histograms."""
        data = np.asarray(data)
        if data.size == 0:
            return 0

        data_min = float(np.min(data))
        data_max = float(np.max(data))
        if data_min >= data_max:
            return int(data_min)

        initial_guess = float(np.percentile(data, 95))
        margin = max((data_max - data_min) * 0.01, 1.0)
        interior_min = data_min + margin
        interior_max = data_max - margin
        if interior_min >= interior_max:
            return int((data_min + data_max) / 2)
        initial_guess = float(np.clip(initial_guess, interior_min, interior_max))

        try:
            return int(threshold_li(data, initial_guess=initial_guess))
        except Exception as e:
            print(f"Li thresholding failed: {e}. Using midpoint fallback.")
            return int((data_min + data_max) / 2)

    def _compute_extraction_threshold(self, blurred_image_data, find_major_peaks):
        hist, bin_edges = np.histogram(blurred_image_data.flatten(), bins=256)

        print("Looking for peaks")
        peak_intensities = find_major_peaks(hist, bin_edges[:-1])

        print("Calculating threshold")

        data_min = float(np.min(blurred_image_data))
        data_max = float(np.max(blurred_image_data))
        unique_count = len(np.unique(blurred_image_data))

        if unique_count <= 2 or (data_max - data_min) < 1e-6:
            if data_min == data_max:
                threshold = int(data_min)
            else:
                foreground_vals = blurred_image_data[blurred_image_data > data_min]
                threshold = int(np.median(foreground_vals)) if foreground_vals.size > 0 else int((data_min + data_max) / 2)
        elif len(peak_intensities) >= 2:
            second_peak_intensity = peak_intensities[1]
            masked_data = blurred_image_data[blurred_image_data > second_peak_intensity]
            if len(masked_data) > 0:
                local_threshold = self._safe_threshold_li(masked_data)
                threshold = max(int(local_threshold), int(second_peak_intensity))
            else:
                threshold = int(second_peak_intensity * 1.2)
        else:
            threshold = self._safe_threshold_li(blurred_image_data)

        print("Threshold: "+str(threshold))
        return threshold

    def _is_fully_extracted(self, extracted_dir, scan_name):
        """Return True only when extracted metadata is complete enough to use."""
        scan_folder = os.path.join(extracted_dir, scan_name)
        json_file = os.path.join(scan_folder, f"{scan_name}.json")
        if not os.path.exists(json_file):
            return False

        try:
            with open(json_file, 'r') as jf:
                metadata = json.load(jf)
        except Exception:
            return False

        if metadata.get('is_mesh') and metadata.get('voxelized') is False:
            required_files = [
                os.path.join(scan_folder, f"{scan_name}.ply"),
                json_file,
            ]
            required_keys = ('name', 'original_format', 'is_mesh', 'voxelized')
            return all(os.path.exists(path) for path in required_files) and all(key in metadata for key in required_keys)

        required_files = [
            os.path.join(scan_folder, f"{scan_name}.nii.gz"),
            os.path.join(scan_folder, f"{scan_name}_lossy.nii.gz"),
            json_file,
        ]
        if not all(os.path.exists(path) for path in required_files):
            return False

        required_keys = ('name', 'voxel_size', 'threshold', 'original_format')
        return all(key in metadata for key in required_keys)

    def _check_and_resample_if_anisotropic(self, image_data, voxel_sizes, verbose=False):
        """
        Check if voxel sizes are anisotropic and resample if needed.
        
        Args:
            image_data: 3D numpy array
            voxel_sizes: tuple of (x, y, z) voxel sizes in mm
            verbose: enable verbose output
            
        Returns:
            tuple: (resampled_image_data, isotropic_voxel_size, was_resampled)
        """
        # Check if any dimension is significantly different (>10% difference)
        min_voxel = min(voxel_sizes)
        max_voxel = max(voxel_sizes)
        anisotropy_ratio = max_voxel / min_voxel
        
        if verbose:
            print(f"Voxel sizes: {voxel_sizes}")
            print(f"Anisotropy ratio: {anisotropy_ratio:.3f}")
        
        # If anisotropy ratio > 1.1 (10% difference), consider it anisotropic
        if anisotropy_ratio > 1.1:
            print(f"🔄 Anisotropic voxels detected (ratio: {anisotropy_ratio:.2f}), resampling to isotropic...")
            
            try:
                # Create interpolator
                interpolator = DeformationBasedMRIInterpolator(
                    registration_type='SyNOnly',  # Use SyNOnly for better performance
                    verbose=verbose
                )
                
                # Resample to isotropic
                resampled_data = interpolator.interpolate_anisotropic_to_isotropic(
                    image_data, voxel_sizes
                )
                
                # The target voxel size is the minimum of the original voxel sizes
                isotropic_voxel_size = min(voxel_sizes)
                
                print(f"✅ Resampling completed. New shape: {resampled_data.shape}")
                print(f"✅ Isotropic voxel size: {isotropic_voxel_size:.3f} mm")
                
                return resampled_data, isotropic_voxel_size, True
                
            except Exception as e:
                print(f"⚠️ Warning: Anisotropic resampling failed: {e}")
                print("Proceeding with original anisotropic data...")
                # Fall back to using minimum voxel size
                return image_data, min(voxel_sizes), False
        else:
            if verbose:
                print("✅ Voxels are already isotropic")
            return image_data, voxel_sizes[0], False

    def _extract_3d_voxel_sizes(self, scan_subtype, scan_name, directory, **kwargs):
        """
        Extract 3D voxel sizes (x, y, z) for different scan types.
        
        Returns:
            tuple: (x, y, z) voxel sizes in mm
        """
        if scan_subtype == "SCANCO vivaCT":
            aim_file = kwargs.get('aim_file')
            header_data = kwargs.get('header_data')
            
            if header_data and 'element_size' in header_data:
                # SCANCO typically has isotropic voxels, but extract all three
                element_sizes = header_data['element_size']
                if len(element_sizes) >= 3:
                    return (float(element_sizes[0]), float(element_sizes[1]), float(element_sizes[2]))
                else:
                    # If only one value, assume isotropic
                    voxel_size = float(element_sizes[0])
                    return (voxel_size, voxel_size, voxel_size)
        
        elif scan_subtype == "DICOM":
            scanner_metadata = kwargs.get('scanner_metadata', {})
            geometry = scanner_metadata.get('geometry', {})
            
            pixel_spacing = geometry.get('pixel_spacing', [1.0, 1.0])
            slice_thickness = geometry.get('slice_thickness', pixel_spacing[0])
            
            return (float(pixel_spacing[0]), float(pixel_spacing[1]), float(slice_thickness))
        
        elif scan_subtype in ["TIFF Folder", "Multi-page TIFF"]:
            # For TIFF, we typically assume isotropic in x-y, but z might be different
            # This would need to be enhanced based on your TIFF metadata extraction
            voxel_size = kwargs.get('voxel_size', 1.0)
            return (voxel_size, voxel_size, voxel_size)
        
        elif scan_subtype in ["NIfTI (.nii.gz)", "NIfTI (.nii)"]:
            nii_img = kwargs.get('nii_img')
            if nii_img:
                zooms = nii_img.header.get_zooms()
                if len(zooms) >= 3:
                    return (float(zooms[0]), float(zooms[1]), float(zooms[2]))
                else:
                    voxel_size = float(zooms[0])
                    return (voxel_size, voxel_size, voxel_size)

        elif scan_subtype == "MINC":
            # Voxel sizes already extracted by load_minc_image; passed through via kwargs
            voxel_sizes_tuple = kwargs.get('voxel_sizes_tuple')
            if voxel_sizes_tuple and len(voxel_sizes_tuple) >= 3:
                return (abs(float(voxel_sizes_tuple[0])),
                        abs(float(voxel_sizes_tuple[1])),
                        abs(float(voxel_sizes_tuple[2])))
            # Fallback: try to read from nibabel directly
            nii_img = kwargs.get('nii_img')
            if nii_img:
                zooms = nii_img.header.get_zooms()
                if len(zooms) >= 3:
                    return (abs(float(zooms[0])), abs(float(zooms[1])), abs(float(zooms[2])))
                else:
                    voxel_size = abs(float(zooms[0]))
                    return (voxel_size, voxel_size, voxel_size)

        # Default fallback
        voxel_size = kwargs.get('voxel_size', 1.0)
        return (voxel_size, voxel_size, voxel_size)

    def post(self, request, *args, **kwargs):

        directory = request.data.get('directory')
        scans = request.data.get('scans')

        if not directory or not scans:
            return Response({'error': 'Missing required parameters'}, status=status.HTTP_400_BAD_REQUEST)

        extracted_dir = os.path.join(directory, 'extracted')
        os.makedirs(extracted_dir, exist_ok=True)

        try:
            # Build a map of available segmentation files/folders in the source directory
            segmentation_map = self._find_segmentations_map(directory)

            # Filter out scans that are already fully extracted (partial json counts as incomplete)
            scans = [
                scan for scan in scans
                if not self._is_fully_extracted(extracted_dir, scan['name'])
            ]

            # Skip any entries that are segmentations ('.seg.' or ending with '.seg')
            scans = [s for s in scans if not self._is_segmentation_name(s['name'])]

            # Skip segmentations and atlas folder
            scans = [s for s in scans if not self._is_segmentation_name(s['name']) and s['name'].lower() != 'atlas']

            mesh_options = request.data.get('mesh_extraction_options') or {}
            mesh_mode = mesh_options.get('mode', 'keep')
            skipped_mesh_subjects = set(mesh_options.get('skipped_subjects') or [])
            mesh_voxel_size = None
            if mesh_mode == 'voxelize':
                mesh_voxel_size = self._derive_mesh_voxel_size(directory, scans, mesh_options)

            intensity_options = request.data.get('intensity_extraction_options') or {}
            # Build subject_windows lookup for O(1) resolve during prepare
            if intensity_options.get('quantitative') and intensity_options.get('groups'):
                subject_windows = dict(intensity_options.get('subject_windows') or {})
                mode = intensity_options.get('mode') or 'shared_subgroup'
                for group in intensity_options.get('groups') or []:
                    if group.get('passthrough') or group.get('action') == 'passthrough':
                        continue
                    if group.get('action') == 'merge_project':
                        continue  # resolved below after merge
                    for subject in group.get('subjects') or []:
                        subject_windows[subject] = {
                            'window_min': float(group['window_min']),
                            'window_max': float(group['window_max']),
                            'mode': group.get('mode') or mode,
                            'group_label': group.get('label'),
                        }
                # Handle merge_project: one combined window across all non-passthrough groups
                merge_subjects = []
                merge_mins = []
                merge_maxs = []
                for group in intensity_options.get('groups') or []:
                    if group.get('passthrough') or group.get('action') == 'passthrough':
                        continue
                    if group.get('action') == 'merge_project':
                        merge_subjects.extend(group.get('subjects') or [])
                        merge_mins.append(float(group['window_min']))
                        merge_maxs.append(float(group['window_max']))
                if merge_subjects and merge_mins and merge_maxs:
                    merged_min = float(min(merge_mins))
                    merged_max = float(max(merge_maxs))
                    # Also include groups that were not merge but user chose shared_project mode
                    for subject in merge_subjects:
                        subject_windows[subject] = {
                            'window_min': merged_min,
                            'window_max': merged_max,
                            'mode': 'shared_project',
                            'group_label': 'project',
                        }
                if intensity_options.get('mode') == 'shared_project':
                    non_pass = [
                        g for g in (intensity_options.get('groups') or [])
                        if not g.get('passthrough') and g.get('action') != 'passthrough'
                    ]
                    if non_pass:
                        pmin = float(min(float(g['window_min']) for g in non_pass))
                        pmax = float(max(float(g['window_max']) for g in non_pass))
                        for group in non_pass:
                            for subject in group.get('subjects') or []:
                                subject_windows[subject] = {
                                    'window_min': pmin,
                                    'window_max': pmax,
                                    'mode': 'shared_project',
                                    'group_label': group.get('label') or 'project',
                                }
                intensity_options = dict(intensity_options)
                intensity_options['subject_windows'] = subject_windows

            total_scans = len(scans)

            # If nothing to do, send a final progress (if possible) and return
            if total_scans == 0:
                channel_layer = get_channel_layer()
                if channel_layer is not None:
                    async_to_sync(channel_layer.group_send)(
                        'progress_group',
                        {
                            'type': 'send_progress',
                            'progress': 1,
                            'scan_name': '',
                            'total': 0,
                            'custom_message': 'Done extracting scans!',
                            'current': 0,
                        }
                    )
                return Response({'message': 'No new scans to extract'})

            # Send progress update via WebSocket
            progress = 0
            print("Extracting scans... "+str(progress))
            channel_layer = get_channel_layer()
            if channel_layer is not None:
                async_to_sync(channel_layer.group_send)(
                    'progress_group',
                    {
                        'type': 'send_progress',
                        'progress': progress,
                        'scan_name': scans[0]['name'],
                        'total': total_scans,
                        'custom_message': 'Extracting scans...',
                        'current': 0,
                    }
                )

            

            for idx, scan in enumerate(scans):
                scan_name = scan['name']
                scan_subtype = scan['subtype']   

                # Send progress update via WebSocket
                progress = idx / total_scans
                print("Extracting scan number "+str(idx+1)+" of "+str(total_scans)+" - "+scan_name+"... "+str(progress))
                channel_layer = get_channel_layer()
                if channel_layer is not None:
                    async_to_sync(channel_layer.group_send)(
                        'progress_group',
                        {
                            'type': 'send_progress',
                            'progress': progress,
                            'scan_name': scan_name,
                            'total': total_scans,
                            'custom_message': 'Extracting '+scan_name+'...',
                            'current': idx+1,
                        }
                    )

                scan_out_folder = os.path.join(extracted_dir, scan_name)
                if not os.path.exists(scan_out_folder):
                    os.makedirs(scan_out_folder)

                scanner_metadata = None 
                image_data = None
                voxel_sizes = None  # Change to store 3D voxel sizes
                is_binary = False
                extra_json_metadata = {}
                intensity_value_mapping = None

                if scan_subtype == "SCANCO vivaCT":
                    aim_file = os.path.join(directory, f"{scan_name}.aim")
                    if not os.path.exists(aim_file):
                        aim_file = os.path.join(directory, f"{scan_name}.AIM")
                    
                    image_data = aim2numpy.extract(aim_file)
                    header_data = aim2numpy.get_header_info(aim_file)
                    
                    # Extract 3D voxel sizes
                    voxel_sizes = self._extract_3d_voxel_sizes(
                        scan_subtype, scan_name, directory, 
                        aim_file=aim_file, header_data=header_data
                    )
                    
                    # Standardize data type
                    image_data, is_binary, intensity_value_mapping = self._prepare_scan_image_data(
                        image_data, intensity_options=intensity_options, scan_name=scan_name
                    )
                    
                elif scan_subtype == "TIFF Folder":
                    scan_folder = os.path.join(directory, scan_name)
                    image_data, voxel_size = self.load_zeiss_image(scan_folder)
                    
                    # For now, assume isotropic for TIFF (can be enhanced)
                    voxel_sizes = (voxel_size, voxel_size, voxel_size)
                    
                    # Standardize data type
                    image_data, is_binary, intensity_value_mapping = self._prepare_scan_image_data(
                        image_data, intensity_options=intensity_options, scan_name=scan_name
                    )
                    
                elif scan_subtype == "DICOM":
                    scan_folder = os.path.join(directory, scan_name)
                    if os.path.exists(os.path.join(scan_folder, "DICOMDIR")) or any(f.endswith('.dcm') for f in os.listdir(scan_folder)):
                        voxel_size_single, image_data, scanner_metadata = self.load_dicom_image(scan_folder)
                        
                        # Extract 3D voxel sizes from DICOM metadata
                        voxel_sizes = self._extract_3d_voxel_sizes(
                            scan_subtype, scan_name, directory,
                            scanner_metadata=scanner_metadata
                        )
                        
                        # Standardize data type
                        image_data, is_binary, intensity_value_mapping = self._prepare_scan_image_data(
                            image_data, intensity_options=intensity_options, scan_name=scan_name
                        )
                        
                elif scan_subtype == "Multi-page TIFF":
                    scan_folder_tiff = os.path.join(directory, scan_name + ".tiff")
                    scan_folder_tif = os.path.join(directory, scan_name + ".tif")
                    
                    if os.path.exists(scan_folder_tiff):
                        scan_folder = scan_folder_tiff
                    elif os.path.exists(scan_folder_tif):
                        scan_folder = scan_folder_tif
                    else:
                        print(f"Warning: Neither {scan_name}.tiff nor {scan_name}.tif found, skipping...")
                        continue
                        
                    image_data, voxel_size, scanner_metadata = self.load_multi_page_tiff(scan_folder)
                    
                    # For now, assume isotropic for TIFF (can be enhanced)
                    voxel_sizes = (voxel_size, voxel_size, voxel_size)
                    
                    # Standardize data type
                    image_data, is_binary, intensity_value_mapping = self._prepare_scan_image_data(
                        image_data, intensity_options=intensity_options, scan_name=scan_name
                    )
                    
                elif scan_subtype == "NIfTI (.nii.gz)":
                    nii_gz_file = os.path.join(directory, f"{scan_name}.nii.gz")
                    if os.path.exists(nii_gz_file):
                        # Load the NIfTI file to extract metadata and voxel sizes
                        nii_img = nib.load(nii_gz_file)
                        image_data = np.asanyarray(nii_img.dataobj)
                        
                        # Extract 3D voxel sizes
                        voxel_sizes = self._extract_3d_voxel_sizes(
                            scan_subtype, scan_name, directory,
                            nii_img=nii_img
                        )
                        
                        # Standardize data type
                        image_data, is_binary, intensity_value_mapping = self._prepare_scan_image_data(
                            image_data, intensity_options=intensity_options, scan_name=scan_name
                        )
                        
                        # Extract scanner metadata from NIfTI header
                        scanner_metadata = self._extract_nifti_metadata(nii_img)
                    else:
                        continue
                        
                elif scan_subtype == "NIfTI (.nii)":
                    nii_file = os.path.join(directory, f"{scan_name}.nii")
                    if os.path.exists(nii_file):
                        # Load the NIfTI file
                        nii_img = nib.load(nii_file)
                        image_data = np.asanyarray(nii_img.dataobj)
                        
                        # Extract 3D voxel sizes
                        voxel_sizes = self._extract_3d_voxel_sizes(
                            scan_subtype, scan_name, directory,
                            nii_img=nii_img
                        )
                        
                        # Standardize data type
                        image_data, is_binary, intensity_value_mapping = self._prepare_scan_image_data(
                            image_data, intensity_options=intensity_options, scan_name=scan_name
                        )
                        
                        # Extract scanner metadata from NIfTI header
                        scanner_metadata = self._extract_nifti_metadata(nii_img)
                    else:
                        continue

                elif scan_subtype == "MINC":
                    # Probe both lowercase and uppercase extensions
                    mnc_file = os.path.join(directory, f"{scan_name}.mnc")
                    if not os.path.exists(mnc_file):
                        mnc_file = os.path.join(directory, f"{scan_name}.MNC")
                    if os.path.exists(mnc_file):
                        image_data, voxel_sizes, scanner_metadata = self.load_minc_image(mnc_file)
                        if image_data is None:
                            continue
                        # Standardize data type
                        image_data, is_binary, intensity_value_mapping = self._prepare_scan_image_data(
                            image_data, intensity_options=intensity_options, scan_name=scan_name
                        )
                    else:
                        continue

                elif self._is_mesh_subtype(scan_subtype):
                    if scan_name in skipped_mesh_subjects:
                        print(f"Skipping mesh {scan_name} by user request")
                        continue

                    mesh_path = self._mesh_source_path(directory, scan_name, scan_subtype)
                    if not mesh_path:
                        print(f"Warning: mesh file for {scan_name} not found, skipping...")
                        continue

                    scale_factor = self._mesh_scale_factor_for_scan(scan_name, mesh_options)
                    group_label = (mesh_options.get('subject_scale_groups') or {}).get(scan_name)
                    builtin_texture_meta = None
                    extracted_face_uvs = None
                    if mesh_mode != 'voxelize':
                        builtin_texture_meta = detect_and_extract_builtin_texture(
                            mesh_path, scan_out_folder, scan_name
                        )
                        if builtin_texture_meta:
                            from .openUsdMeshTools import is_openusd_mesh_source, load_openusd_face_corner_uvs
                            from .builtinTextureTools import _load_single_trimesh

                            raw_vertices = raw_faces = None
                            if is_openusd_mesh_source(mesh_path):
                                raw_vertices, raw_faces, extracted_face_uvs = load_openusd_face_corner_uvs(
                                    mesh_path, scale_factor=scale_factor
                                )
                            else:
                                raw_mesh = _load_single_trimesh(mesh_path)
                                if raw_mesh is not None and scale_factor != 1.0:
                                    raw_mesh.vertices = (
                                        np.asarray(raw_mesh.vertices, dtype=np.float64) * float(scale_factor)
                                    )
                                if raw_mesh is not None:
                                    raw_vertices = np.asarray(raw_mesh.vertices, dtype=np.float64)
                                    raw_faces = np.asarray(raw_mesh.faces, dtype=np.int64)
                                extracted_face_uvs = extract_face_corner_uvs(raw_mesh)
                            if extracted_face_uvs is None:
                                print(
                                    f"Built-in texture metadata found for {scan_name} but UV "
                                    "extraction failed; disabling built-in texture."
                                )
                                builtin_texture_meta = None
                            else:
                                mesh_for_uv_align = self._load_mesh_for_extraction(
                                    mesh_path, scale_factor=scale_factor
                                )
                                aligned_faces = np.asarray(mesh_for_uv_align.faces, dtype=np.int64)
                                if (
                                    raw_vertices is not None
                                    and raw_faces is not None
                                    and (
                                        aligned_faces.shape != raw_faces.shape
                                        or not np.array_equal(aligned_faces, raw_faces)
                                    )
                                ):
                                    extracted_face_uvs = remap_face_uvs_for_decimated_mesh(
                                        raw_vertices,
                                        raw_faces,
                                        extracted_face_uvs,
                                        np.asarray(mesh_for_uv_align.vertices, dtype=np.float64),
                                        aligned_faces,
                                    )
                                if extracted_face_uvs is None:
                                    print(
                                        f"Built-in texture metadata found for {scan_name} but UV "
                                        "alignment after mesh welding failed; disabling built-in texture."
                                    )
                                    builtin_texture_meta = None
                    mesh = self._load_mesh_for_extraction(mesh_path, scale_factor=scale_factor)
                    extract_centroid = _center_trimesh_at_surface_centroid(mesh)
                    mesh_summary = self._mesh_summary(mesh, scan_name, scale_factor=scale_factor, group_label=group_label)
                    mesh_summary.update({
                        'source_file': os.path.basename(mesh_path),
                        'extract_centroid': extract_centroid.tolist(),
                        'coordinate_origin': 'surface_centroid',
                    })

                    if mesh_mode == 'voxelize':
                        final_mesh_voxel_size = mesh_voxel_size or self._derive_mesh_voxel_size(directory, [scan], mesh_options)
                        image_data, voxelization_warning = self._voxelize_mesh_to_volume(mesh, final_mesh_voxel_size)
                        voxel_sizes = (final_mesh_voxel_size, final_mesh_voxel_size, final_mesh_voxel_size)
                        is_binary = True
                        scanner_metadata = {
                            'mesh_extraction': {
                                'assumed_units': 'mm',
                                'voxelized': True,
                                'voxelization_warning': voxelization_warning,
                            }
                        }
                        extra_json_metadata = {
                            'is_mesh': True,
                            'voxelized': True,
                            'mesh_metadata': mesh_summary,
                            'mesh_scale': {
                                'assumed_units_after_scaling': 'mm',
                                'scale_factor': float(scale_factor),
                                'scale_group': group_label,
                            },
                            'voxelization_warning': voxelization_warning,
                        }
                    else:
                        ply_file = os.path.join(scan_out_folder, f"{scan_name}.ply")
                        self._save_mesh_as_ply(mesh, ply_file)
                        json_file = os.path.join(scan_out_folder, f"{scan_name}.json")
                        json_metadata = {
                            'name': scan_name,
                            'original_format': scan_subtype,
                            'is_mesh': True,
                            'voxelized': False,
                            'coordinate_origin': 'surface_centroid',
                            'source_file': os.path.basename(mesh_path),
                            'mesh_file': f"{scan_name}.ply",
                            'mesh_metadata': mesh_summary,
                            'mesh_scale': {
                                'assumed_units_after_scaling': 'mm',
                                'scale_factor': float(scale_factor),
                                'scale_group': group_label,
                            },
                        }
                        if builtin_texture_meta:
                            json_metadata['builtin_texture'] = builtin_texture_meta
                            if extracted_face_uvs is not None:
                                save_uv_sidecar(ply_file, extracted_face_uvs)
                        with open(json_file, 'w') as jf:
                            json.dump(json_metadata, jf, indent=4)
                        print(scan_name+" mesh saved")
                        continue

                else:
                    continue

                if image_data is not None and image_data.ndim > 3:
                    channel_axis = int(np.argmin(image_data.shape))
                    print(
                        f"4D+ volume (shape {image_data.shape}), "
                        f"reducing to 3D via channel axis {channel_axis}"
                    )
                    image_data = self._reduce_extra_dims_to_3d(image_data)

                # 🔄 NEW: Check for anisotropic voxels and resample if needed
                if image_data is not None and voxel_sizes is not None:
                    print(f"Processing {scan_name}: shape {image_data.shape}, voxel sizes {voxel_sizes}")
                    
                    # Check and resample if anisotropic
                    image_data, final_voxel_size, was_resampled = self._check_and_resample_if_anisotropic(
                        image_data, voxel_sizes, verbose=True
                    )
                    
                    if was_resampled:
                        print(f"✅ {scan_name} resampled from {voxel_sizes} to isotropic {final_voxel_size:.3f} mm")
                        
                        # Update scanner metadata to indicate resampling was performed
                        if scanner_metadata is None:
                            scanner_metadata = {}
                        scanner_metadata['anisotropic_resampling'] = {
                            'performed': True,
                            'original_voxel_sizes': voxel_sizes,
                            'final_isotropic_voxel_size': final_voxel_size,
                            'resampling_method': 'deformation_based_interpolation'
                        }
                    else:
                        if scanner_metadata is None:
                            scanner_metadata = {}
                        scanner_metadata['anisotropic_resampling'] = {
                            'performed': False,
                            'voxel_sizes': voxel_sizes,
                            'reason': 'already_isotropic' if max(voxel_sizes) / min(voxel_sizes) <= 1.1 else 'resampling_failed'
                        }
                else:
                    # Fallback for when we couldn't extract proper voxel sizes
                    final_voxel_size = 1.0
                    print(f"⚠️ Warning: Could not extract voxel sizes for {scan_name}, using default")

                # Save as NIfTI using the final voxel size
                if image_data is not None:
                    nifti_file = os.path.join(scan_out_folder, scan_name)
                    self.save_as_nifti(image_data, final_voxel_size, nifti_file)
                    self.save_as_lossy_nifti(image_data, final_voxel_size, nifti_file)                    
                            
                print(scan_name+" saved")

                # Update the JSON metadata
                json_file = os.path.join(scan_out_folder, f"{scan_name}.json")
                if os.path.exists(json_file):
                    with open(json_file, 'r') as jf:
                        json_metadata = json.load(jf)
                else:
                    json_metadata = {}

                # Add scanner metadata if available
                if scanner_metadata:
                    json_metadata['scanner_metadata'] = scanner_metadata

                def find_major_peaks(histogram, bin_edges, min_distance=10):
                    # Find all peaks
                    peaks, _ = signal.find_peaks(histogram, distance=min_distance)
                    
                    if len(peaks) == 0:
                        return []
                    
                    # Sort peaks by their height (prominence)
                    peak_heights = histogram[peaks]
                    sorted_indices = np.argsort(peak_heights)[::-1]  # Sort in descending order
                    sorted_peaks = peaks[sorted_indices]
                    
                    # Return the bin values (intensity levels) for the peaks
                    peak_intensities = bin_edges[sorted_peaks]
                    return peak_intensities

                if is_binary:
                    threshold = self.BINARY_UINT16_THRESHOLD
                    print("Binary image — using fixed uint16 midpoint threshold: "+str(threshold))
                    image_data = None
                    gc.collect()
                else:
                    # Calculate histogram on a downsampled version if image is very large
                    if image_data.size > 100000000:  # Arbitrary threshold, adjust as needed
                        image_data = gaussian_filter(image_data, sigma=2.0)
                        blurred_image_data = block_reduce(image_data, block_size=(4, 4, 4), func=np.mean)
                    else:
                        blurred_image_data = gaussian_filter(image_data, sigma=2.0)

                    # Free image data as we no longer need it
                    image_data = None
                    gc.collect()  # Encourage garbage collection

                    threshold = self._compute_extraction_threshold(blurred_image_data, find_major_peaks)

                # Update JSON metadata
                json_metadata.update({
                    'name': scan_name,
                    'voxel_size': final_voxel_size,
                    'original_voxel_sizes': voxel_sizes,
                    'threshold': threshold,
                    'original_format': scan_subtype,
                })
                if extra_json_metadata:
                    json_metadata.update(extra_json_metadata)
                if intensity_value_mapping:
                    json_metadata['intensity_value_mapping'] = intensity_value_mapping
                elif 'intensity_value_mapping' in json_metadata:
                    # Passthrough / individual stretch must not retain a stale factor pair
                    del json_metadata['intensity_value_mapping']
                    
                with open(json_file, 'w') as jf:
                    json.dump(json_metadata, jf, indent=4)

                # If a segmentation exists for this scan, load and save masks (full and lossy)
                try:
                    if scan_name in segmentation_map:
                        seg_path = segmentation_map[scan_name]
                        seg_mask = self._load_segmentation_mask(seg_path)
                        if seg_mask is not None:
                            self._save_segmentation_masks(scan_out_folder, scan_name, seg_mask)
                            print(f"Segmentation processed for {scan_name}: {os.path.basename(seg_path)}")
                except Exception as e:
                    print(f"Warning: Could not process segmentation for {scan_name}: {e}")

            # Send progress update via WebSocket
            progress = 1
            channel_layer = get_channel_layer()
            if channel_layer is not None:
                async_to_sync(channel_layer.group_send)(
                    'progress_group',
                    {
                        'type': 'send_progress',
                        'progress': progress,
                        'scan_name': '',
                        'total': total_scans,
                        'custom_message': 'Done extracting scans!',
                        'current': total_scans,
                    }
                )

            return Response({'message': 'Scans extracted successfully'})

        except Exception as e:
            print(e)
            return Response({'error': str(e)}, status=status.HTTP_500_INTERNAL_SERVER_ERROR)

    def extract_voxel_size_from_scanco(self, header_file):
        # Logic to extract voxel size from SCANCO vivaCT header file
        with open(header_file, 'r') as file:
            content = file.read()
            
        # Use regex to find the line containing 'element size in mm'
        match = re.search(r'element size in mm\s+([\d.]+)\s+([\d.]+)\s+([\d.]+)', content)
        
        if match:
            element_sizes = match.groups()
            return float(element_sizes[0])
        else:
            return None

    def extract_voxel_size_from_zeiss(self, header_file):
        # Logic to extract voxel size from ZEISS Xradia header file
        with open(header_file, 'r') as file:
            content = file.read()
            
        # Use regex to find the line containing 'Pixel Size'
        match = re.search(r'Pixel Size\s*=\s*([\d.]+)', content)
        
        if match:
            pixel_size_um = float(match.group(1))
            # Convert from micrometers to millimeters
            pixel_size_mm = pixel_size_um / 1000
            return pixel_size_mm
        else:
            return None


    def load_zeiss_image(self, scan_folder):
        # Get a sorted list of all .tiff files in the scan_folder
        tiff_files = sorted([f for f in os.listdir(scan_folder) if f.endswith('.tiff') or f.endswith('.tif')])
        
        # Preallocate a list to store the file paths
        file_paths = [os.path.join(scan_folder, f) for f in tiff_files]

        # Try to extract voxel size from the first TIFF file's metadata
        voxel_size = None
        first_tiff_path = file_paths[0]
        
        try:
            # Load the first TIFF file to extract voxel size
            with tifffile.TiffFile(first_tiff_path) as tif:
                print(f"DEBUG: Analyzing TIFF file: {first_tiff_path}")
                
                if tif.pages:
                    page = tif.pages[0]
                    tags = page.tags
                    
                    # Print all available tags for debugging
                    print("DEBUG: All available TIFF tags:")
                    for tag_name, tag in tags.items():
                        try:
                            print(f"  {tag_name}: {tag.value} (type: {type(tag.value)})")
                        except:
                            print(f"  {tag_name}: <unable to read> (type: {type(tag)})")
                    
                    # Check for ImageJ metadata
                    if hasattr(page, 'imagej_metadata') and page.imagej_metadata:
                        print("DEBUG: ImageJ metadata:")
                        for key, value in page.imagej_metadata.items():
                            print(f"  {key}: {value}")
                    
                    # Check for any other metadata attributes
                    print("DEBUG: Page attributes:")
                    for attr in dir(page):
                        if not attr.startswith('_') and attr not in ['tags', 'imagej_metadata']:
                            try:
                                value = getattr(page, attr)
                                if not callable(value):
                                    print(f"  {attr}: {value}")
                            except:
                                pass
                    
                    # Look for X and Y resolution
                    if 'XResolution' in tags and 'YResolution' in tags:
                        x_res = tags['XResolution'].value
                        y_res = tags['YResolution'].value
                        
                        print(f"DEBUG: XResolution: {x_res}, YResolution: {y_res}")
                        
                        # Convert resolution to voxel size
                        if isinstance(x_res, (list, tuple)) and len(x_res) == 2:
                            x_resolution_value = x_res[0] / x_res[1]
                            print(f"DEBUG: X resolution value (from fraction): {x_resolution_value}")
                        else:
                            x_resolution_value = float(x_res)
                            print(f"DEBUG: X resolution value (direct): {x_resolution_value}")
                        
                        # Check resolution unit
                        resolution_unit = tags.get('ResolutionUnit', 1).value
                        print(f"DEBUG: Resolution unit: {resolution_unit}")
                        
                        # Properly invert resolution to get voxel size
                        # Resolution is pixels per unit, voxel size is unit per pixel
                        if resolution_unit == 2:  # Inches
                            voxel_size = 25.4 / x_resolution_value  # Convert inches to mm
                        elif resolution_unit == 3:  # Centimeters
                            voxel_size = 10.0 / x_resolution_value  # Convert cm to mm
                        else:  # Default/unknown unit
                            voxel_size = 1.0 / x_resolution_value if x_resolution_value > 0 else 1.0
                            print(f"DEBUG: Calculated voxel size (unknown unit): {voxel_size:.6f} mm")
                        
                        print(f"Resolution: {x_resolution_value:.4f} pixels per unit (unit={resolution_unit})")
                        print(f"Extracted voxel size from TIFF metadata: {voxel_size:.6f} mm")
                    
                    # Check for ImageJ metadata which might contain voxel spacing
                    if voxel_size is None and hasattr(page, 'imagej_metadata') and page.imagej_metadata:
                        ij_meta = page.imagej_metadata
                        if 'spacing' in ij_meta:
                            voxel_size = float(ij_meta['spacing'])
                            print(f"Extracted voxel size from ImageJ metadata: {voxel_size:.3f} mm")
        
        except Exception as e:
            print(f"Could not extract voxel size from TIFF metadata: {e}")
            import traceback
            traceback.print_exc()
            voxel_size = None
        
        # Fall back to header file method if voxel size couldn't be extracted from TIFF
        if voxel_size is None:
            header_file = next((f for f in os.listdir(scan_folder) if f.endswith('.txt')), None)
            if header_file:
                voxel_size = self.extract_voxel_size_from_zeiss(os.path.join(scan_folder, header_file))
                if voxel_size:
                    print(f"Extracted voxel size from header file: {voxel_size:.3f} mm")
        
        # Default voxel size if all methods fail
        if voxel_size is None:
            voxel_size = 1.0  # Default voxel size in mm
            print("\033[91mWarning: Could not extract voxel size from TIFF or header file. Using default 1 mm.\033[0m")

        # Read the image data as bytes
        file_bytes_list = []
        for file_path in file_paths:
            with open(file_path, 'rb') as f:
                file_bytes_list.append(f.read())

        # Load images in parallel using ProcessPoolExecutor
        with concurrent.futures.ProcessPoolExecutor() as executor:
            slices = list(executor.map(load_image_from_bytes, file_bytes_list))

        # Stack all slices along a new axis to create the 3D volume
        extracted_image = np.stack(slices, axis=0)

        return extracted_image, voxel_size  # Return both image and voxel size
    

    def save_as_nifti(self, image_data, voxel_size, nifti_file):
        """
        Saves image data as a NIfTI file.

        Args:
            image_data (numpy array): The image data to save.
            voxel_size (float): The size of the voxels in the image.
            nifti_file (str): The file path to save the NIfTI file.
        """

        affine = np.diag([voxel_size, voxel_size, voxel_size, 1])
        if image_data.ndim > 3:
            channel_axis = int(np.argmin(image_data.shape))
            print(
                f"4D+ image data (shape {image_data.shape}), "
                f"taking index 0 along channel axis {channel_axis}"
            )
            image_data = self._reduce_extra_dims_to_3d(image_data)
        nifti_img = nib.Nifti1Image(image_data, affine)
        nib.save(nifti_img, f"{nifti_file}.nii.gz")


    def save_as_lossy_nifti(self, image_data, voxel_size, nifti_file):
        """
        Extract-time lossy preview. Delegates to RegistrationTools.save_as_lossy_nifti
        (mean-pool with ceil pad) so raw extract lossy matches edit/elastic/atlas lossy
        shapes on odd dimensions. The previous stride+duplicate-last-slice path here
        produced (ceil(s/2)+1 on odd axes) and broke elastic↔reference GPU-slice compare
        when the reference stayed at raw.
        """
        json_file = f"{nifti_file}.json"
        output_file = f"{nifti_file}_lossy.nii.gz"

        if os.path.exists(json_file):
            with open(json_file, 'r') as jf:
                json_metadata = json.load(jf)
        else:
            json_metadata = {}

        # RegistrationTools requires on-disk JSON and appends lossy_compression.
        # Extract rewrites the base raw lossy, so clear prior entries (same as the
        # old replace semantics) instead of stacking duplicates on re-extract.
        json_metadata['lossy_compression'] = []
        json_metadata.setdefault('voxel_size', float(voxel_size))
        with open(json_file, 'w') as jf:
            json.dump(json_metadata, jf, indent=4)

        RegistrationTools().save_as_lossy_nifti(
            image_data,
            voxel_size,
            json_file,
            output_file,
        )


    def load_dicom_image(self, scan_folder):
        """
        Load a 3D image from DICOM files in the given folder.
        
        Args:
            scan_folder (str): Path to the folder containing DICOM files
            
        Returns:
            tuple: (voxel_size, image_data, scanner_metadata) where voxel_size is in mm, 
                  image_data is a 3D numpy array, and scanner_metadata is a dictionary
        """        
        
        dicom_files = []
        
        # First check for files with .dcm extension
        dcm_files = sorted([
            os.path.join(scan_folder, f) 
            for f in os.listdir(scan_folder) 
            if f.endswith('.dcm')
        ])
        
        if dcm_files:
            dicom_files = dcm_files
        else:
            # Check if DICOMDIR exists
            dicomdir_path = os.path.join(scan_folder, 'DICOMDIR')
            if os.path.exists(dicomdir_path):
                try:
                    # Use DICOMDIR to find DICOM files without extensions
                    dicomdir = dcmread(dicomdir_path)
                    
                    # Process DirectoryRecordSequence
                    if hasattr(dicomdir, 'DirectoryRecordSequence'):
                        # Track the current level in the hierarchy
                        current_patient = None
                        current_study = None
                        current_series = None
                        
                        for record in dicomdir.DirectoryRecordSequence:
                            record_type = record.DirectoryRecordType
                            
                            if record_type == 'PATIENT':
                                current_patient = record
                            elif record_type == 'STUDY':
                                current_study = record
                            elif record_type == 'SERIES':
                                current_series = record
                            elif record_type == 'IMAGE':
                                if hasattr(record, 'ReferencedFileID'):
                                    # ReferencedFileID contains path components                                    
                                    file_path = os.path.join(scan_folder, record.ReferencedFileID)
                                    if os.path.exists(file_path):
                                        dicom_files.append(file_path)
                    else:
                        print("No DirectoryRecordSequence found. Available keys:", list(dicomdir.keys()))
                        
                    # If we didn't find any files, try a different approach
                    if len(dicom_files) == 0:
                        print("Trying alternative approach to parse DICOMDIR")
                        # Try to access the top-level dataset
                        for key in dicomdir.keys():
                            print(f"Key: {key}, Value type: {type(dicomdir[key])}")
                except Exception as e:
                    print(f"Error reading DICOMDIR: {e}")
            
            # If still no files found, look for files without extensions that are DICOM
            if len(dicom_files) == 0:
                for root, _, files in os.walk(scan_folder):
                    for f in files:
                        file_path = os.path.join(root, f)
                        # Try to determine if it's a DICOM file regardless of extension
                        try:
                            with open(file_path, 'rb') as test_file:
                                # Check for DICOM magic number (DICM at byte offset 128)
                                test_file.seek(128)
                                if test_file.read(4) == b'DICM':
                                    dicom_files.append(file_path)
                        except:
                            pass
            
            # If still no files found, look for .dcm files in subdirectories
            if len(dicom_files) == 0:
                for root, _, files in os.walk(scan_folder):
                    dicom_files.extend(sorted([
                        os.path.join(root, f) 
                        for f in files 
                        if f.endswith('.dcm')
                    ]))
        
        if len(dicom_files) == 0:
            raise ValueError(f"No DICOM files found in {scan_folder}")
                
        # Sort files to ensure correct slice order
        dicom_files = sorted(dicom_files, key=lambda x: self._get_slice_position(x))
        
        # Read the first DICOM file to get metadata
        first_dicom = dcmread(dicom_files[0])
        
        # Extract comprehensive metadata into a dictionary
        scanner_metadata = self._extract_dicom_metadata(first_dicom)
        
        # Add number of slices to the metadata
        if 'image' not in scanner_metadata:
            scanner_metadata['image'] = {}
        scanner_metadata['image']['number_of_slices'] = len(dicom_files)
        
        # Extract voxel size (in mm)
        try:
            # Try to get pixel spacing (x, y) and slice thickness (z)
            pixel_spacing = first_dicom.PixelSpacing
            slice_thickness = getattr(first_dicom, 'SliceThickness', None)
            
            if slice_thickness is None:
                # Try to get spacing between slices if slice thickness is not available
                slice_thickness = getattr(first_dicom, 'SpacingBetweenSlices', pixel_spacing[0])
            
            # Store spacing details in metadata
            if 'geometry' not in scanner_metadata:
                scanner_metadata['geometry'] = {}
            scanner_metadata['geometry']['pixel_spacing'] = [float(pixel_spacing[0]), float(pixel_spacing[1])]
            scanner_metadata['geometry']['slice_thickness'] = float(slice_thickness)
            
            # Check for isotropic voxels
            if pixel_spacing[0] == pixel_spacing[1]:
                voxel_size = float(pixel_spacing[0])  # in mm
                scanner_metadata['geometry']['isotropic'] = True
                print("isotropic voxel size: "+str(voxel_size))
            else:
                print("\033[91mWarning: Non-isotropic voxels detected. Assuming isotropic voxels.\033[0m")
                scanner_metadata['geometry']['isotropic'] = False
                voxel_size = float(pixel_spacing[0])  # in mm
        except (AttributeError, TypeError):
            print("\033[91mWarning: Could not extract voxel size from DICOM. Assuming default 1 mm.\033[0m")
            voxel_size = 1  # Default voxel size in mm
            if 'geometry' not in scanner_metadata:
                scanner_metadata['geometry'] = {}
            scanner_metadata['geometry']['default_voxel_size_used'] = True
        
        # Load all DICOM slices sequentially instead of using multiprocessing
        slices = []
        for dicom_file in dicom_files:
            slice_data = dcmread(dicom_file).pixel_array
            slices.append(slice_data)
        
        # Stack all slices to create a 3D volume
        image_data = np.stack(slices, axis=0)
        
        return voxel_size, image_data, scanner_metadata

    def load_multi_page_tiff(self, scan_path):
        """
        Load a 3D image from a multi-page TIFF file.
        
        Args:
            scan_path (str): Path to the TIFF file
            
        Returns:
            tuple: (image_data, voxel_size, scanner_metadata) where voxel_size is in mm, 
                  image_data is a 3D numpy array, and scanner_metadata is a dictionary
        """        
        
        try:
            # Load the multi-page TIFF file
            with tifffile.TiffFile(scan_path) as tif:
                # Read the image data as a numpy array
                image_data = tif.asarray()
                
                # Initialize metadata dictionary
                scanner_metadata = {}
                
                # Extract basic file information
                scanner_metadata['file_info'] = {
                    'filename': os.path.basename(scan_path),
                    'num_pages': len(tif.pages),
                    'shape': image_data.shape,
                    'dtype': str(image_data.dtype)
                }
                
                # Try to extract voxel size from TIFF metadata
                voxel_size = 1.0  # Default voxel size in mm


                
                # Check for resolution information in the first page
                if tif.pages:
                    page = tif.pages[0]
                    tags = page.tags
                    
                    # Look for X and Y resolution
                    if 'XResolution' in tags and 'YResolution' in tags:
                        x_res = tags['XResolution'].value
                        y_res = tags['YResolution'].value
                        
                        # Convert resolution to voxel size
                        # Resolution is typically in pixels per unit
                        if isinstance(x_res, (list, tuple)) and len(x_res) == 2:
                            x_pixels_per_unit = x_res[0] / x_res[1]
                        else:
                            x_pixels_per_unit = float(x_res)
                            
                        if isinstance(y_res, (list, tuple)) and len(y_res) == 2:
                            y_pixels_per_unit = y_res[0] / y_res[1]
                        else:
                            y_pixels_per_unit = float(y_res)
                        
                        # Check resolution unit
                        resolution_unit = tags.get('ResolutionUnit', 1).value
                        
                        if resolution_unit == 2:  # Inches
                            # Convert from pixels per inch to mm per pixel
                            voxel_size = 25.4 / x_pixels_per_unit  # 25.4 mm per inch
                        elif resolution_unit == 3:  # Centimeters
                            # Convert from pixels per cm to mm per pixel
                            voxel_size = 10.0 / x_pixels_per_unit  # 10 mm per cm
                        else:
                            voxel_size = 1.0 / x_pixels_per_unit if x_pixels_per_unit > 0 else 1.0
                            print(f"DEBUG: Calculated voxel size (unknown unit): {voxel_size:.6f} mm")
                        
                        print(f"Extracted voxel size from TIFF metadata: {voxel_size:.3f} mm")

                        scanner_metadata['geometry'] = {
                            'x_resolution': x_pixels_per_unit,
                            'y_resolution': y_pixels_per_unit,
                            'resolution_unit': resolution_unit,
                            'voxel_size_mm': voxel_size
                        }
                    
                    # Check for ImageJ metadata which might contain voxel spacing
                    if hasattr(page, 'imagej_metadata') and page.imagej_metadata:
                        ij_meta = page.imagej_metadata
                        if 'spacing' in ij_meta:
                            voxel_size = float(ij_meta['spacing'])
                            scanner_metadata['imagej'] = ij_meta
                    
                    # Extract other relevant tags
                    metadata_tags = {}
                    for tag_name in ['ImageDescription', 'Software', 'DateTime', 'Artist']:
                        if tag_name in tags:
                            try:
                                metadata_tags[tag_name] = tags[tag_name].value
                            except:
                                pass
                    
                    if metadata_tags:
                        scanner_metadata['tags'] = metadata_tags
                
                # Ensure image_data is 3D
                if image_data.ndim == 2:
                    # Single page TIFF - add a singleton dimension
                    image_data = image_data[np.newaxis, ...]
                elif image_data.ndim > 3:
                    channel_axis = int(np.argmin(image_data.shape))
                    print(
                        f"4D+ TIFF (shape {image_data.shape}), "
                        f"taking index 0 along channel axis {channel_axis}"
                    )
                    image_data = self._reduce_extra_dims_to_3d(image_data)
                
                print(f"Loaded TIFF: {image_data.shape}, voxel size: {voxel_size:.3f} mm")
                
        except Exception as e:
            print(f"\033[91mError loading TIFF file {scan_path}: {str(e)}\033[0m")
            return None, None, None
        
        return image_data, voxel_size, scanner_metadata

    def _extract_dicom_metadata(self, dicom_dataset):
        """
        Extract relevant metadata from a DICOM dataset into a structured dictionary.
        
        Args:
            dicom_dataset: A pydicom dataset
            
        Returns:
            dict: A dictionary containing structured DICOM metadata
        """
        metadata = {}
        
        # Equipment information
        metadata['equipment'] = {
            'manufacturer': self._safe_json_value(getattr(dicom_dataset, 'Manufacturer', None)),
            'model': self._safe_json_value(getattr(dicom_dataset, 'ManufacturerModelName', None)),
            'institution': self._safe_json_value(getattr(dicom_dataset, 'InstitutionName', None)),
            'modality': self._safe_json_value(getattr(dicom_dataset, 'Modality', None))
        }
        
        # Study information
        metadata['study'] = {
            'description': self._safe_json_value(getattr(dicom_dataset, 'StudyDescription', None)),
            'id': self._safe_json_value(getattr(dicom_dataset, 'StudyID', None)),
            'date': self._safe_json_value(getattr(dicom_dataset, 'StudyDate', None)),
            'time': self._safe_json_value(getattr(dicom_dataset, 'StudyTime', None))
        }
        
        # Series information
        metadata['series'] = {
            'description': self._safe_json_value(getattr(dicom_dataset, 'SeriesDescription', None)),
            'number': self._safe_json_value(getattr(dicom_dataset, 'SeriesNumber', None)),
            'date': self._safe_json_value(getattr(dicom_dataset, 'SeriesDate', None)),
            'time': self._safe_json_value(getattr(dicom_dataset, 'SeriesTime', None))
        }
        
        # Acquisition information
        metadata['acquisition'] = {
            'date': self._safe_json_value(getattr(dicom_dataset, 'AcquisitionDate', None)),
            'time': self._safe_json_value(getattr(dicom_dataset, 'AcquisitionTime', None)),
            'kvp': self._safe_json_value(getattr(dicom_dataset, 'KVP', None)),
            'exposure_time': self._safe_json_value(getattr(dicom_dataset, 'ExposureTime', None)),
            'exposure': self._safe_json_value(getattr(dicom_dataset, 'Exposure', None)),
            'protocol_name': self._safe_json_value(getattr(dicom_dataset, 'ProtocolName', None))
        }
        
        # Image information
        metadata['image'] = {
            'type': self._safe_json_value(getattr(dicom_dataset, 'ImageType', None)),
            'position_patient': self._safe_json_value(getattr(dicom_dataset, 'ImagePositionPatient', None)),
            'orientation_patient': self._safe_json_value(getattr(dicom_dataset, 'ImageOrientationPatient', None)),
            'rows': self._safe_json_value(getattr(dicom_dataset, 'Rows', None)),
            'columns': self._safe_json_value(getattr(dicom_dataset, 'Columns', None)),
            'bits_allocated': self._safe_json_value(getattr(dicom_dataset, 'BitsAllocated', None)),
            'bits_stored': self._safe_json_value(getattr(dicom_dataset, 'BitsStored', None)),
            'high_bit': self._safe_json_value(getattr(dicom_dataset, 'HighBit', None)),
            'pixel_representation': self._safe_json_value(getattr(dicom_dataset, 'PixelRepresentation', None)),
            'window_center': self._safe_json_value(getattr(dicom_dataset, 'WindowCenter', None)),
            'window_width': self._safe_json_value(getattr(dicom_dataset, 'WindowWidth', None))
        }
        
        # Geometry information
        metadata['geometry'] = {
            'slice_thickness': self._safe_json_value(getattr(dicom_dataset, 'SliceThickness', None)),
            'spacing_between_slices': self._safe_json_value(getattr(dicom_dataset, 'SpacingBetweenSlices', None)),
            'pixel_spacing': self._safe_json_value(getattr(dicom_dataset, 'PixelSpacing', None))
        }
        
        # Calibration information
        metadata['calibration'] = {
            'rescale_intercept': self._safe_json_value(getattr(dicom_dataset, 'RescaleIntercept', 0)),
            'rescale_slope': self._safe_json_value(getattr(dicom_dataset, 'RescaleSlope', 1)),
            'rescale_type': self._safe_json_value(getattr(dicom_dataset, 'RescaleType', None))
        }
        
        # Try to extract any CT-specific attributes
        if getattr(dicom_dataset, 'Modality', '') == 'CT':
            metadata['ct_specific'] = {
                'convolution_kernel': self._safe_json_value(getattr(dicom_dataset, 'ConvolutionKernel', None)),
                'reconstruction_diameter': self._safe_json_value(getattr(dicom_dataset, 'ReconstructionDiameter', None)),
                'filter_type': self._safe_json_value(getattr(dicom_dataset, 'FilterType', None)),
                'spiral_pitch_factor': self._safe_json_value(getattr(dicom_dataset, 'SpiralPitchFactor', None)),
                'data_collection_diameter': self._safe_json_value(getattr(dicom_dataset, 'DataCollectionDiameter', None))
            }
        
        # Clean up the dictionary by removing None values and empty dictionaries
        return self._clean_metadata_dict(metadata)

    def _clean_metadata_dict(self, metadata_dict):
        """
        Remove None values and empty dictionaries from the metadata dictionary.
        
        Args:
            metadata_dict (dict): The metadata dictionary to clean
            
        Returns:
            dict: The cleaned metadata dictionary
        """
        result = {}
        for key, value in metadata_dict.items():
            if isinstance(value, dict):
                cleaned_dict = self._clean_metadata_dict(value)
                if cleaned_dict:  # Only add non-empty dictionaries
                    result[key] = cleaned_dict
            elif value is not None:
                result[key] = value
        return result

    def _safe_json_value(self, value):
        """
        Convert DICOM values to JSON-serializable types.
        
        Args:
            value: A DICOM data element value
            
        Returns:
            A JSON-serializable representation of the value
        """
        if value is None:
            return None
            
        # Handle pydicom's MultiValue type (similar to a list)
        if hasattr(value, '__iter__') and not isinstance(value, (str, bytes, dict)):
            return [self._safe_json_value(item) for item in value]
            
        # Handle pydicom's PersonName type
        if hasattr(value, 'family_name'):
            return str(value)
            
        # Handle pydicom's DA/TM (date/time) types
        if hasattr(value, 'original_string'):
            return str(value)
            
        # Handle bytes
        if isinstance(value, bytes):
            try:
                return value.decode('utf-8')
            except UnicodeDecodeError:
                return str(value)
                
        # Handle other types that might not be JSON serializable
        try:
            json.dumps(value)
            return value
        except (TypeError, OverflowError):
            return str(value)

    def load_dicom_slice(self, dicom_file):
        slice = dcmread(dicom_file)
        return slice.pixel_array

    def _get_slice_position(self, dicom_file):
        """
        Helper method to get the slice position for sorting DICOM files.
        
        Args:
            dicom_file (str): Path to a DICOM file
            
        Returns:
            float: The slice position value for sorting
        """
        try:
            dcm = dcmread(dicom_file, stop_before_pixels=True)
            # Try different DICOM tags that might contain position information
            if hasattr(dcm, 'ImagePositionPatient'):
                return float(dcm.ImagePositionPatient[2])
            elif hasattr(dcm, 'SliceLocation'):
                return float(dcm.SliceLocation)
            elif hasattr(dcm, 'InstanceNumber'):
                return float(dcm.InstanceNumber)
            else:
                # If no position information is available, use the filename
                return os.path.basename(dicom_file)
        except Exception:
            # If reading fails, use the filename as fallback
            return os.path.basename(dicom_file)

    def _extract_nifti_metadata(self, nii_img):
        """
        Extract relevant metadata from a NIfTI image header.
        
        Args:
            nii_img: A nibabel NIfTI image object
            
        Returns:
            dict: A dictionary containing essential NIfTI metadata
        """
        metadata = {}
        
        # Define fields to extract at the top level
        fields_to_extract = ['datatype', 'bitpix', 'pixdim', 'scl_slope', 'scl_inter', 'cal_max', 'cal_min', 'descrip', 'aux_file', 'intent_name']
        
        try:
            # Basic file information
            metadata['file_info'] = {
                'data_type': str(nii_img.get_data_dtype()),
                'shape': list(nii_img.shape),
                'affine': nii_img.affine.tolist() if nii_img.affine is not None else None
            }
        except Exception as e:
            print(f"Warning: Could not extract basic file info: {e}")
            metadata['file_info'] = {'data_type': 'unknown', 'shape': [], 'affine': None}
        
        # Header information - extract each field individually with its own try-catch
        header = nii_img.header
        header_metadata = {}
        for field_name in fields_to_extract:
            try:
                if hasattr(header, field_name):
                    value = getattr(header, field_name)
                elif field_name in header:
                    value = header[field_name]
                else:
                    continue
                
                # Convert value to JSON-serializable format
                converted_value = self._safe_convert_value(value)
                if converted_value is not None:
                    header_metadata[field_name] = converted_value
                    
            except Exception as e:
                print(f"Warning: Could not extract field '{field_name}': {e}")
                continue
            
        if header_metadata:
            metadata['header'] = header_metadata
        
        # Geometry information
        try:
            zooms = header.get_zooms()
            metadata['geometry'] = {
                'voxel_size_mm': float(zooms[0]) if len(zooms) > 0 else 1.0,
                'zooms': [float(z) for z in zooms] if zooms else [1.0],
                'units': str(header.get_xyzt_units())
            }
        except (AttributeError, IndexError):
            metadata['geometry'] = {
                'voxel_size_mm': 1.0,
                'zooms': [1.0],
                'units': 'unknown'
            }
        
        # Clean up the dictionary by removing None values and empty dictionaries
        return self._clean_metadata_dict(metadata)

    def _safe_convert_value(self, value):
        """
        Safely convert a value to a JSON-serializable format.
        
        Args:
            value: The value to convert
            
        Returns:
            A JSON-serializable value or None if conversion fails
        """
        import math  # For NaN and inf checks
        try:
            if value is None:
                return None
            elif isinstance(value, float):
                if math.isnan(value):
                    return None  # or 'NaN' if you prefer to keep it as string
                elif math.isinf(value):
                    return None  # or 'Infinity' / '-Infinity'
                else:
                    return value
            elif hasattr(value, 'tolist'):
                # Numpy arrays - recursively convert elements
                return [self._safe_convert_value(v) for v in value]
            elif hasattr(value, 'item'):
                # Numpy scalars
                scalar = value.item()
                return self._safe_convert_value(scalar)  # Recurse to handle float NaN
            elif isinstance(value, bytes):
                # Bytes objects - try multiple approaches
                try:
                    decoded = value.decode('utf-8', errors='ignore').strip('\x00').strip()
                    return decoded if decoded else None
                except:
                    try:
                        decoded = value.decode('ascii', errors='ignore').strip('\x00').strip()
                        return decoded if decoded else None
                    except:
                        return f"<bytes: {len(value)} bytes>"
            elif isinstance(value, (str, int, bool)):
                # Native Python types
                return value
            elif hasattr(value, '__iter__') and not isinstance(value, (str, bytes)):
                # Iterables (lists, tuples, etc.)
                try:
                    return [self._safe_convert_value(item) for item in value]
                except:
                    return str(value)
            else:
                # Any other type - convert to string as last resort
                return str(value)
        except Exception as e:
            print(f"Warning: Could not convert value {type(value)}: {e}")
            return None

    # ------------------------------------------------------------------
    # MINC support (no MINC toolkit required)
    # MINC1 is NetCDF-based (needs netCDF4 or nibabel's built-in reader).
    # MINC2 is HDF5-based (needs h5py).
    # nibabel handles both transparently via nib.load().
    # ------------------------------------------------------------------

    def _detect_minc_version(self, file_path):
        """
        Detect MINC file version by inspecting magic bytes.
        MINC1 (NetCDF) starts with 'CDF', MINC2 (HDF5) starts with the HDF5 signature.

        Returns:
            int: 1 for MINC1, 2 for MINC2, None if unrecognised.
        """
        try:
            with open(file_path, 'rb') as f:
                magic = f.read(8)
            if magic[:3] == b'CDF':
                return 1
            elif magic[:4] == b'\x89HDF':
                return 2
        except Exception as e:
            print(f"Warning: Could not detect MINC version for {file_path}: {e}")
        return None

    def load_minc_image(self, mnc_path):
        """
        Load a MINC file (v1 or v2) without the MINC toolkit.
        Uses nibabel, which supports both variants natively:
          - MINC1 via its own minimal NetCDF reader (or netCDF4 if installed)
          - MINC2 via h5py

        The dimension-ordering and direction-cosine remapping performed by
        the reference mnc2nii C tool is handled internally by nibabel, so
        the returned array is already in standard (x, y, z) orientation.

        Returns:
            tuple: (image_data np.ndarray, voxel_sizes tuple(x,y,z), scanner_metadata dict)
                   or (None, None, None) on failure.
        """
        try:
            minc_version = self._detect_minc_version(mnc_path)
            print(f"Loading MINC{minc_version or '?'} file: {mnc_path}")

            mnc_img = nib.load(mnc_path)
            image_data = mnc_img.get_fdata()

            # Ensure the array is 3-D
            if image_data.ndim > 3:
                channel_axis = int(np.argmin(image_data.shape))
                print(
                    f"4D+ MINC (shape {image_data.shape}), "
                    f"taking index 0 along channel axis {channel_axis}"
                )
                image_data = self._reduce_extra_dims_to_3d(image_data)
            elif image_data.ndim == 2:
                image_data = image_data[np.newaxis, ...]
            elif image_data.ndim != 3:
                print(f"Warning: unexpected MINC dimensionality {image_data.ndim} for {mnc_path}")
                return None, None, None

            # Voxel sizes — use absolute values because MINC step can be negative
            # (the C code does the same: step = -step when step < 0)
            zooms = mnc_img.header.get_zooms()
            vx = abs(float(zooms[0])) if len(zooms) > 0 else 1.0
            vy = abs(float(zooms[1])) if len(zooms) > 1 else vx
            vz = abs(float(zooms[2])) if len(zooms) > 2 else vx
            # Guard against zero voxel sizes
            vx = vx if vx > 0 else 1.0
            vy = vy if vy > 0 else 1.0
            vz = vz if vz > 0 else 1.0
            voxel_sizes = (vx, vy, vz)

            # Build scanner metadata
            affine_list = mnc_img.affine.tolist() if mnc_img.affine is not None else None
            scanner_metadata = {
                'file_info': {
                    'minc_version': minc_version,
                    'data_type': str(mnc_img.get_data_dtype()),
                    'shape': list(mnc_img.shape),
                    'affine': affine_list,
                },
                'geometry': {
                    'voxel_size_x_mm': vx,
                    'voxel_size_y_mm': vy,
                    'voxel_size_z_mm': vz,
                    'zooms': list(voxel_sizes),
                },
            }

            print(f"MINC loaded: shape={image_data.shape}, voxel_sizes={voxel_sizes}")
            return image_data, voxel_sizes, scanner_metadata

        except ImportError as e:
            # Likely missing h5py (MINC2) or netCDF4 (MINC1)
            missing = 'h5py' if 'h5py' in str(e) else 'netCDF4'
            print(f"Error loading MINC file — missing dependency '{missing}': {e}")
            print(f"Install with: pip install {missing}")
            return None, None, None
        except Exception as e:
            print(f"Error loading MINC file {mnc_path}: {e}")
            import traceback
            traceback.print_exc()
            return None, None, None


class ExtractScansPreflightView(APIView):
    def post(self, request, *args, **kwargs):
        directory = request.data.get('directory')
        scans = request.data.get('scans')

        if not directory or scans is None:
            return Response({'error': 'Missing required parameters'}, status=status.HTTP_400_BAD_REQUEST)

        extractor = ExtractScansView()
        extracted_dir = os.path.join(directory, 'extracted')

        def _needs_extraction(scan):
            scan_name = scan.get('name', '')
            if not scan_name or scan_name.lower() == 'atlas':
                return False
            if extractor._is_segmentation_name(scan_name):
                return False
            return not extractor._is_fully_extracted(extracted_dir, scan_name)

        mesh_scans = [
            scan for scan in scans
            if extractor._is_mesh_subtype(scan.get('subtype')) and _needs_extraction(scan)
        ]
        volume_scans = [
            scan for scan in scans
            if not extractor._is_mesh_subtype(scan.get('subtype')) and _needs_extraction(scan)
        ]

        mesh_infos = extractor._collect_mesh_infos(directory, mesh_scans)
        groups = extractor._group_mesh_infos_by_scale(mesh_infos)
        subject_scale_groups = {}
        for group in groups:
            for subject in group.get('subjects', []):
                subject_scale_groups[subject] = group.get('label')

        existing_intensity_policy = extractor._infer_existing_intensity_policy(extracted_dir)
        intensity_scan_stats = extractor._collect_intensity_scan_stats(directory, volume_scans)
        intensity_groups = extractor._group_intensity_stats_by_value_family(intensity_scan_stats)
        needs_intensity_options = any(
            s.get('needs_range_decision') for s in intensity_scan_stats if not s.get('error')
        )

        incremental_assignments = []
        new_subgroup_alerts = []
        if existing_intensity_policy.get('has_quantitative_mapping') and needs_intensity_options:
            incremental_assignments, new_subgroup_alerts = extractor._assign_pending_to_existing_intensity_groups(
                intensity_scan_stats, existing_intensity_policy
            )
            # Prefer existing windows for non-alert subjects; rebuild intensity_groups for UI
            if incremental_assignments:
                rebuilt = []
                by_label = {}
                for assignment in incremental_assignments:
                    label = assignment['group_label']
                    if label not in by_label:
                        by_label[label] = {
                            'label': label,
                            'subjects': [],
                            'dtype_family': 'mixed',
                            'dtypes': [],
                            'window_min': float(assignment['window_min']),
                            'window_max': float(assignment['window_max']),
                            'passthrough': False,
                            'action_default': 'group_window',
                            'is_new_subgroup': bool(assignment.get('is_new_subgroup')),
                            'from_existing': not bool(assignment.get('is_new_subgroup')),
                        }
                    by_label[label]['subjects'].append(assignment['name'])
                    # Expand new-subgroup window to include all assigned scans
                    if assignment.get('is_new_subgroup'):
                        by_label[label]['window_min'] = min(
                            by_label[label]['window_min'], float(assignment['window_min'])
                        )
                        by_label[label]['window_max'] = max(
                            by_label[label]['window_max'], float(assignment['window_max'])
                        )
                rebuilt = list(by_label.values())
                # Keep uint16 passthrough informational group from fresh clustering
                for group in intensity_groups:
                    if group.get('passthrough'):
                        rebuilt.append(group)
                intensity_groups = rebuilt

        decision_groups = [g for g in intensity_groups if not g.get('passthrough')]
        has_intensity_subgroup_warning = len(decision_groups) > 1 or len(new_subgroup_alerts) > 0

        return Response({
            'mesh_count': len(mesh_scans),
            'volume_count': len(volume_scans),
            'mesh_infos': mesh_infos,
            'scale_groups': groups,
            'subject_scale_groups': subject_scale_groups,
            'has_scale_warning': len(groups) > 1,
            'assumed_units': 'mm',
            'needs_intensity_options': needs_intensity_options,
            'intensity_scan_stats': intensity_scan_stats,
            'intensity_groups': intensity_groups,
            'has_intensity_subgroup_warning': has_intensity_subgroup_warning,
            'existing_intensity_policy': existing_intensity_policy,
            'incremental_assignments': incremental_assignments,
            'new_subgroup_alerts': new_subgroup_alerts,
        })


def compute_union_mask_ncc(fixed_volume, moving_volume, reference_threshold, moving_threshold):
    """
    Zero-mean NCC of intensities inside the OR of the two threshold masks.

    Returns a float in [-1, 1], or 0.0 when the union is empty / constant.
    """
    union_mask = np.logical_or(
        fixed_volume > reference_threshold,
        moving_volume > moving_threshold,
    )
    if int(np.count_nonzero(union_mask)) <= 1:
        return 0.0
    fixed_vals = fixed_volume[union_mask].astype(np.float64, copy=False)
    moving_vals = moving_volume[union_mask].astype(np.float64, copy=False)
    fixed_centered = fixed_vals - fixed_vals.mean()
    moving_centered = moving_vals - moving_vals.mean()
    denom = np.linalg.norm(fixed_centered) * np.linalg.norm(moving_centered)
    if denom <= 0:
        return 0.0
    return float(np.dot(fixed_centered, moving_centered) / denom)


class ExtractJsonView(APIView):
    def post(self, request, *args, **kwargs):
        json_path = request.data.get('path')
        print(json_path)

        if not json_path:
            return Response({'error': 'Missing required parameters'}, status=status.HTTP_400_BAD_REQUEST)

        if not os.path.isfile(json_path):
            return Response({'error': 'JSON file not found'}, status=status.HTTP_404_NOT_FOUND)

        try:
            with open(json_path, 'r') as file:
                json_data = json.load(file)

            scan_name = json_data.get('name')
            if not scan_name:
                scan_name = os.path.basename(json_path)[:-5] if os.path.basename(json_path).endswith('.json') else strip_nifti_basename(json_path)
                json_data['name'] = scan_name

            # Edit files on disk are authoritative; strip any legacy persisted lists.
            disk_had_ephemeral = any(key in json_data for key in ('edits', 'edits_masks', 'last_mesh_edit'))
            strip_ephemeral_scan_metadata(json_data)
            should_persist_metadata = disk_had_ephemeral

            edits_dir = os.path.dirname(json_path)
            is_preserved_mesh = json_data.get('is_mesh') is True and json_data.get('voxelized') is False
            edits = list_scan_edit_filenames(edits_dir, scan_name, is_preserved_mesh)
            edits_masks = (
                [] if is_preserved_mesh
                else list_scan_edit_mask_filenames(edits_dir, scan_name)
            )
            landmarks = [
                f for f in os.listdir(edits_dir)
                if f.startswith(scan_name) and (
                    f.endswith("landmarks.json") or f.endswith("landmark_distances.json")
                )
            ]

            if should_persist_metadata:
                with open(json_path, 'w') as jf:
                    json.dump(json_data, jf, indent=4)

            json_data['edits'] = sort_edit_filenames(edits)
            json_data['edits_masks'] = sort_edit_filenames(edits_masks)
            json_data['landmark_files'] = sorted(landmarks)
            json_data = enrich_builtin_texture_metadata(
                json_data,
                edits_dir,
                scan_name,
            )

            # Temporary legacy support: older metadata has 1-voxel landmark outliers
            # but not the newer 6-voxel counts. Derive them from saved distance files
            # while loading the bundle so the UI can use one consistent shape.
            landmarks_meta = json_data.get('landmarks')
            if isinstance(landmarks_meta, dict) and landmarks_meta.get('outliers') is not None and landmarks_meta.get('outliers_six') is None:
                edit_name = landmarks_meta.get('edit_name')
                candidate_distance_files = []
                if edit_name:
                    candidate_distance_files.append(f"{edit_name}_landmark_distances.json")
                candidate_distance_files.extend(
                    f for f in sorted(landmarks) if f.endswith("landmark_distances.json")
                )

                distances_dir = os.path.dirname(json_path)
                for distance_filename in dict.fromkeys(candidate_distance_files):
                    distances_path = os.path.join(distances_dir, distance_filename)
                    if not os.path.isfile(distances_path):
                        continue
                    try:
                        with open(distances_path, 'r') as distance_file:
                            distances_data = json.load(distance_file)

                        if isinstance(distances_data, dict):
                            distances = distances_data.get('distances')
                            snap_distance = distances_data.get('snap_distance')
                        else:
                            distances = distances_data
                            snap_distance = None

                        voxel_size = float(json_data.get('voxel_size'))
                        threshold_six = voxel_size * 6
                        if distances is not None:
                            distances_array = np.array(distances, dtype=float)
                            landmarks_meta['outliers_six'] = int(np.sum(distances_array > threshold_six))
                        if snap_distance is not None and landmarks_meta.get('snapped_outliers') is not None and landmarks_meta.get('snapped_outliers_six') is None:
                            snap_distance_array = np.array(snap_distance, dtype=float)
                            landmarks_meta['snapped_outliers_six'] = int(np.sum(snap_distance_array > threshold_six))
                        break
                    except Exception as legacy_error:
                        print(f"Could not derive legacy 6-voxel landmark metadata for {json_path}: {legacy_error}")

            # Check if the latest edit has guidepoints
            json_data['has_guidepoints'] = False
            latest_edit = 0
            while glob.glob(os.path.join(os.path.dirname(json_path), scan_name+"_edit_"+str(latest_edit)+"_*.nii.gz")):
                latest_edit += 1
            latest_edit -= 1
            if latest_edit >= 0:
                guidepoint_files = glob.glob(os.path.join(os.path.dirname(json_path), scan_name+"_edit_"+str(latest_edit)+"_*guidepoints.json"))
                if len(guidepoint_files) > 0:
                    if os.path.isfile(guidepoint_files[0]):
                        json_data['has_guidepoints'] = True
            elif latest_edit == -1:
                guidepoint_files = glob.glob(os.path.join(os.path.dirname(json_path), scan_name+"_guidepoints.json"))
                if len(guidepoint_files) > 0:
                    if os.path.isfile(guidepoint_files[0]):
                        json_data['has_guidepoints'] = True

            return Response(json_data, status=status.HTTP_200_OK)

        except Exception as e:
            return Response({'error': str(e)}, status=status.HTTP_500_INTERNAL_SERVER_ERROR)
        

