class DeleteScientificReportView(APIView):
    """Delete a Scientific Report template and its sidecars under extracted/."""

    def post(self, request):
        directory = request.data.get('directory')
        name = request.data.get('name', '')

        if not directory or not isinstance(directory, str):
            return Response({'error': 'directory is required'}, status=400)
        if not isinstance(name, str) or not name.strip():
            return Response({'error': 'name is required'}, status=400)

        safe_name = os.path.basename(name.strip()).replace('\\', '_').replace('/', '_')
        safe_name = safe_name.replace('\0', '')
        if safe_name.lower().endswith('.txt'):
            safe_name = safe_name[:-4]
        if safe_name.lower().endswith('.figures.json'):
            safe_name = safe_name[: -len('.figures.json')]
        if safe_name.lower().endswith('.vars.json'):
            safe_name = safe_name[: -len('.vars.json')]
        safe_name = ''.join(ch for ch in safe_name if ch.isalnum() or ch in (' ', '-', '_', '.')).strip()
        safe_name = safe_name.replace(' ', '_')
        if not safe_name:
            return Response({'error': 'invalid name'}, status=400)

        try:
            extracted_dir = os.path.join(directory, 'extracted')
            if not os.path.isdir(extracted_dir):
                return Response({'error': 'no extracted folder'}, status=400)

            extracted_real = os.path.realpath(extracted_dir)
            candidates = [
                os.path.join(extracted_dir, f'{safe_name}.txt'),
                os.path.join(extracted_dir, f'{safe_name}.vars.json'),
                os.path.join(extracted_dir, f'{safe_name}.figures.json'),
            ]
            deleted = []
            for path in candidates:
                real = os.path.realpath(path)
                if not real.startswith(extracted_real + os.sep):
                    return Response({'error': 'invalid path'}, status=400)
                if os.path.isfile(path):
                    os.remove(path)
                    deleted.append(os.path.basename(path))

            if not deleted:
                return Response({'error': 'template not found'}, status=404)

            return Response({
                'message': 'Scientific report template deleted',
                'name': safe_name,
                'deleted': deleted,
            })
        except Exception as e:
            return Response({'error': str(e)}, status=400)


class GetVersionView(APIView):
    def get(self, request):
        """
        Get the installed Aurora version by reading version.txt
        Works across Linux, Windows, and macOS
        """
        import os
        import sys
        
        try:
            system = sys.platform
            version_paths = []
            
            if system == 'linux':
                version_paths = ['/opt/aurora-tools/version.txt']
            elif system == 'win32':
                local_app_data = os.environ.get('LOCALAPPDATA')
                
                if local_app_data:
                    version_paths.append(os.path.join(local_app_data, 'Aurora', 'version.txt'))
                
                home_dir = os.path.expanduser('~')
                version_paths.append(os.path.join(home_dir, 'AppData', 'Local', 'Aurora', 'version.txt'))
                
            elif system == 'darwin':
                version_paths = ['/Library/Application Support/Aurora/version.txt']
            
            for version_path in version_paths:
                if version_path and os.path.exists(version_path):
                    try:
                        with open(version_path, 'r') as f:
                            version = f.read().strip()
                        if version:
                            return Response({
                                'version': version,
                                'status': 'installed'
                            })
                    except Exception as read_error:
                        continue
            
            return Response({
                'version': None,
                'status': 'not_installed'
            })
            
        except Exception as e:
            return Response({
                'error': str(e),
                'status': 'error'
            }, status=500)

class ExportLandmarksView(APIView):
    def post(self, request, *args, **kwargs):
        try:
            
            # Extract directory from request
            directory = request.data.get('directory')
            
            print(f"Exporting landmarks from directory: {directory}")
            
            if not directory:
                return Response(
                    {'error': 'No directory provided'},
                    status=status.HTTP_400_BAD_REQUEST
                )
            
            # Get all scans from the extracted directory
            extracted_dir = os.path.join(directory, "extracted")
            if not os.path.exists(extracted_dir):
                return Response(
                    {'error': 'No extracted directory found'},
                    status=status.HTTP_400_BAD_REQUEST
                )
            
            scans = [d for d in os.listdir(extracted_dir) 
                    if os.path.isdir(os.path.join(extracted_dir, d))]
            
            print(f"Found {len(scans)} scans")
            
            if not scans:
                return Response(
                    {'error': 'No scans found in extracted directory'},
                    status=status.HTTP_400_BAD_REQUEST
                )
            
            # Collect all landmarks data
            all_data = []
            
            for scan_name in scans:
                sub_path = os.path.join(extracted_dir, scan_name)
                
                # Check if scan metadata exists and is not faulty
                metadata_path = os.path.join(sub_path, f"{scan_name}.json")
                if not os.path.exists(metadata_path):
                    print(f"Skipping {scan_name}: no metadata found")
                    continue
                
                try:
                    with open(metadata_path, 'r') as jf:
                        metadata = json.load(jf)
                    
                    # Skip faulty scans
                    if metadata.get('faulty', False):
                        print(f"Skipping {scan_name}: marked as faulty")
                        continue
                except (json.JSONDecodeError, FileNotFoundError):
                    print(f"Skipping {scan_name}: could not read metadata")
                    continue
                
                # Find the latest landmarks file for this scan
                landmarks_files = glob.glob(os.path.join(sub_path, f"{scan_name}*_landmarks.json"))
                
                if not landmarks_files:
                    print(f"No landmarks found for scan {scan_name}")
                    continue
                
                # Sort to get the latest edit (by modification time)
                latest_landmarks_file = sorted(landmarks_files, key=os.path.getmtime)[-1]
                
                try:
                    with open(latest_landmarks_file, 'r') as jf:
                        landmarks = json.load(jf)
                    
                    # Handle both old and new formats
                    if isinstance(landmarks, list):
                        # Check if it's new format (list of dicts with position and landmark_type)
                        if len(landmarks) > 0 and isinstance(landmarks[0], dict) and 'position' in landmarks[0]:
                            # New format: prepend semi_ for semilandmarks (landmark_type == "semi")
                            landmarks_dict = {}
                            for i, lm in enumerate(landmarks):
                                prefix = "semi_" if lm.get('landmark_type') == 'semi' else ""
                                landmarks_dict[f"{prefix}landmark_{i}"] = lm['position']
                        else:
                            # Old format: list of coordinate arrays
                            landmarks_dict = {f"landmark_{i}": coord for i, coord in enumerate(landmarks)}
                    else:
                        # Dict format (legacy?)
                        landmarks_dict = landmarks
                    
                    if landmarks_dict:
                        # Create a row for this scan
                        row = {'Subject': scan_name}
                        
                        # Extract x, y, z for each landmark
                        for lm_name, coord in landmarks_dict.items():
                            if isinstance(coord, (list, tuple)) and len(coord) >= 3:
                                row[f'{lm_name}_x'] = coord[0]
                                row[f'{lm_name}_y'] = coord[1]
                                row[f'{lm_name}_z'] = coord[2]
                        
                        all_data.append(row)
                        print(f"Loaded landmarks from {scan_name}: {len(landmarks_dict)} landmarks")
                
                except (json.JSONDecodeError, FileNotFoundError):
                    print(f"Could not read landmarks file: {latest_landmarks_file}")
                    continue
            
            print(f"Collected landmarks from {len(all_data)} scans")
            
            if not all_data:
                return Response(
                    {'error': 'No landmarks found in any scans'},
                    status=status.HTTP_400_BAD_REQUEST
                )
            
            # Create DataFrame from collected data
            df = pd.DataFrame(all_data)
            
            # Fill missing values with empty string
            df = df.fillna('')
            
            print(f"DataFrame shape: {df.shape}")
            print(f"Columns: {df.columns.tolist()}")
            
            # Create temporary file for response
            temp_dir = os.path.join(directory, '.temp')
            os.makedirs(temp_dir, exist_ok=True)
            
            csv_filename = f"landmarks_export_{datetime.now().strftime('%Y%m%d_%H%M%S')}.csv"
            csv_path = os.path.join(temp_dir, csv_filename)
            
            print(f"Writing CSV to temporary file: {csv_path}")
            # Use pandas to write CSV (simpler and more robust)
            df.to_csv(csv_path, index=False)
            
            # Prepare response with file
            print(f"Sending CSV file to client")
            response = FileResponse(
                open(csv_path, 'rb'),
                as_attachment=True,
                filename=csv_filename,
                content_type='text/csv'
            )
            response['Content-Length'] = os.path.getsize(csv_path)
            
            return response
            
        except Exception as e:
            error_message = f"Error exporting landmarks: {str(e)}"
            print(error_message)
            import traceback
            print(traceback.format_exc())
            return Response(
                {'error': error_message},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR
            )


class ExportLandmarkDistancesView(APIView):
    """
    Export landmark distance data as a ZIP containing up to two CSVs:
    - Surface distances (pre-snap): distance from each landmark to mesh surface (proxy for uncertainty).
    - Snap distances (post-snap): how far each landmark moved when snapped to mesh (only if available).
    """
    def post(self, request, *args, **kwargs):
        try:
            directory = request.data.get('directory')
            print(f"Exporting landmark distances from directory: {directory}")

            if not directory:
                return Response(
                    {'error': 'No directory provided'},
                    status=status.HTTP_400_BAD_REQUEST
                )

            extracted_dir = os.path.join(directory, "extracted")
            if not os.path.exists(extracted_dir):
                return Response(
                    {'error': 'No extracted directory found'},
                    status=status.HTTP_400_BAD_REQUEST
                )

            scans = [d for d in os.listdir(extracted_dir)
                    if os.path.isdir(os.path.join(extracted_dir, d))]

            if not scans:
                return Response(
                    {'error': 'No scans found in extracted directory'},
                    status=status.HTTP_400_BAD_REQUEST
                )

            surface_data = []
            snap_data = []
            max_landmarks = 0

            for scan_name in scans:
                sub_path = os.path.join(extracted_dir, scan_name)

                metadata_path = os.path.join(sub_path, f"{scan_name}.json")
                if not os.path.exists(metadata_path):
                    print(f"Skipping {scan_name}: no metadata found")
                    continue

                try:
                    with open(metadata_path, 'r') as jf:
                        metadata = json.load(jf)
                    if metadata.get('faulty', False):
                        print(f"Skipping {scan_name}: marked as faulty")
                        continue
                except (json.JSONDecodeError, FileNotFoundError):
                    print(f"Skipping {scan_name}: could not read metadata")
                    continue

                landmarks_files = glob.glob(os.path.join(sub_path, f"{scan_name}*_landmarks.json"))
                if not landmarks_files:
                    continue

                latest_landmarks_file = sorted(landmarks_files, key=os.path.getmtime)[-1]
                distances_path = latest_landmarks_file.replace("_landmarks.json", "_landmark_distances.json")
                if not os.path.exists(distances_path):
                    print(f"No distances file for {scan_name}")
                    continue

                # Load landmarks to get landmark_type per index (for semi_ column names)
                landmark_types = []
                try:
                    with open(latest_landmarks_file, 'r') as jf:
                        lm_data = json.load(jf)
                    if isinstance(lm_data, list) and len(lm_data) > 0 and isinstance(lm_data[0], dict) and 'position' in lm_data[0]:
                        landmark_types = [lm.get('landmark_type', 'main') for lm in lm_data]
                except (json.JSONDecodeError, FileNotFoundError):
                    pass

                try:
                    with open(distances_path, 'r') as jf:
                        data = json.load(jf)
                except (json.JSONDecodeError, FileNotFoundError):
                    print(f"Could not read distances file: {distances_path}")
                    continue

                # Normalise: plain list vs dict with 'distances' and optional 'snap_distance'
                if isinstance(data, list):
                    surface_dists = data
                    snap_dists = None
                else:
                    surface_dists = data.get('distances', [])
                    snap_dists = data.get('snap_distance')

                if not surface_dists:
                    continue

                n_lm = len(surface_dists)
                max_landmarks = max(max_landmarks, n_lm)

                def _lm_col(i):
                    return f"semi_landmark_{i}" if i < len(landmark_types) and landmark_types[i] == 'semi' else f"landmark_{i}"

                surface_row = {'Subject': scan_name}
                for i, d in enumerate(surface_dists):
                    surface_row[_lm_col(i)] = d
                surface_data.append(surface_row)

                if snap_dists is not None and len(snap_dists) == n_lm:
                    snap_row = {'Subject': scan_name}
                    for i, d in enumerate(snap_dists):
                        snap_row[_lm_col(i)] = d
                    snap_data.append(snap_row)

            if not surface_data:
                return Response(
                    {'error': 'No landmark distance data found in any scans'},
                    status=status.HTTP_400_BAD_REQUEST
                )

            # Determine landmark_types from first scan with data (should be consistent across scans)
            inferred_landmark_types = []
            for row in surface_data:
                cols = [c for c in row.keys() if c != 'Subject']
                for col in cols:
                    if col.startswith('semi_landmark_'):
                        idx = int(col.replace('semi_landmark_', ''))
                        while len(inferred_landmark_types) <= idx:
                            inferred_landmark_types.append('main')
                        inferred_landmark_types[idx] = 'semi'
                    elif col.startswith('landmark_'):
                        idx = int(col.replace('landmark_', ''))
                        while len(inferred_landmark_types) <= idx:
                            inferred_landmark_types.append('main')
                        if inferred_landmark_types[idx] != 'semi':
                            inferred_landmark_types[idx] = 'main'
                break

            # Column order: Subject, then landmark column per index (name determined by type)
            surface_cols = ['Subject'] + [f"semi_landmark_{i}" if (i < len(inferred_landmark_types) and inferred_landmark_types[i] == 'semi') else f"landmark_{i}" for i in range(max_landmarks)]
            surface_df = pd.DataFrame(surface_data)
            surface_df = surface_df.reindex(columns=surface_cols)
            surface_df = surface_df.fillna('')

            temp_dir = os.path.join(directory, '.temp')
            os.makedirs(temp_dir, exist_ok=True)
            ts = datetime.now().strftime('%Y%m%d_%H%M%S')
            dir_basename = os.path.basename(directory.rstrip(os.sep)) or 'export'
            surface_filename = f"{dir_basename}_current_surface_distances.csv"
            surface_path = os.path.join(temp_dir, surface_filename)
            surface_df.to_csv(surface_path, index=False)

            zip_filename = f"landmark_distances_{ts}.zip"
            zip_path = os.path.join(temp_dir, zip_filename)

            with zipfile.ZipFile(zip_path, 'w', zipfile.ZIP_DEFLATED) as zf:
                zf.write(surface_path, arcname=surface_filename)
                if snap_data:
                    snap_cols = ['Subject'] + [f"semi_landmark_{i}" if (i < len(inferred_landmark_types) and inferred_landmark_types[i] == 'semi') else f"landmark_{i}" for i in range(max_landmarks)]
                    snap_df = pd.DataFrame(snap_data)
                    snap_df = snap_df.reindex(columns=snap_cols)
                    snap_df = snap_df.fillna('')
                    snap_filename = f"{dir_basename}_pre_snap_distances.csv"
                    snap_path = os.path.join(temp_dir, snap_filename)
                    snap_df.to_csv(snap_path, index=False)
                    zf.write(snap_path, arcname=snap_filename)
                    try:
                        os.remove(snap_path)
                    except OSError:
                        pass

            try:
                os.remove(surface_path)
            except OSError:
                pass

            response = FileResponse(
                open(zip_path, 'rb'),
                as_attachment=True,
                filename=zip_filename,
                content_type='application/zip'
            )
            response['Content-Length'] = os.path.getsize(zip_path)
            return response

        except Exception as e:
            error_message = f"Error exporting landmark distances: {str(e)}"
            print(error_message)
            import traceback
            print(traceback.format_exc())
            return Response(
                {'error': error_message},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR
            )


class ExportLandmarksBundleView(APIView):
    """
    Export all landmark data in a single ZIP: coordinates CSV plus surface and
    (if available) snap distance CSVs. One request, one download.
    """
    def post(self, request, *args, **kwargs):
        try:
            directory = request.data.get('directory')
            print(f"Exporting landmarks bundle from directory: {directory}")

            if not directory:
                return Response(
                    {'error': 'No directory provided'},
                    status=status.HTTP_400_BAD_REQUEST
                )

            extracted_dir = os.path.join(directory, "extracted")
            if not os.path.exists(extracted_dir):
                return Response(
                    {'error': 'No extracted directory found'},
                    status=status.HTTP_400_BAD_REQUEST
                )

            scans = [d for d in os.listdir(extracted_dir)
                    if os.path.isdir(os.path.join(extracted_dir, d))]

            if not scans:
                return Response(
                    {'error': 'No scans found in extracted directory'},
                    status=status.HTTP_400_BAD_REQUEST
                )

            coordinates_data = []
            surface_data = []
            snap_data = []
            max_landmarks = 0

            for scan_name in scans:
                sub_path = os.path.join(extracted_dir, scan_name)

                metadata_path = os.path.join(sub_path, f"{scan_name}.json")
                if not os.path.exists(metadata_path):
                    print(f"Skipping {scan_name}: no metadata found")
                    continue

                try:
                    with open(metadata_path, 'r') as jf:
                        metadata = json.load(jf)
                    if metadata.get('faulty', False):
                        print(f"Skipping {scan_name}: marked as faulty")
                        continue
                except (json.JSONDecodeError, FileNotFoundError):
                    print(f"Skipping {scan_name}: could not read metadata")
                    continue

                landmarks_files = glob.glob(os.path.join(sub_path, f"{scan_name}*_landmarks.json"))
                if not landmarks_files:
                    continue

                latest_landmarks_file = sorted(landmarks_files, key=os.path.getmtime)[-1]

                # --- Coordinates (same format as ExportLandmarksView, with semi_ for semilandmarks) ---
                try:
                    with open(latest_landmarks_file, 'r') as jf:
                        landmarks = json.load(jf)
                    if isinstance(landmarks, list):
                        if len(landmarks) > 0 and isinstance(landmarks[0], dict) and 'position' in landmarks[0]:
                            landmarks_dict = {}
                            for i, lm in enumerate(landmarks):
                                prefix = "semi_" if lm.get('landmark_type') == 'semi' else ""
                                landmarks_dict[f"{prefix}landmark_{i}"] = lm['position']
                        else:
                            landmarks_dict = {f"landmark_{i}": coord for i, coord in enumerate(landmarks)}
                    else:
                        landmarks_dict = landmarks

                    if landmarks_dict:
                        row = {'Subject': scan_name}
                        for lm_name, coord in landmarks_dict.items():
                            if isinstance(coord, (list, tuple)) and len(coord) >= 3:
                                row[f'{lm_name}_x'] = coord[0]
                                row[f'{lm_name}_y'] = coord[1]
                                row[f'{lm_name}_z'] = coord[2]
                        coordinates_data.append(row)
                except (json.JSONDecodeError, FileNotFoundError):
                    print(f"Could not read landmarks file: {latest_landmarks_file}")
                    continue

                # --- Distances (same logic as ExportLandmarkDistancesView, with semi_ for semilandmarks) ---
                distances_path = latest_landmarks_file.replace("_landmarks.json", "_landmark_distances.json")
                if not os.path.exists(distances_path):
                    continue

                # landmark_types from landmarks (list of dicts) loaded above in coordinates block
                landmark_types = []
                if isinstance(landmarks, list) and len(landmarks) > 0 and isinstance(landmarks[0], dict) and 'position' in landmarks[0]:
                    landmark_types = [lm.get('landmark_type', 'main') for lm in landmarks]

                try:
                    with open(distances_path, 'r') as jf:
                        data = json.load(jf)
                except (json.JSONDecodeError, FileNotFoundError):
                    continue

                if isinstance(data, list):
                    surface_dists = data
                    snap_dists = None
                else:
                    surface_dists = data.get('distances', [])
                    snap_dists = data.get('snap_distance')

                if not surface_dists:
                    continue

                n_lm = len(surface_dists)
                max_landmarks = max(max_landmarks, n_lm)

                def _lm_col(i):
                    return f"semi_landmark_{i}" if i < len(landmark_types) and landmark_types[i] == 'semi' else f"landmark_{i}"

                surface_row = {'Subject': scan_name}
                for i, d in enumerate(surface_dists):
                    surface_row[_lm_col(i)] = d
                surface_data.append(surface_row)

                if snap_dists is not None and len(snap_dists) == n_lm:
                    snap_row = {'Subject': scan_name}
                    for i, d in enumerate(snap_dists):
                        snap_row[_lm_col(i)] = d
                    snap_data.append(snap_row)

            if not coordinates_data:
                return Response(
                    {'error': 'No landmarks found in any scans'},
                    status=status.HTTP_400_BAD_REQUEST
                )

            # Infer landmark_types from first scan with distance data (consistency check)
            inferred_landmark_types = []
            if surface_data:
                for row in surface_data:
                    cols = [c for c in row.keys() if c != 'Subject']
                    for col in cols:
                        if col.startswith('semi_landmark_'):
                            idx = int(col.replace('semi_landmark_', ''))
                            while len(inferred_landmark_types) <= idx:
                                inferred_landmark_types.append('main')
                            inferred_landmark_types[idx] = 'semi'
                        elif col.startswith('landmark_'):
                            idx = int(col.replace('landmark_', ''))
                            while len(inferred_landmark_types) <= idx:
                                inferred_landmark_types.append('main')
                            if inferred_landmark_types[idx] != 'semi':
                                inferred_landmark_types[idx] = 'main'
                    break

            temp_dir = os.path.join(directory, '.temp')
            os.makedirs(temp_dir, exist_ok=True)
            ts = datetime.now().strftime('%Y%m%d_%H%M%S')
            dir_basename = os.path.basename(directory.rstrip(os.sep)) or 'export'
            zip_filename = f"landmarks_export_{ts}.zip"
            zip_path = os.path.join(temp_dir, zip_filename)

            with zipfile.ZipFile(zip_path, 'w', zipfile.ZIP_DEFLATED) as zf:
                # 1. Coordinates CSV (always)
                coords_df = pd.DataFrame(coordinates_data).fillna('')
                landmarks_filename = f"{dir_basename}_landmarks.csv"
                landmarks_path = os.path.join(temp_dir, landmarks_filename)
                coords_df.to_csv(landmarks_path, index=False)
                zf.write(landmarks_path, arcname=landmarks_filename)
                try:
                    os.remove(landmarks_path)
                except OSError:
                    pass

                # 2. Surface distances CSV (if any)
                if surface_data:
                    surface_cols = ['Subject'] + [f"semi_landmark_{i}" if (i < len(inferred_landmark_types) and inferred_landmark_types[i] == 'semi') else f"landmark_{i}" for i in range(max_landmarks)]
                    surface_df = pd.DataFrame(surface_data).reindex(columns=surface_cols).fillna('')
                    surface_filename = f"{dir_basename}_current_surface_distances.csv"
                    surface_path = os.path.join(temp_dir, surface_filename)
                    surface_df.to_csv(surface_path, index=False)
                    zf.write(surface_path, arcname=surface_filename)
                    try:
                        os.remove(surface_path)
                    except OSError:
                        pass

                # 3. Snap distances CSV (if any)
                if snap_data:
                    snap_cols = ['Subject'] + [f"semi_landmark_{i}" if (i < len(inferred_landmark_types) and inferred_landmark_types[i] == 'semi') else f"landmark_{i}" for i in range(max_landmarks)]
                    snap_df = pd.DataFrame(snap_data).reindex(columns=snap_cols).fillna('')
                    snap_filename = f"{dir_basename}_pre_snap_distances.csv"
                    snap_path = os.path.join(temp_dir, snap_filename)
                    snap_df.to_csv(snap_path, index=False)
                    zf.write(snap_path, arcname=snap_filename)
                    try:
                        os.remove(snap_path)
                    except OSError:
                        pass

            response = FileResponse(
                open(zip_path, 'rb'),
                as_attachment=True,
                filename=zip_filename,
                content_type='application/zip'
            )
            response['Content-Length'] = os.path.getsize(zip_path)
            return response

        except Exception as e:
            error_message = f"Error exporting landmarks bundle: {str(e)}"
            print(error_message)
            import traceback
            print(traceback.format_exc())
            return Response(
                {'error': error_message},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR
            )


class ExportLandmarksJsonView(APIView):
    """
    Export all landmark coordinates as a single JSON file.

    Structure:
    {
        "scan_name": {
            "landmark_0":      [x, y, z],
            "semi_landmark_1": [x, y, z],
            ...
        },
        ...
    }

    Skips faulty scans. Uses the most recently modified landmarks file per scan.
    """
    def post(self, request, *args, **kwargs):
        try:
            directory = request.data.get('directory')
            print(f"Exporting landmarks as JSON from directory: {directory}")

            if not directory:
                return Response(
                    {'error': 'No directory provided'},
                    status=status.HTTP_400_BAD_REQUEST
                )

            extracted_dir = os.path.join(directory, "extracted")
            if not os.path.exists(extracted_dir):
                return Response(
                    {'error': 'No extracted directory found'},
                    status=status.HTTP_400_BAD_REQUEST
                )

            scans = [d for d in os.listdir(extracted_dir)
                     if os.path.isdir(os.path.join(extracted_dir, d))]

            if not scans:
                return Response(
                    {'error': 'No scans found in extracted directory'},
                    status=status.HTTP_400_BAD_REQUEST
                )

            scans.sort()

            export_data = {}

            for scan_name in scans:
                sub_path = os.path.join(extracted_dir, scan_name)

                metadata_path = os.path.join(sub_path, f"{scan_name}.json")
                if not os.path.exists(metadata_path):
                    print(f"Skipping {scan_name}: no metadata found")
                    continue

                try:
                    with open(metadata_path, 'r') as jf:
                        metadata = json.load(jf)
                    if metadata.get('faulty', False):
                        print(f"Skipping {scan_name}: marked as faulty")
                        continue
                except (json.JSONDecodeError, FileNotFoundError):
                    print(f"Skipping {scan_name}: could not read metadata")
                    continue

                landmarks_files = glob.glob(os.path.join(sub_path, f"{scan_name}*_landmarks.json"))
                if not landmarks_files:
                    continue

                latest_landmarks_file = sorted(landmarks_files, key=os.path.getmtime)[-1]

                try:
                    with open(latest_landmarks_file, 'r') as jf:
                        landmarks = json.load(jf)

                    if isinstance(landmarks, list):
                        if len(landmarks) > 0 and isinstance(landmarks[0], dict) and 'position' in landmarks[0]:
                            scan_landmarks = {}
                            for i, lm in enumerate(landmarks):
                                prefix = "semi_" if lm.get('landmark_type') == 'semi' else ""
                                key = f"{prefix}landmark_{i}"
                                scan_landmarks[key] = lm['position']
                        else:
                            scan_landmarks = {
                                f"landmark_{i}": coord
                                for i, coord in enumerate(landmarks)
                            }
                    else:
                        scan_landmarks = landmarks

                    if scan_landmarks:
                        export_data[scan_name] = scan_landmarks
                        print(f"Loaded {len(scan_landmarks)} landmarks from {scan_name}")

                except (json.JSONDecodeError, FileNotFoundError):
                    print(f"Could not read landmarks file: {latest_landmarks_file}")
                    continue

            if not export_data:
                return Response(
                    {'error': 'No landmarks found in any scans'},
                    status=status.HTTP_400_BAD_REQUEST
                )

            temp_dir = os.path.join(directory, '.temp')
            os.makedirs(temp_dir, exist_ok=True)

            ts = datetime.now().strftime('%Y%m%d_%H%M%S')
            dir_basename = os.path.basename(directory.rstrip(os.sep)) or 'export'
            json_filename = f"{dir_basename}_landmarks_{ts}.json"
            json_path = os.path.join(temp_dir, json_filename)

            with open(json_path, 'w') as jf:
                json.dump(export_data, jf, indent=2)

            response = FileResponse(
                open(json_path, 'rb'),
                as_attachment=True,
                filename=json_filename,
                content_type='application/json'
            )
            response['Content-Length'] = os.path.getsize(json_path)
            return response

        except Exception as e:
            error_message = f"Error exporting landmarks as JSON: {str(e)}"
            print(error_message)
            import traceback
            print(traceback.format_exc())
            return Response(
                {'error': error_message},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR
            )


class ClearIntermediateFilesView(APIView):
    """
    Clears intermediate files from completed subjects to save storage space.
    
    This view will:
    1. Find all subjects that have completed elastic transformation
    2. Delete all subjects marked as faulty from extracted/
    3. Move raw counterparts of deleted faulty subjects into directory/faulty/
       (creates faulty/ if non-existing; matches any file or folder whose name equals
       the subject or starts with subject followed by . or _)
    4. For non-faulty completed subjects:
       - Keep the elastic transformation edit and one edit before it
       - Delete all other intermediate edits
       - Preserve original files
       - Update metadata JSON to keep only the last two lossy_compression entries
    5. Keep all other metadata intact
    
    This operation is irreversible and locks in the final results.
    To regenerate intermediate steps, users must rerun from original files.
    """
    
    def post(self, request, *args, **kwargs):
        try:
            directory = request.data.get('directory')
            
            if not directory or not os.path.exists(directory):
                return Response({
                    'error': 'Invalid directory path'
                }, status=status.HTTP_400_BAD_REQUEST)
            
            extracted_path = os.path.join(directory, "extracted")
            if not os.path.exists(extracted_path):
                return Response({
                    'error': 'No extracted subjects found'
                }, status=status.HTTP_404_NOT_FOUND)
            
            # Get all subjects
            subjects = [d for d in os.listdir(extracted_path) 
                       if os.path.isdir(os.path.join(extracted_path, d)) 
                       and d != "atlas"]
            
            total_subjects = len(subjects)
            processed_count = 0
            deleted_faulty_count = 0
            deleted_faulty_subjects = []  # names of subjects deleted from extracted (for moving raw to faulty)
            cleaned_count = 0
            skipped_count = 0
            total_space_freed = 0  # in bytes
            
            # Setup WebSocket for progress updates
            channel_layer = get_channel_layer()
            
            print(f"Processing {total_subjects} subjects...")
            
            for idx, subject in enumerate(subjects):
                subject_path = os.path.join(extracted_path, subject)
                json_path = os.path.join(subject_path, f"{subject}.json")
                
                # Send progress update
                if channel_layer is not None:
                    async_to_sync(channel_layer.group_send)(
                        "progress",
                        {
                            "type": "progress_update",
                            "total": total_subjects,
                            "current": idx + 1,
                            "scan_name": subject,
                            "progress": (idx + 1) / total_subjects,
                            "custom_message": f"Processing subject {idx + 1}/{total_subjects}"
                        }
                    )
                
                # Load metadata
                if not os.path.exists(json_path):
                    print(f"No metadata found for {subject}, skipping...")
                    skipped_count += 1
                    continue
                
                try:
                    with open(json_path, 'r') as jf:
                        metadata = json.load(jf)
                except json.JSONDecodeError:
                    print(f"Corrupted metadata for {subject}, skipping...")
                    skipped_count += 1
                    continue
                
                # Check if subject is marked as faulty
                if metadata.get('faulty', False):
                    print(f"Deleting faulty subject: {subject}")
                    
                    # Calculate space before deletion
                    subject_size = 0
                    for root, dirs, files in os.walk(subject_path):
                        for f in files:
                            fp = os.path.join(root, f)
                            if os.path.exists(fp):
                                subject_size += os.path.getsize(fp)
                    
                    # Delete entire subject directory
                    shutil.rmtree(subject_path)
                    deleted_faulty_count += 1
                    deleted_faulty_subjects.append(subject)
                    total_space_freed += subject_size
                    processed_count += 1
                    continue
                
                # Find all edit files
                all_files = os.listdir(subject_path)
                
                # Find the latest elastic edit number
                elastic_edit_number = -1
                for filename in all_files:
                    if "_elastic" in filename and "_edit_" in filename:
                        try:
                            match = re.search(r'_edit_(\d+)_', filename)
                            if match:
                                edit_num = int(match.group(1))
                                elastic_edit_number = max(elastic_edit_number, edit_num)
                        except (IndexError, ValueError):
                            continue
                
                # If no elastic transformation found, skip this subject
                if elastic_edit_number == -1:
                    print(f"No elastic transformation found for {subject}, skipping...")
                    skipped_count += 1
                    processed_count += 1
                    continue
                
                print(f"Processing completed subject: {subject} (elastic edit: {elastic_edit_number})")
                
                # Determine which edits to keep (elastic and one before)
                edits_to_keep = {elastic_edit_number}
                if elastic_edit_number > 0:
                    edits_to_keep.add(elastic_edit_number - 1)
                
                print(f"  Keeping edits: {sorted(edits_to_keep)}")
                
                # Find all files to potentially delete
                files_to_delete = []
                lossy_files_to_keep = set()
                
                for filename in all_files:
                    # Skip metadata and original files
                    if filename.endswith('.json') or filename == f"{subject}.nii.gz" or filename == f"{subject}_lossy.nii.gz":
                        continue
                    
                    # Check if it's an edit file
                    if "_edit_" in filename:
                        try:
                            match = re.search(r'_edit_(\d+)_', filename)
                            if match:
                                edit_num = int(match.group(1))
                                if edit_num not in edits_to_keep:
                                    files_to_delete.append(filename)
                                else:
                                    # Track lossy files we're keeping
                                    if "_lossy_edit_" in filename and filename.endswith('.nii.gz'):
                                        lossy_files_to_keep.add(filename)
                        except (IndexError, ValueError):
                            continue
                
                # Delete the intermediate files
                space_freed_subject = 0
                for filename in files_to_delete:
                    file_path = os.path.join(subject_path, filename)
                    if os.path.exists(file_path):
                        file_size = os.path.getsize(file_path)
                        os.remove(file_path)
                        space_freed_subject += file_size
                        print(f"  Deleted: {filename} ({file_size / (1024*1024):.2f} MB)")
                
                total_space_freed += space_freed_subject
                
                # Update metadata - keep only lossy_compression entries for kept files
                if 'lossy_compression' in metadata:
                    lossy_compression = metadata['lossy_compression']
                    
                    # Normalize to list format
                    if isinstance(lossy_compression, dict):
                        lossy_compression = [lossy_compression]
                    
                    # Filter to keep only entries for files we're keeping
                    updated_lossy_compression = []
                    
                    # Always keep the base lossy file entry if it exists
                    for entry in lossy_compression:
                        entry_filename = entry.get('filename', '')
                        if entry_filename == f"{subject}_lossy.nii.gz":
                            updated_lossy_compression.append(entry)
                            break
                    
                    # Keep only the last two edit entries (elastic and one before)
                    edit_entries = []
                    for entry in lossy_compression:
                        entry_filename = entry.get('filename', '')
                        if "_lossy_edit_" in entry_filename and entry_filename in lossy_files_to_keep:
                            edit_entries.append(entry)
                    
                    # Sort by edit number and keep last two
                    def extract_edit_num(entry):
                        filename = entry.get('filename', '')
                        match = re.search(r'_edit_(\d+)_', filename)
                        return int(match.group(1)) if match else -1
                    
                    edit_entries.sort(key=extract_edit_num)
                    updated_lossy_compression.extend(edit_entries[-2:])  # Keep last two
                    
                    metadata['lossy_compression'] = updated_lossy_compression
                    
                    # Save updated metadata
                    with open(json_path, 'w') as jf:
                        json.dump(metadata, jf, indent=4)
                    
                    print(f"  Updated metadata: kept {len(updated_lossy_compression)} lossy_compression entries")
                
                cleaned_count += 1
                processed_count += 1
            
            # Move raw counterparts of deleted faulty subjects into faulty folder
            # Raw can be any file or folder whose name matches the subject (exact or at start)
            faulty_path = os.path.join(directory, "faulty")
            raw_moved_to_faulty = 0
            if deleted_faulty_subjects:
                os.makedirs(faulty_path, exist_ok=True)
                skip_dirs = {"extracted", "atlas", "faulty", ".temp", ".Trash-1000"}
                try:
                    root_entries = [e for e in os.listdir(directory) if e not in skip_dirs and not e.startswith(".")]
                except OSError:
                    root_entries = []
                for subject in deleted_faulty_subjects:
                    for name in root_entries:
                        if not (name == subject or name.startswith(subject)):
                            continue                        
                        src = os.path.join(directory, name)
                        dest = os.path.join(faulty_path, name)
                        if os.path.exists(dest):
                            continue
                        shutil.move(src, dest)
                        raw_moved_to_faulty += 1
                        print(f"Moved raw to faulty: {name}")
                    # Remove moved entries from root_entries so we don't try to match again
                    root_entries = [e for e in root_entries if os.path.exists(os.path.join(directory, e))]
            
            # Final summary
            space_freed_gb = total_space_freed / (1024**3)
            
            message = (
                f"Intermediate file cleanup completed!\n"
                f"Processed: {processed_count}/{total_subjects} subjects\n"
                f"Deleted faulty subjects: {deleted_faulty_count}\n"
                f"Cleaned completed subjects: {cleaned_count}\n"
                f"Skipped (incomplete): {skipped_count}\n"
                f"Total space freed: {space_freed_gb:.2f} GB"
            )
            if raw_moved_to_faulty:
                message += f"\nMoved {raw_moved_to_faulty} raw counterpart(s) to faulty/"
            
            print(message)
            
            return Response({
                'message': message,
                'processed': processed_count,
                'deleted_faulty': deleted_faulty_count,
                'raw_moved_to_faulty': raw_moved_to_faulty,
                'cleaned': cleaned_count,
                'skipped': skipped_count,
                'space_freed_gb': round(space_freed_gb, 2)
            }, status=status.HTTP_200_OK)
            
        except Exception as e:
            print(f"Error in ClearIntermediateFilesView: {str(e)}")
            import traceback
            traceback.print_exc()
            return Response({
                'error': f'Failed to clear intermediate files: {str(e)}'
            }, status=status.HTTP_500_INTERNAL_SERVER_ERROR)

            